window.POETRY_REGISTER("v4-poems-424.js",{"records":[["陇麦高低径路斜，小池杨柳带人家。\n东菑午饷柴门静，一犬篱根卧落花。",""],["山路初晴槲叶香，青林赤碛带横冈。\n玉隆山后平田少，柳下人家是石塘。",""],["风翮霜毛劲气多，清秋一点过新罗。\n飞栖不定还惊顾，奈尔山田野雀何。",""],["池南欹柳燕将雏，门巷新晴转绿芜。\n花隔小窗人不到，一帘香雾斗摴蒱。",""],["武山曾共赋仙游，按节传觞夜不休。\n恨杀春寒花雨湿，时时吹笛上西楼。",""],["昔人城里筑基牢，撤屋新来又作濠。\n濠底土为城上土，到头谁下复谁高。",""],["银烛频烧夜宴迟，晨光忽觉转檐枝。\n幽人欲起还中酒，卧听西斋读杜诗。",""],["披图如见锦袍仙，正咏银河落九天。\n百叠云屏烟雾里，石梁听雪定何年。",""],["最忆梨花白雪香，春深千树锁昭阳。\n画图惊见东风面，独拥红绡试浅妆。",""],["孙公墩在水南村，乱后重来已闭门。\n壁上残诗犹可读，令人还忆醉时尊。",""],["天星堕地气如虹，深映萧萧玉一丛。\n草满汉宫秋露冷，金茎双出月明中。",""],["经旬不见邓郎过，入手新诗意气多。\n政是珠林秋雨过，水清沙白见微波。",""],["沙泥拓额最堪悲，纱帽笼头又一时。\n可怜画史寻常意，不写当年月蚀诗。",""],["溪泉依旧石泉通，故旧飘零土室空。\n却忆清江刘处士，曾同绝顶坐松风。",""],["金粟庄前白雁翔，十年嶷嶷见诸郎。\n重来往事那堪赋，依旧当门杏叶黄。",""],["十载安危此地分，豺狼一旦自成群。\n烽烟江上愁回首，只向深山望白云。",""],["万折千萦度远山，举家筋力尽跻攀。\n喜闻故友山中近，却望前峰一解颜。",""],["华屋娉婷步履轻，乱来几日窜荆榛。\n官兵驱入牛羊队，直过江南闻哭声。",""],["朝火南村暮北村，千家今有几家存。\n君看道路累累者，总是承平长育恩。",""],["结草为寮石作床，和云和月卷衣裳。\n秋风华屋成尘土，却望青山是故乡。",""],["己挽卑枝当屋椽，更班枯草作寒毡。\n从今莫弹南飞鸟，客土安巢未有年。",""],["鸡喧犬嘷牛夜鸣，空村月落旅魂惊。\n何人敲竹争防虎，坐听山风过五更。",""],["偶沿流水出孤村，遥见人家欲断魂。\n屋上野狐嘷不去，土垣插棘半无门。",""],["负嵎妥尾两蹄蹲，秋草斑斑见石根。\n鸡犬已空人散久，犹张馋吻向荒村。",""],["万卷家藏史与经，翻床毁椟总飘零。\n可怜闲杀笺题手，无复林间拾露萤。","万卷家藏史与经，翻床毁椟总飘零。\n可怜閒杀笺题手，无复林间拾露萤。"],["团团异柏名罗汉，来往山中忽见之。\n东树作花西树子，从教枝叶定雄雌。",""],["东壁图龙势最雄，气连西壁雨云通。\n葛陂一杖无人识，双剑飞来野寺中。",""],["十年离乱今年甚，尽室飘零秋雨时。\n百里荒山行欲暮，望人烟火望晨炊。",""],["八月南奔未授衣，忽惊霜露满柴扉。\n敝裘已落他人手，憔悴苏秦未得归。",""],["门前红叶寒初落，窗下青烟湿不飞。\n赖得西邻老翁健，荆薪长日送柴扉。",""],["四邻寂寂昼无烟，一榻寒风拥被眠。\n十日开门惊剥啄，故人还送买盐钱。",""],["潇洒高标早出尘，岁寒空谷见斯人。\n紫霞洞里吹箫处，闲杀桃花万树春。","潇洒高标早出尘，岁寒空谷见斯人。\n紫霞洞里吹箫处，閒杀桃花万树春。"],["最爱同年欧进士，写梅笔意自成家。\n君看半幅横枝景，犹是春前雪后花。",""],["冲雪残年事远行，若为留滞过新正。\n室家零落田庐废，一纸书来万感生。",""],["夜宿塘西山馆中，可怜愁雨又愁风。\n一瓢春酒千行泪，明日行人独向东。",""],["东南争战定何如，二月农民少定居。\n独上西楼坐寥阒，四山烟雨一床书。",""],["颠云横雨挟风尘，终日寻春不见春。\n鸡犬已空桑柘废，清明谁是踏青人。",""],["二月携家又入山，纷纷争战往来间。\n草堂落尽梨花雪，过却清明未拟还。",""],["少壮从军事战征，东南十载废春耕。\n老翁远作诸孙计，闲种松苗待太平。","少壮从军事战征，东南十载废春耕。\n老翁远作诸孙计，閒种松苗待太平。"],["荒城人散草如烟，豺虎西来望市廛。\n肠断城南望城北，春深无计得归田。",""],["南园桃李旧凋伤，作意迎春向艳阳。\n十日寒风三日雨，翻成狼藉送年光。",""],["百年礼乐化齐民，孔庙彬彬器数陈。\n笾豆飘零钟磬毁，逾河蹈海更无人。",""],["石桥流水带人家，紫殿春阴阁岸沙。\n啼鸟数声山雨歇，门前落尽白桐花。",""],["松林日暮雨凄凄，十里陂田五里泥。\n一月离家归未得，桐花落尽子规啼。",""],["东望仙坛第一峰，倚天秀色尽寒松。\n春来山下多风雨，黄土潭深有卧龙。",""],["夜半山中布谷啼，离人归路梦中迷。\n深乡三月青苗老，犹有荒田未得犁。",""],["村北村南春雨多，千声布谷奈君何。\n稚子不知征战苦，把秧犹唱太平歌。",""],["路入南门晓看山，金钟石下转松关。\n溪深恶木多蒙密，却采芹花日暮还。",""],["东林鸟鸣风萧萧，西林月落星寥寥。\n老翁开门饭牛起，绿苗满田白水摇。",""],["三月雨晴风日侵，山下田田流水深。\n稻苗一片青如织，花鸭来时无处寻。",""],["伐木修城更运粮，科铜采箭又征鎗。\n耕牛掠尽丁男死，不信官田不解荒。","伐木修城更运粮，科铜采箭又徵鎗。\n耕牛掠尽丁男死，不信官田不解荒。"],["寺后青峰梵阁阴，寺前流水稻苗深。\n重寻稚子牵衣处，栗叶青青雨满林。",""],["白鹤仙人剑气雄，蜿蜒鳞甲动秋风。\n何年飞上精蓝壁，海藏神珠彻夜红。",""],["牧子食牛牛性驯，一鞭斜日过平津。\n如何跃马金鞍客，不及逍遥垄上人。",""],["绿房秋老骊珠黑，青箬霜馀翠羽干。\n歌罢采莲人不见，雪姑飞去水云寒。","绿房秋老骊珠黑，青箬霜馀翠羽乾。\n歌罢采莲人不见，雪姑飞去水云寒。"],["丛竹娟娟露叶翻，高情长是忆王孙。\n喜从石上看书法，不独墙阴见雨痕。",""],["满山黄叶乱秋晴，风款横江一棹轻。\n老屋溪南归未得，十年风雨最关情。",""],["云根雪骨立峥嵘，谁种琅玕绿乍成。\n安得长竿三百丈，为君横海掣飞鲸。",""],["石盘鳞鳞水溪急，鹡鸰飞来水中立。\n前飞回首定相呼，寒枝月明愁影只。",""],["霜蹄雾鬣耸权奇，乍摘金鞍汗血垂。\n海外贡来偏爱惜，监官引过不教骑。",""],["断岸遥山翠欲漫，冥鸿飞去楚天宽。\n何年结屋长松下，坐听江声五月寒。",""],["行人三五度回溪，乱后人家井灶迷。\n苍耳黄蒿无路入，断垣细雨鹁鸠啼。",""],["芦叶萧萧乱压头，石攒山拥路如钩。\n阴沉不见天边日，鸟自喧啾水自流。",""],["断垄荒冈少树林，翩翩何许一幽禽。\n欲栖不定还飞去，白苇黄茆秋正深。",""],["老虎庙前溪水长，白羊坪下晚山苍。\n到家尚远心先近，指点行人问小庄。",""],["猪龙已化潭中石，石上空馀人虎迹。\n老僧骑虎不曾归，溪水潺潺山叶碧。",""],["丁男战死籍名存，主将呼名更点屯。\n白发满头筋力尽，却教随伴守营门。",""],["火烧桥畔草离离，野水寒山日暮时。\n已渡前溪更回首，知君独立尚归迟。",""],["土屋无风尚不关，屋前遥见两青山。\n瓦盆盛酒茆铺席，何日柴门望月还。",""],["当时曾共北沙游，把酒哦诗赏素秋。\n十载故人零落尽，东山依旧说汤休。",""],["山绕平原屋绕山，两溪流水结回环。\n绿杨如画花如锦，长日鸟啼烟雾间。",""],["山中春鸟夜相呼，岸上谁家酒可沽。\n风露满船眠不得，长歌乘月过郎湖。",""],["野人乱后无归处，惟有尊前似故乡。\n昨夜流江水亭上，五更酒醒月如霜。",""],["风雨潇潇鸡乱啼，去年春梦使人迷。\n环波亭下东湖路，依旧荷花水满堤。",""],["北苑南宫意所亲，早于挥洒见天真。\n僧郎前月金陵去，卷得淮山一片春。",""],["万壑千林掩翠岑，出山自浅入山深。\n桃源未必真无路，正恐重来自莫寻。",""],["月隐前峰雾不开，杉林十里路萦回。\n多情楠木塘边水，相送行人出岭来。",""],["山塘坂上路如弓，步入巉岩曲折中。\n野鸟乱啼寒日暮，满山红叶动秋风。",""],["知君高节抱幽贞，为写修篁石上生。\n却忆瑶琴清奏罢，满天风露听秋声。",""],["历历烈烈风火飞，前山后山相映辉。\n春来雨打黑灰落，山下麦田应解肥。",""],["闲寻隐者忆重论，路绕荒田水绕园。\n何日山中收药去，满林修竹不开门。","閒寻隐者忆重论，路绕荒田水绕园。\n何日山中收药去，满林脩竹不开门。"],["海外飞腾地轴倾，五云雷电绕神京。\n鼎湖天远人难见，彷佛龙髯下太清。",""],["悠悠四十六年春，览镜惊看白发新。\n已分逍遥酬日月，东风何用妒闲人。","悠悠四十六年春，览镜惊看白发新。\n已分逍遥酬日月，东风何用妒閒人。"],["别时曾赋落梅花，江上风寒燕子斜。\n过却清明三日雨，荼䕷亭上客思家。",""],["白发曾闻一老翁，巍科当日仰高风。\n乡人遥指读书处，多在林间野寺中。",""],["蒲觞饮罢不成歌，闲步林阴爱绿莎。\n记取长塘初五夜，月明偏傍屋西多。","蒲觞饮罢不成歌，閒步林阴爱绿莎。\n记取长塘初五夜，月明偏傍屋西多。"],["水蛾扑扑飞烟暝，田狗荒荒吠月明。\n绛帐十围人半醉，青灯一点夜三更。",""],["去年南富杨梅熟，曾折青枝露颗垂。\n今夜长塘灯下醉，独看红颗忆青枝。",""],["依旧当年一笛吹，山寒云破月光迟。\n满堂宾客今谁在，无限伤心只自知。",""],["潇潇山雨夜鸣鸡，梦里怀归意转迷。\n林下今年寒更早，谁拈黄叶止儿啼。",""],["凤凰飞集五云间，送尔长歌入楚关。\n明日驾帆淮水上，便从云气望钟山。",""],["宫亭水落雁南飞，寒日萧萧锦树稀。\n二月东风江浦绿，却攀杨柳待君归。",""],["荷叶陂头流水声，月华霜气两凄清。\n自怜委翅蓬蒿底，不得相从赴远征。",""],["十年跋足走风尘，到处青山是主宾。\n武姥岩前前夜月，多情何事苦随人。",""],["山下泉车尽日闻，山头茶树绿成云。\n几时荷叶陂头住，学种山茶四十斤。",""],["水南羁客望春归，日暮茗园野烧稀。\n知有陂塘应不远，一双野鹤傍山飞。",""],["当年毛骨耸奇雄，曾奋沙场百战功。\n万里渥洼归未得，却将憔悴托秋风。",""],["离离四五百竿竹，落落二三千尺松。\n深结秋阴应憩鹤，高蟠云气欲成龙。",""],["碧岭穹林相倚倾，隔溪啼鸟唤春晴。\n松间石上堪题句，怕有人来识姓名。",""],["匆匆濡墨写忧端，凭仗东风寄便翰。\n政使书回春未暮，也应无处倩人看。",""],["花间撩乱作团飞，草际悠扬独自归。\n恼杀吴姬描不就，忽随扇影上春衣。",""],["汴水西头鼙鼓声，宝笺香翰尚娱情。\n可怜㶉鶒空毛羽，不解传书到北京。","汴水西头鼙鼓声，宝笺香翰尚娱情。\n可怜鸂鶒空毛羽，不解传书到北京。"],["暖风疏雨净尘埃，林下幽居锁绿苔。\n昨日桃花浑落尽，去年燕子却飞来。",""],["鹡鸰相顾复相依，萱草花开满石矶。\n不似秋来沙上雁，天涯风雨更分飞。",""],["江上何人吹笛声，水云风树两凄清。\n几时载取禾川酒，苦竹潭心看月明。",""],["日落狭潭风涌波，泛舟从此入天河。\n虚疑天上无人到，百叠青山路更多。","日落狭潭风涌波，汎舟从此入天河。\n虚疑天上无人到，百叠青山路更多。"],["千山万山云雾堆，一声何处雁飞来。\n盘回欲下还惊起，月照寒潭一线开。",""],["石根寒沼时时落，岭上荒田寸寸锄。\n已围荞麦防饥鹿，更插杉条护冻鱼。",""],["败叶草荒馀箭眼，残兵衣秃见刀瘢。\n萧条香火枫林静，散漫人烟草阁寒。",""],["两角黄牛一钓竿，古城幽处足盘桓。\n乱来税水仍输秸，留取溪山画里看。",""],["靖州令弟蚤称贤，小隐哦诗数百篇。\n松竹已荒文采在，清名留与后人传。",""],["十人送行一人去，船头举手沙头语。\n船开山转水急流，白云杳杳知何处。",""],["停舟不发更歌诗，歌未成章意已悲。\n注目沧波相别处，断肠荒陇独归时。",""],["冬青叶上雨潇潇，虚馆山寒坐寂寥。\n还说南村收获去，可能留客待明朝。","冬青叶上雨潇潇，虚馆山寒坐寂寥。\n还说南村收穫去，可能留客待明朝。"],["闭门坐待月光斜，应念行人未到家。\n好是客窗残酒醒，一帘风露看灯花。",""],["河水西边万木群，三间茆屋祀真君。\n仙家阒静无尘榻，自扫青苔坐白云。",""],["郎石溪头君故家，前朝文物自清华。\n几回想踏桥边石，翠竹潇潇覆白沙。",""],["臂袒红衫侧皂冠，翩跹跌舞乐初攒。\n笛声一片宫前起，应说秋风蜀道难。",""],["昨见王郎问吾子，山居炼得好诗材。\n青年未必仍多病，却怕风寒不出来。","昨见王郎问吾子，山居鍊得好诗材。\n青年未必仍多病，却怕风寒不出来。"],["我到流江一月馀，相思长把案头书。\n门前几树垂杨柳，比似别时今更疏。",""],["梨花一树照清池，煖雪晴风二月时。\n忽忆小园曾种得，今年应发两三枝。",""],["豫樟凝绿雪霜中，何事春来一转蓬。\n自是新条更旧叶，不关摇落是东风。",""],["君王无那汴宫春，八宝笺明墨羽新。\n寂寞金舆滦水外，绣禽杨柳入边尘。",""],["金沙花发绕亭东，万朵笼松满障红。\n安得移樽唤歌舞，为君醉倒锦屏中。",""],["明年期看上林花，烽火中原起叹嗟。\n旧业可堪沦草莽，高怀元不累尘沙。",""],["江草青青江水生，故人相见总怜情。\n云来雨去青天里，一日阴晴几变更。",""],["古今作者自联绵，白首穷愁也可怜。\n须信乾坤同照耀，肯教光景付流连。",""],["一夜山中听雨眠，重檐深院烛花偏。\n珠湖滩下水三尺，不知流却木兰船。",""],["园西翠韭千畦密，屋后红椒万本疏。\n日晏荷锄归未得，林风吹乱读残书。",""],["红锦帐子薄于纱，四壁清风泛彩霞。\n昨夜月明春梦熟，误吹长笛入桃花。","红锦帐子薄于纱，四壁清风汎綵霞。\n昨夜月明春梦熟，误吹长笛入桃花。"],["槐树阴阴雨满池，晚风滟滟绿生漪。\n槎头出水才三尺，便有蜻蜓立许时。",""],["画栏碧树午阴斜，小扇微风拂帽纱。\n最怜一时春水绿，不教五月看荷花。",""],["槿花蓬门处处同，行人桥外各西东。\n荒原斜日牛羊下，一路西风蒴藋红。",""],["珠湖湖里蚌生珠，野老传言定有无。\n昨夜月明湖上望，一川寒色秀菰蒲。",""],["老桂初开试一枝，吹香时有外人知。\n深林尽日何当见，自是秋风不敢私。",""],["连云长爱绿团团，一片清阴九夏寒。\n自有秋香三万斛，何人更向月中看。",""],["山风吹落桂花枝，江上停杯欲别迟。\n半夜酒醒柔橹发，一篷烟雨过平陂。",""],["石门滩下浪如雷，西岸人家夕照催。\n乱石满江滩路浅，唱歌踏水负薪来。",""],["石潭秋水漾清萍，两岸青山夹去津。\n钩箭缠丝挟长弩，柳阴时见射鱼人。",""],["龙福渡头滩最高，断桥崩石鼓秋涛。\n小船不敢当江下，独傍洲湾送短篙。",""],["秋雨生苔绿正肥，江心石面暗浮衣。\n渔人网罟应难下，野鸭鸬鹚满钓矶。",""],["马颊庙前江水长，马头石下绿潭光。\n出山估客来求卜，抛纸放船浇酒香。",""],["沙岸崩时惟见石，江流曲处却逢山。\n荒林野屋元星散，古路行人自往还。",""],["放船出峡遇回风，石角参差尽向东。\n贪看好山如走马，不知波浪入船中。",""],["阳台石下水离离，梦阁犹传故老知。\n千载神游竟何往，满江明月照荒祠。",""],["老人醉墨走蛇虬，风露潇潇数叶秋。\n无复驼囊盛马乳，却教图画忆凉州。",""],["朝真坛上月明时，白鹤归来见好诗。\n三月青塘芳草路，十年风雨最相思。",""],["筼筜谷中三日雪，深林无人鸟飞绝。\n翩翩翠袖出岩阿，路转风回闻佩玦。",""],["沧波石面晚阴凉，翠筱娟娟过雨香。\n何许鹧鸪啼不断，黄陵祠下是三湘。",""],["翠叶枝低雨过时，钓台石上影离离。\n记得月明江浦夜，舟人解唱竹枝词。",""],["石边修竹两三竿，渭水萧森暮色寒。\n会见秋风吹结实，凤皇吹下五云端。",""],["长丰隐者年八十，种竹满林皆老苍。\n莫将翠玉轻裁管，留取长竿钓渭阳。",""],["秾花嫩蕊各争春，乳燕鸣鸠亦恼人。\n偃蹇南园敧竹笋，独依榛藋蔽闲身。","秾花嫩蕊各争春，乳燕鸣鸠亦恼人。\n偃蹇南园敧竹笋，独依榛藋蔽閒身。"],["华山收雨两江晴，夏竹屯云一径清。\n门外绿阴眠野鹿，隔帘时听打棋声。",""],["玉露凋伤赤岸枫，寒江月落雁呼风。\n谁知茅屋荒山夜，亦有长吟抱膝翁。",""],["雾雨初晴万竹低，莺声彷佛度前溪。\n忽然飞去无人见，却在绿杨深处啼。",""],["胜乡三日雨如秋，两江新水拍山流。\n长杉短筏不敢下，怕有蛟龙乘夜游。",""],["宣华西上是敖城，江水弓弯复镜平。\n五月行人西岭下，满山青树只闻莺。",""],["为谢高阳旧酒徒，相逢从此莫言酤。\n野鸟不知官禁苦，向人犹自说提壶。",""],["苍颜皓首一癯翁，谈笑衣冠有晋风。\n昨夜卷书灯下看，眼明犹自辨鱼虫。",""],["林间净扫白云眠，萧散宁为外物怜。\n自说东华年少梦，千金歌舞看花前。",""],["高架松棚荫绿苔，忽看片影上层台。\n可缘畏日翻嫌月，并隔清光不入来。",""],["湖阴微雨裛新妆，隔浦风来水气香。\n闲凭船舷不归去，绿荷花底看鸳鸯。","湖阴微雨裛新妆，隔浦风来水气香。\n閒凭船舷不归去，绿荷花底看鸳鸯。"],["绿荷缭绕水为城，十里红云照眼明。\n不知昨夜花开满，清晓船来不可行。",""],["郎船夜傍隔溪云，清晓看花不见君。\n自拨兰桡唱歌去，却嫌荷叶混罗裙。",""],["新莲乍出即昂头，叶底红菱不解浮。\n菱角沉泥终暗老，莲花落尽即漂流。",""],["㶉鶒双飞乱绿苹，画船终日倚湖滨。\n泥中踏藕何由得，水上看花恼杀人。","鸂鶒双飞乱绿蘋，画船终日倚湖滨。\n泥中踏藕何由得，水上看花恼杀人。"],["自入花丛擘翠房，散抛莲菂水中央。\n秋来无奈相思苦，心苦愁多不敢尝。",""],["淡淡红妆慢慢歌，画船如月荫高荷。\n雨来不怕罗裙湿，贪看湖光舞翠娥。",""],["独自沿流出浦迟，回船何事不相期。\n满房莲子谁心苦，落尽秋花君始知。",""],["风满松林水满池，幽人看月未归时。\n山禽夜半啼如鬼，童子熟眠浑未知。",""],["早禾渡头不相遇，青山岩前还独归。\n想见它山逐狐兔，苍鹰掠地马如飞。",""],["候吏庭闲散绿苔，银鞍何处未归来。\n寒塘九月风烟净，惟见芙蓉一树开。","候吏庭閒散绿苔，银鞍何处未归来。\n寒塘九月风烟净，惟见芙蓉一树开。"],["清潭百尺绿渟渟，潭上青山立翠屏。\n安得扣舷明月下，放歌垂足踏寒星。",""],["深深黄竹两三家，丘陇高低径路斜。\n犬吠柴门枫叶下，一篱寒日蔓丝瓜。",""],["中园风雨一茆茨，土壁沾濡叹地卑。\n昨日开渠北檐下，已通流水过南池。",""],["娇儿忍冷戏床前，贪笑痴啼也可怜。\n乌桕林空红叶湿，萧萧烟火对愁眠。",""],["鸡犬萧条少四邻，孤村风雨自荆榛。\n愁来爱读平原传，浊世翩翩一伟人。",""],["山鸟一声当翠微，野人初启竹间扉。\n日轮欲上天东角，满地白烟皆倒飞。",""],["入山方恨故人疏，喜得朝来一纸书。\n十日闭门仍断酒，谁怜多病马相如。",""],["快阁东头是故家，儿时插竹更移花。\n只今门巷无寻处，半落江流半岸沙。",""],["寒江水落雁团沙，碧嶂霜馀树隐霞。\n行客忽惊冬欲尽，道傍初见报春花。",""],["霜落乌啼知夜长，驱车欲别更徬徨。\n明年何处来相觅，杨柳青青马迹塘。",""],["北岩云气上岧峣，却望归云度野桥。\n谁在西楼吹夏笛，雁飞不尽海天遥。",""],["一二初三眉黛横，佳人夜夜望琼英。\n无端数到团圆后，圆不多时缺又生。",""],["此去风光日尚微，已闻百舌弄春晖。\n江南二月多冰雪，塌翼垂头何处飞。",""],["阴雨先晨作大寒，东归道路恐难干。\n故园梅树花开未，犹拟春前十日看。","阴雨先晨作大寒，东归道路恐难乾。\n故园梅树花开未，犹拟春前十日看。"],["洞玄道士周方外，昨到宣华绝顶回。\n岩上欲寻山橄榄，忽逢虎迹却归来。",""],["奉天门外唱班齐，雾隐回廊月正西。\n警跸传声团扇出，文楼挝鼓报鸡啼。",""],["禁树晨霜欲下时，垂鞭马上怯先知。\n午门月落闻金柝，城上风回见画旗。",""],["晓日曈昽射赤墀，侍臣奏事退班迟。\n龙旗凤扇参差出，又是彤墀下直时。","晓日曈昽射赤墀，侍臣奏事退班迟。\n龙旂凤扇参差出，又是彤墀下直时。"],["圣主潜心古帝王，武楼降辇步长廊。\n壁间不遣丹青涴，尽揭先儒衍义章。",""],["警跸初传夜未央，朱衣当殿簇班行。\n忽宣内使移宫炬，分照儒臣读奏章。",""],["东苑金河水慢流，水边芳草弄轻柔。\n晚凉小盖诸王出，争控雕弓试紫骝。",""],["天设皇居象紫庭，文昌执法粲群星。\n午门东北红云起，遥见钟山万丈青。",""],["腊月炎州霜霰稀，清江白日燕交飞。\n四千馀里金陵路，何日征人度岭归。",""],["垂根榕树三千尺，结子芭蕉百万头。\n异味荐盘随地有，繁阴压屋半天浮。",""],["趋跄木屐儿童惯，织作蕉丝妇女能。\n老去只疑盐是雪，寒来不信水成冰。",""],["峒商贩米笼千头，结竹浮江下广州。\n击鼓烧香南海庙，买羊沽酒市街楼。",""],["炎州果木人难识，诘问惭为口腹劳。\n滋味却缘相济好，也拈柑橘食羊桃。",""],["天边日出雾难收，海上潮来水逆流。\n一自征夫下番去，南风日日误登楼。",""],["箸竹长篙铁木船，两樯夹立引藤牵。\n越童狎水仍轻悍，荡桨踏歌惊昼眠。",""],["越王台榭已成原，汉殿空馀铁柱存。\n莫倚兵戈凭海峤，好勤忠孝荅乾坤。",""],["五指山前落日黄，雷家寨下野田荒。\n时平村堡无防警，缘水人家自绕墙。",""],["行尽翁源山万重，高人喜遇粟千钟。\n可怜老却观书眼，不识云间一个峰。",""],["万石崩腾互犬牙，两山盘沓欲横遮。\n泷流直下三千尺，不见船头见浪花。",""],["白日青崖烟雾生，深林绝涧少人行。\n残年乌石泷头路，听得山猿第一声。",""],["锦裹石前江水流，故人曾此戍康州。\n当年旌节随云散，尚对山花识旧游。",""],["苍梧浦口暂停舟，闻在浔州与贺州。\n无限好山云雾里，为君惆怅一回头。",""],["都峤山前望北流，丹砂勾漏若为求。\n陆川更在浮云外，落日旌旗生远愁。",""],["南上荒原路欲迷，数家茆屋背清溪。\n夜深月落千峰暗，时有山禽树上啼。",""],["树杪高崖尽插天，岩腰坠石半侵田。\n火烧山木断平路，骑马乱行江水边。",""],["路入高州石径微，紫崖崩处黑云飞。\n行人初发青山下，尽折芭蕉作雨衣。",""],["化州城上月如秋，听着歈歌人自愁。\n何日归帆向东去，陵罗江上正西流。",""],["山晚鸦啼木栅城，征人暂驻马前旌。\n荒原漠漠风沙晚，犹隔雷阳二月程。",""],["独上高原望海堤，黄云白浪使人迷。\n无端路近青铜港，流水三条尽向西。",""],["去年与子南京别，知领盐仓白石场。\n万里相寻不相见，独骑官马过雷阳。",""],["钦廉西望路悠悠，海角亭中足胜游。\n圣化只今无远迩，岭南风土是中州。",""],["鹑居鷇食见天机，踯躅蓬茆顾影稀。\n长忆野田秋日晚，马头惊起一双飞。",""],["小小池陂两斛泉，也教插柳着春烟。\n粉墙过午新阴合，时有清风一洒然。",""],["闻有高荷相次开，绿云深护紫霞杯。\n公曹清切人难到，自绕池边去复来。",""],["野桥流水乱浮花，深巷垂杨浅荫沙。\n祗恨小船呼不应，隔江茆屋似吾家。",""],["忆昔推篷泛雪漪，一花半蕊见横枝。\n谁知天上春消息，不在清江烂漫时。",""],["清溪绿涨岸西东，五月荷花似锦红。\n安得水亭杨柳畔，疏帘小扇坐薰风。",""],["内官宣进瑞瓜词，阊阖门深昼影移。\n东苑红桥杨柳下，曾因待诏立多时。",""],["湛湛长江上有枫，偶然相遇两渔翁。\n明日何由问踪迹，五湖烟浪杳茫中。",""],["上人九月过开沙，门掩虚庭白日斜。\n好是重阳最相忆，隔墙无路看黄花。",""],["巨然山水校毫毛，灵彻诗歌费炼陶。\n何似老禅三昧手，云飞风卷幻蒲萄。",""],["禅林闻有诸方胜，吏事惭无半日闲。\n京口五更鸡唱乱，又冲残月过金山。","禅林闻有诸方胜，吏事惭无半日閒。\n京口五更鸡唱乱，又冲残月过金山。"],["曾向花前倒酒卮，茆堂雪月澹相宜。\n一从省掖看图画，长忆故园花发时。",""],["仙人粲粲雪肌肤，风格天然韵更殊。\n月落岭南啼翠羽，春深洛浦弄明珠。",""],["昔年禹庙閟神功，遗干槎枒自一丛。\n彷佛苍龙鳞甲动，倒翻云影下晴空。",""],["内官飞骑入松林，寺里华钟吼法音。\n五百高僧齐上殿，红袈裟里间泥金。",""],["香台百尺拥雕棂，一朵青莲出紫庭。\n龙辇先登开善塔，鸾旗犹驻翠微亭。",""],["影落松林初散漫，阴浮野水暂稀微。\n时来天上从龙去，五色祥光夹日飞。",""],["海上风清入桂林，好山何处一登临。\n都门四月相携别，不尽长江望远心。",""],["太常天上缀清班，家在金华紫翠间。\n昨日朝回见图画，双松正对石门山。",""],["一枝寒影弄芳菲，无数幽香上客衣。\n好似水边晴雪后，醉吹玉笛送春归。",""],["湛湛长江上有枫，江平日落见飞鸿。\n安得酒船三百斛，荷花荡里钓秋风。",""],["钓船闲倚落星湾，飞瀑高悬紫翠间。\n风雨不来云气净，绝胜湖里看庐山。","钓船閒倚落星湾，飞瀑高悬紫翠间。\n风雨不来云气净，绝胜湖里看庐山。"],["赞府澄江送别时，曾挥健笔写淋漓。\n只今西掖看图画，江雨山云总去思。",""],["道人滴露调香墨，写出秋花一两枝。\n愁绝渊明愁未醒，短篱沽酒月明时。",""],["仙鸟飞来练带斜，踏翻云影碧桃花。\n谁令天上传消息，春到瑶池阿母家。",""],["先生归隐甘溪日，七帙高堂雪满簪。\n不待鼎珍陈至礼，便如饮水也应甘。",""],["海岛沙寒倦马嘶，风潮雪暗水禽啼。\n去京已是三千里，家比京城更在西。",""],["小清河入大清河，混混船头涌浊波。\n已过回湾五十里，华山犹自郁嵯峨。",""],["东望华山西碏山，河流奔放两山间。\n岸沙疏恶居人少，时见鱼罾占一湾。",""],["北上桐城日未斜，人烟萧瑟半风沙。\n客怀千里愁冰雪，三月东河见柳芽。",""],["山东征客几时归，榆荚成钱草似衣。\n政自羁愁无着处，马头忽见雉双飞。",""],["初日榆林听鸟鸣，微风拂面晓烟轻。\n纸钱麦饭谁家子，忽忆清明上冢行。",""],["毵毵榆柳带烟萝，落日荒原狐兔多。\n断港已无流水过，行人犹说古黄河。",""],["三月春光欲暮时，故园回首意兼悲。\n道傍杨柳心枯尽，犹有青青到远枝。",""],["燕山城里逢除夕，子自无家我亦僧。\n一种乡心难与说，闭门各自对青灯。",""],["书发南京已岁徂，开缄惊喜忽长吁。\n谁知路比燕山近，更说新来一字无。",""],["南北相望路七千，南风只有卖盐船。\n故乡消息何时发，纵得书来是半年。",""],["稚子家人俱可怜，江南烟水路绵绵。\n开船好是烧灯后，下马何由醉眼前。",""],["转觉别来俱老大，四年不见奈愁何。\n直须灯下狂呼酒，比较何人白发多。",""],["昨日通州好语传，凌开已见上河船。\n船中怕有南来客，直遣相迎河水边。","昨日通州好语传，淩开已见上河船。\n船中怕有南来客，直遣相迎河水边。"],["更忆舍南篁竹边，长公相对结茅椽。\n有时蹑屐窥园去，长日抛书枕石眠。",""],["自起床头数俸钱，倩人买秫酿冰泉。\n牡丹开日应须到，净扫西轩待醉眠。",""],["群乌乱鸣苍柏颠，南窗对酒一凄然。\n不知今夜燕台月，何处荒江照客船。","群乌乱鸣苍柏颠，南窗对酒一悽然。\n不知今夜燕台月，何处荒江照客船。"],["不见梅花思黯然，萧萧尘土入新年。\n白杨枝上垂缨络，正是燕城二月天。",""],["自卷新图寄长公，幽篁古木两三丛。\n燕城六月尘如海，得似南窗卧竹风。","自捲新图寄长公，幽篁古木两三丛。\n燕城六月尘如海，得似南窗卧竹风。"],["江亭秋望渺衡湘，埼岸枫林带夕阳。\n欲采苹花愁远客，白鸥飞去水茫茫。","江亭秋望渺衡湘，埼岸枫林带夕阳。\n欲采蘋花愁远客，白鸥飞去水茫茫。"],["锦石琼沙不涴尘，桃花杨柳满江春。\n画船载酒游何处，绝似风流贺季真。",""],["海子空涵万岁山，广寒殿在碧云间。\n岩前无数长松树，惟有飞鸦日暮还。",""],["微雨初晴不作泥，牡丹花发石栏西。\n公庭过午文书静，坐听林鸠自在啼。",""],["叶底青丝乍委𬙋，枝头碧子渐含浆。\n燕南山北家家种，不比齐东枣栗场。","叶底青丝乍委纕，枝头碧子渐含浆。\n燕南山北家家种，不比齐东枣栗场。"],["十年不见寿安红，三月燕城雾雨中。\n未省何人旧栽得，斩新雨露斗春风。",""],["绀芽翠叶蔼离离，喜见新年发数枝。\n无酒无朋难独赏，每来花畔立多时。",""],["年少粗豪喜战功，短袍新赐锦重重。\n对箭戳鎗夸得隽，骣骑官马去如龙。","年少粗豪喜战功，短袍新赐锦重重。\n对箭戳鎗誇得隽，骣骑官马去如龙。"],["绕城密密插垂杨，近水仍添四五行。\n莫遣行人来系马，更教遮护起藩墙。",""],["海上青山山上云，空青锦绣自成文。\n广寒西下红桥晚，两岸荷花一径分。",""],["潇洒颂台赞礼郎，手持纨扇白于霜。\n只今写得筼筜竹，清昼无风也自凉。",""],["南城土垣故不塌，西宫渠水自相通。\n野芦花侣杨花白，蕊木叶如枫叶红。",""],["菜根磊磊红萝卜，草子崭崭白蒺藜。\n东蓟直通齐化外，南城更在顺承西。",""],["长帘卖酒夸江米，小槛分鱼说海鲜。\n羊市角头逢贾竖，蓬莱坊里问神仙。","长帘卖酒誇江米，小槛分鱼说海鲜。\n羊市角头逢贾竖，蓬莱坊里问神仙。"],["城中十井九苦水，城外四围三面山。\n侠客已无多伎俩，燕姬那得好容颜。",""],["官马清晨去打围，马前鹰犬去如飞。\n平原日落烟尘起，野兔山鸡倒载归。",""],["满城风雨冷凄凄，白杨叶飞鸟乱啼。\n马蹄暗踏十街水，车毂深埋一尺泥。",""],["直北风来厉作威，吹沙挟雨半空飞。\n行人不惯张油盖，茸帽毡衫信马归。",""],["自数青钱送酒家，瓦瓶细细注流霞。\n牡丹芍药从渠有，莫负庭前瘦菊花。",""],["杨叶落尽桑叶稀，乌鹊夜啼风掩扉。\n长年塞北风霜早，何日江南游子归。",""],["帘外纤尘寂不惊，满庭秋意坐来清。\n闲门白日无人过，犬吠阶前落叶声。","帘外纤尘寂不惊，满庭秋意坐来清。\n閒门白日无人过，犬吠阶前落叶声。"],["杏梨三月斗芳华，不见深冬梅与茶。\n欲识幽燕风景异，菊花开后更无花。",""],["陟顿风来刮地吹，排窗推户更掀帷。\n居民土壁围烟火，暖坑敧眠自不知。",""],["马龁枯荄寒夜长，风如箭镞射阴房。\n不知门外三更雪，误起开门看月光。",""],["残年寄食尚天涯，风裂禅衣面扑沙。\n还忆故山晴雪里，闲拖锡杖看梅花。","残年寄食尚天涯，风裂禅衣面扑沙。\n还忆故山晴雪里，閒拖锡杖看梅花。"],["曾闻剑阁上青天，栈道萦纡路几千。\n更过陇头听流水，白云西下自秦川。",""],["九华日照绿杨川，三峡云深瀑布泉。\n安得草衣骑白鹿，碧桃花底访神仙。",""],["惆怅乘骢客未回，杏花落尽牡丹开。\n西厅吏散文书静，几向花阴立紫苔。",""],["囊盛罂粟寄来迟，种得花开定几时。\n赖有戎葵高一丈，浅红深绿总宜诗。",""],["戎葵花早牡丹迟，刚值先生下马时。\n不便破除千斛酒，也应勾引数篇诗。",""],["有客邯郸久未回，西厅无奈好花开。\n当筵纵赏何由共，日日开轩扫翠苔。",""],["家住江南青竹林，别来无日不关心。\n偶然写向齐纨上，便欲移床坐绿阴。",""],["琼枝翠叶静为邻，秀色娟娟绝点尘。\n日暮天寒罗袖薄，可怜空谷有佳人。",""],["居庸关前秋草新，桑干河畔是通津。\n可怜无数沙场雁，个个南飞背着人。","居庸关前秋草新，桑乾河畔是通津。\n可怜无数沙场雁，个个南飞背着人。"],["送客出城秋已凉，太行南上楚天长。\n顺承门外斜阳里，荞麦花开似故乡。",""],["十角黄牛两具犁，山南山北趁幽栖。\n杏花开后菖蒲出，春雨鹁鸠相应啼。",""],["独移兰棹钓沧湾，风细波澄夜景闲。\n却渡九溪歌九曲，不知月上浸亭山。","独移兰棹钓沧湾，风细波澄夜景閒。\n却渡九溪歌九曲，不知月上浸亭山。"],["西风和雨入长杨，的的青灯伴夜长。\n一纸乡书三四读，不知清泪湿衣裳。",""],["瓦桥东馆晚停骖，喜遇幽人慰盍簪。\n间说从游往年事，满庭霜月梦江南。",""],["顺承关外酒阑时，驻马相看各自悲。\n多谢青山三百里，送人直过易河西。",""],["单家桥下雪横冰，草树连云掠冻鹰。\n汉业已荒河水在，行人遥指献王陵。",""],["柴门下马日平低，苇席蓬窗壁乍泥。\n寒夜老翁看客惯，青钱问酒过村西。",""],["霜结沙尘冻不飞，榆林风定日熹微。\n客程已入山东境，渐喜居人识面稀。",""],["昔贤经济未轩张，末路低回祗自伤。\n斗酒新礼聊濯足，令人长忆马宾王。",""],["北风吹沙官道长，两傍杨柳间榆桑。\n何时走马重来此，要看清阴六月凉。",""],["碌独双轮至日斜，北风竟日卷黄沙。\n已添衣上尘三斗，谁料胸中书五车。","碌独双轮至日斜，北风竟日捲黄沙。\n已添衣上尘三斗，谁料胸中书五车。"],["牧童敲火枯柳根，青烟猎猎起荒原。\n回风吹入蓬科去，烧却东家桑枣园。",""],["野老当门喜客来，旋烧新炕斫桑柴。\n自言土恶无甜水，五里分泉夜部回。",""],["驱车甜水铺前宿，燎火夜干衣上霜。\n忍渴不眠愁水苦，五更乘月过高唐。","驱车甜水铺前宿，燎火夜乾衣上霜。\n忍渴不眠愁水苦，五更乘月过高唐。"],["桥跨平湖一境开，群鸥欲下正徘徊。\n萧萧芦苇层冰上，犹有樵人踏雪来。",""],["联桂坊前君故里，匆匆车过不曾知。\n逢人相问凭相谢，正是南关大雪时。",""],["寒鸦啄雪行且飞，东平道上行人稀。\n炕头黄酒那得买，冰下鲤鱼空自肥。",""],["忆从绣水入高州，篁竹萧萧万岭秋。\n道上行人敲石火，截筒炊饭也风流。",""],["庆都山人齐伯高，袖有五色之仙毫。\n李白楼前忽相遇，便呼银瓮出蒲萄。",""],["我本山林麋鹿姿，多君点染出清奇。\n不知老去愁多少，但觉秋霜满鬓丝。",""],["昨夜南关对月时，客心如水向南驰。\n京城此去犹千里，岁晏还家未有期。",""],["京国南还水路遥，城阴复此驻兰桡。\n可怜关外重重闸，不放河流过鲁桥。",""],["目送飞鸿手抚弦，十年幽事已茫然。\n谁知昨夜南归梦，犹在云山野水边。",""],["忆在江南处士家，每从雪里见横斜。\n北来十月燕山下，却忆梅花似雪花。",""],["北风打头船进迟，南阳河口正流澌。\n玉皇庙前杨柳树，行人却望忆来时。",""],["小龙涡接大龙涡，谷亭闸口水穿波。\n寄语南船缓来上，北船东下正如梭。",""],["谷亭亭子大河边，赤鲤黄鱼不论钱。\n水上浮凌高一尺，朝来阻住北来船。","谷亭亭子大河边，赤鲤黄鱼不论钱。\n水上浮淩高一尺，朝来阻住北来船。"],["河堤石表古来存，知为谁家守墓门。\n旧冢已墟人世换，年年乌鸟当儿孙。",""],["鸡鸣台下水禽啼，韩信城边雪满堤。\n千里行人愁夜半，一船明月过河西。",""],["水禽如雪憩浮澌，流下前滩漫不知。\n岸转舟回忽惊起，口中衔得锦鳞鱼。",""],["一河盘注两堤间，十里应多北曲湾。\n南舰经年载盐去，北船尽日送军还。",""],["数家茆屋是沙河，废闸当河乱石多。\n大船东下好扶舵，泗水西流当奈何。",""],["荒城如斗半蒿藜，千古全功孰与齐。\n须信君恩本天道，如何自挟请封齐。",""],["满河冰片挟舟行，洲渚参差互送行。\n九里山晴春意动，买鱼酤酒过彭城。",""],["舟下徐洪冻已开，故园远在赣江隈。\n家家春近栽杨柳，江上行人且未回。",""],["徐州洪上月团团，浪打孤舟客影寒。\n料得人家今夕语，一年十二度相看。",""],["碧瓮盛来琥珀光，感君远意不能忘。\n情知岁近归期远，且对尊前说故乡。",""],["白头鸳鸯飞且号，双双冲雪下江皋。\n吴娃不省风波苦，只想花门绣羽毛。",""],["淮安城下霜月明，淮河船上唱歌声。\n谁遣此歌今夜唱，声声却是怨郎行。",""],["望郎归近怨郎行，一步闺门万里情。\n辛苦寄书河北去，人言却在武昌城。",""],["湖淀野人工捕鱼，隔冰见鱼冰下居。\n持斧凿冰刺鱼去，凿根团团井不如。",""],["关门迢递通何处，野寺依稀记昔年。\n未拟炉峰看瀑布，直疑剑阁上青天。",""],["沙薄霜干草不深，萧萧榆柳冷无阴。\n村园门巷皆鸡犬，比似江南少竹林。","沙薄霜乾草不深，萧萧榆柳冷无阴。\n村园门巷皆鸡犬，比似江南少竹林。"],["层冰两岸戏龙鳞，先放河心一道春。\n借问驿船行得未，南京杨柳待归人。",""],["鸟过平原霜草齐，雉飞兔走各东西。\n何由掣取腰间剑，细割肥鲜酒自携。",""],["古色苍寒倚太空，旁无附丽屹当中。\n要知独拄东南角，不是人间培𪣻雄。","古色苍寒倚太空，旁无附丽屹当中。\n要知独拄东南角，不是人间培塿雄。"],["步入齐城见石麟，荒凉莎草欲无春。\n北风着意如相识，吹雪花来候远人。",""],["欲度成山泛海槎，凤村夜半雪飞花。\n何由倒卷沧溟水，净洗扶桑看日华。","欲度成山泛海槎，凤村夜半雪飞花。\n何由倒捲沧溟水，净洗扶桑看日华。"],["北海东逢曲秀才，凤皇闻到此山来。\n春风好种梧桐树，早晚飞鸣上紫台。",""],["青杨沟下是黄河，三月春深风浪多。\n河中石子白磊磊，河水自浑君奈何。",""],["河流曲曲是盘钩，东北西南不定流。\n何似客行西北去，回头一向望南州。",""],["马家浅上船难泊，徐州洪下好相寻。\n水急莫嗔郎性恶，滩浅不如人意深。",""],["家住黄河相见湾，湾头道路古来难。\n十度船来九度见，郎行自隔万重山。",""],["河上丈人河上居，杨柳青青三月初。\n少年挟箭去射雁，妇女踏罾能网鱼。",""],["临河照影插花枝，莫道浑浊不相宜。\n试把郎心比河水，顾盼分明当自知。",""],["长洲短岸去匆匆，坐看云霞西复东。\n最爱归船胜走马，不烦鞭策只乘风。",""],["南上河里三百里，买鱼沽酒二三程。\n小篷短棹泛敧侧，卧听风声与水声。",""],["木落秋容净，天高旦气清。\n乾坤澄玉色，云雾豁金精。\n招隐怀丛桂，寻幽想茯苓。\n委蛇缘涧壑，迢递出郊坰。\n赤岭酣朝旭，青峰带曙星。\n筼筜交石崦，萝薜荫林亭。\n峡口闻清唱，崖阴见耦耕。\n洞猿啼石裂，山鹘掠云平。\n瑶草迷玄圃，琪花蔼赤城。\n老君岩崱屴，仙女沼泓澄。\n玉几栖崖稳，金床映户荧。\n仙桃宁有种，石鼓自无声。\n莲坠飘银汉，松蟠偃翠棂。\n缘檐风铎乱，挂壁雨瓢轻。\n木鹤遥占斗，铜龙并拱衡。\n殿标唐岁月，地拥汉精灵。\n凤诏云霞焕，龙章日月精。\n搴帷瞻绰约，隔水望娉婷。\n奕奕青霞服，飘飘赤羽旌。\n采鸾朝解佩，骑虎夜吹笙。\n缥渺何由遇，荒唐孰可名。\n悲歌传下土，遗迹渺飞輧。\n王纪长沙系，兵行百粤征。\n委禽怀恋恋，凿石感铮铮。\n仙偶真难匹，师昏竟莫成。\n断云空有望，流水故无情。\n已矣遗祠庙，苍然肃殿楹。\n莓苔沾玉座，尘网拂珠缨。\n明镜沈秋涧，残棋委石枰。\n寻真怜梦窈，抚字觉心惊。\n映日蚕崖瘦，缘云鸟道横。\n跻攀愁独坐，歌啸混同行。\n剪烛当清漏，移尊近翠屏。\n绝襟从客醉，移席任渠争。\n酬唱兼谐谑，登临任送迎。\n孟文频绝倒，仲颖故沈冥。\n思苦心应呕，眠迟眼屡瞠。\n吟教刘楚哑，联到赵埙醒。\n月冷茶烹栗，霜寒瓜剖琼。\n风从钟后息，泉共醉时听。\n磨石须题姓，临池欲写经。\n继膏愁道士，授简愧诸生。\n林鸟寒初定，岩扉夜不扃。\n栟榈高瑟瑟，黄竹乱琤琤。\n天地真㵳泬，朋游此合并。\n百年成过鸟，一夕感浮萍。\n野迥参初转，庭空露向零。\n长吟倚空阔，吾欲访蓬瀛。",""],["云递月微明，月澄露初泫。\n川容淡水物，荷气沿阶藓。\n更深喧渐息，虑涤情自遣。\n宿鸟寒不飞，流星下遥𪩘。","云递月微明，月澄露初泫。\n川容淡水物，荷气沿阶藓。\n更深喧渐息，虑涤情自遣。\n宿鸟寒不飞，流星下遥巘。"],["林馆众绿净，微风濯烦歊。\n眷言集群彦，清宴永崇朝。\n礼尚匏樽俭，欢逾锦瑟调。\n初筵陈旅语，雅韵接仙韶。\n磊落高怀泻，疏狂逸兴飘。\n炙鲜香溢鼎，注玉色翻瓢。\n斟酌烦童竖，歌呼狎友僚。\n杨梅红欲滴，山韭翠初挑。\n坐倦轻𫄨解，吟酣小扇摇。\n云窗尘不到，雪椀暑全消。\n憩渚仙禽迥，穿檐海燕娇。\n飞飞浑不定，矫矫讵能招。\n慈竹秋阴近，宫槐暮色遥。\n居便人事简，贫爱客情饶。\n闭户仍投辖，携壶更解貂。\n习池宁足恋，谢墅故难邀。\n自抚便便腹，谁呼袅袅腰。\n青云期放旷，白发任飘萧。\n楚也泥途迹，铭乎玉雪标。\n那能终隐逸，端可上云霄。\n萍梗嗟良会，蓬蒿托圣朝。\n赤心元皎洁，丹禁自岧峣。\n伏剑青蒲切，趋班玉笋超。\n鸡鸣天阙道，龙跃海门潮。\n结驷陪官署，联镳出使轺。\n北游尚尘土，幽事且渔樵。\n胜会宁辞数，狂歌故不骄。\n杯行须泛泛，瓶罄莫寥寥。\n苏圃连花坞，徐亭带柳桥。\n它年留雅韵，应得继风谣。","林馆众绿净，微风濯烦歊。\n眷言集群彦，清宴永崇朝。\n礼尚匏樽俭，欢逾锦瑟调。\n初筵陈旅语，雅韵接仙韶。\n磊落高怀泻，疏狂逸兴飘。\n炙鲜香溢鼎，注玉色翻瓢。\n斟酌烦童竖，歌呼狎友僚。\n杨梅红欲滴，山韭翠初挑。\n坐倦轻絺解，吟酣小扇摇。\n云窗尘不到，雪椀暑全消。\n憩渚仙禽迥，穿檐海燕娇。\n飞飞浑不定，矫矫讵能招。\n慈竹秋阴近，宫槐暮色遥。\n居便人事简，贫爱客情饶。\n闭户仍投辖，携壶更解貂。\n习池宁足恋，谢墅故难邀。\n自抚便便腹，谁呼袅袅腰。\n青云期放旷，白发任飘萧。\n楚也泥途迹，铭乎玉雪标。\n那能终隐逸，端可上云霄。\n萍梗嗟良会，蓬蒿托圣朝。\n赤心元皎洁，丹禁自岧峣。\n伏剑青蒲切，趋班玉笋超。\n鸡鸣天阙道，龙跃海门潮。\n结驷陪官署，联镳出使轺。\n北游尚尘土，幽事且渔樵。\n胜会宁辞数，狂歌故不骄。\n杯行须泛泛，瓶罄莫寥寥。\n苏圃连花坞，徐亭带柳桥。\n它年留雅韵，应得继风谣。"],["次公不解饮，越石最能诗。\n短句从谁赋，空觞祗自持。\n晴云低过雨，斜日上高枝。\n近寺钟声起，归鞍未可期。",""],["疏雨湖边过，凉风柳下来。\n隔堤渔网出，别浦酒船回。\n远树来江阔，残云带暝开。\n层台歌吹发，犹恐暮钟催。",""],["池馆月初上，幽人时独行。\n焉知竹林下，有此木屐声。",""],["潇洒青云彦，幽居隔柳樊。\n湖阴通曲径，苔色上高垣。\n帘卷南薰入，窗含夏荫繁。\n脱巾投玉麈，移席倒匏樽。\n凉雨荷香度，晴云树色屯。\n芙蓉交翠叶，薜荔引芳根。\n雪茧乌丝细，霜毫玉箸完。\n笼鹅从换帖，爱鹤敢乘轩。\n休日欣良觌，高怀得细论。\n堆盘朱实润，溢砌紫兰翻。\n属坐仪如凤，挥觚健胜猿。\n雄文三峡水，壮志九溟鹍。\n酒晕开愁颊，茶香醒滞魂。\n风尘江海暗，戎马道途喧。\n杜子无家久，张君有舌存。\n丹心依魏阙，清梦绕天阍。\n寥落悲时事，飘零愧弟昆。\n盍簪萍梗日，曳履缙绅门。\n句压弥明鼎，宴同桃李园。\n银屏酣坐稳，鹦鹉可鲸吞。","潇洒青云彦，幽居隔柳樊。\n湖阴通曲径，苔色上高垣。\n帘捲南薰入，窗含夏荫繁。\n脱巾投玉麈，移席倒匏樽。\n凉雨荷香度，晴云树色屯。\n芙蓉交翠叶，薜荔引芳根。\n雪茧乌丝细，霜毫玉箸完。\n笼鹅从换帖，爱鹤敢乘轩。\n休日欣良觌，高怀得细论。\n堆盘朱实润，溢砌紫兰翻。\n属坐仪如凤，挥觚健胜猿。\n雄文三峡水，壮志九溟鹍。\n酒晕开愁颊，茶香醒滞魂。\n风尘江海暗，戎马道途喧。\n杜子无家久，张君有舌存。\n丹心依魏阙，清梦绕天阍。\n寥落悲时事，飘零愧弟昆。\n盍簪萍梗日，曳履缙绅门。\n句压弥明鼎，宴同桃李园。\n银屏酣坐稳，鹦鹉可鲸吞。"],["酌酒湖阴晚，移床竹径凉。\n高荷凌水碧，幽草入林香。\n问字过从数，联诗叹语长。\n却怀杨宪史，骑马出东坊。",""],["斋居澹心情，分火试香缕。\n纤纤五彩缠，烱烱众星吐。\n初闻疑袭芳，细辨须按谱。\n千条揉金枝，百和杂琼乳。\n本非龙涎收，岂与鸡舌伍。\n烟联玉绳直，雾袅金茎古。\n月斜忽逶迤，风度自飘舞。\n氤氲起丝发，宛转散毛羽。\n眩眸讶窥管，拂鼻欲停麈。\n麝脐远近发，狼燧高下举。\n缲车不可收，蓍草远堪取。\n焰含怪鎗殳，烬过惜𬘓组。\n焦头恍莫救，燃指粲可数。\n萧茎引初焫，艾剂消微炷。\n袖携忆朝回，灺落惊夜午。\n兰膏既异资，庭燎亦殊炬。\n唫长搜韵险，坐久搅怀苦。\n云冷博山空，城楼已三鼓。","斋居澹心情，分火试香缕。\n纤纤五綵缠，烱烱众星吐。\n初闻疑袭芳，细辨须按谱。\n千条揉金枝，百和杂琼乳。\n本非龙涎收，岂与鸡舌伍。\n烟联玉绳直，雾袅金茎古。\n月斜忽逶迤，风度自飘舞。\n氤氲起丝发，宛转散毛羽。\n眩眸讶窥管，拂鼻欲停麈。\n麝脐远近发，狼燧高下举。\n缲车不可收，蓍草远堪取。\n焰含怪鎗殳，烬过惜紃组。\n焦头恍莫救，燃指粲可数。\n萧茎引初焫，艾剂消微炷。\n袖携忆朝回，灺落惊夜午。\n兰膏既异资，庭燎亦殊炬。\n唫长搜韵险，坐久搅怀苦。\n云冷博山空，城楼已三鼓。"],["成均地何灵，圣泽资灌沃。\n兔奔兆奇征，井渫发新斸。\n自非三窟深，孰湛一泓绿。\n储精本从金，生色绝胜玉。\n霜唇蘸寒饮，雪毳翻夜浴。\n酿冽补酒经，沐丹验仙箓。\n杵舂蟾宫弃，珠喷鳣堂触。\n朵月生阴津，观天漏晴旭。\n水澄毛骨竖，鉴彻须眉烛。\n鵵名徒自奇，桧行秽难赎。\n虽涵东郭狡，难洗上蔡辱。\n引满瓶未嬴，探幽绠频续。\n流罂渗银床，出窦溅琼粟。\n醉沃日晕花，冻吸指连瘃。\n濡毫乃自润，照影从人欲。\n光沈天上魄，祥启地中躅。\n摛辞挹馀清，盥荐侑佳告。\n剑刺非贰师，池移岂身毒。\n燕支愧淫陈，盐卤鄙富蜀。\n不动疑雪洼，长摇笑风纛。\n天光一眼开，云影片鳞束。\n剧燕觉瘆?，蹶足想彳亍。\n觱沸虎爪跑，?吸猿臂曲。\n洁士濯冠缨，渴卒卸刀韣。\n精当卯君降，液或井宿督。\n谁知钟阜分，脉与伊洛属。\n锡名尔固佳，战句吾何局。\n联将指鼎比，疾胜击钵促。\n惊风落灯烬，斜月坠檐曲。\n灵源讵能穷，短咏聊可录。","成均地何灵，圣泽资灌沃。\n兔奔兆奇徵，井渫发新斸。\n自非三窟深，孰湛一泓绿。\n储精本从金，生色绝胜玉。\n霜唇蘸寒饮，雪毳翻夜浴。\n酿冽补酒经，沐丹验仙箓。\n杵舂蟾宫弃，珠喷鳣堂触。\n朵月生阴津，观天漏晴旭。\n水澄毛骨竖，鉴彻须眉烛。\n鵵名徒自奇，桧行秽难赎。\n虽涵东郭狡，难洗上蔡辱。\n引满瓶未嬴，探幽绠频续。\n流罂渗银床，出窦溅琼粟。\n醉沃日晕花，冻吸指连瘃。\n濡毫乃自润，照影从人欲。\n光沈天上魄，祥启地中躅。\n摛辞挹馀清，盥荐侑佳告。\n剑刺非贰师，池移岂身毒。\n燕支愧淫陈，盐卤鄙富蜀。\n不动疑雪洼，长摇笑风纛。\n天光一眼开，云影片鳞束。\n剧燕觉瘆?，蹶足想彳亍。\n觱沸虎爪跑，?吸猿臂曲。\n洁士濯冠缨，渴卒卸刀韣。\n精当卯君降，液或井宿督。\n谁知钟阜分，脉与伊洛属。\n锡名尔固佳，战句吾何局。\n联将指鼎比，疾胜击钵促。\n惊风落灯烬，斜月坠檐曲。\n灵源讵能穷，短咏聊可录。"],["池上月凉秋似洗，城头漏转夜如年。\n枳林不动风初定，草叶低垂露正圆。\n移席偶临流水坐，钩帘还对落星眠。\n几时吹笛芙蓉底，更向龙湾棹酒船。",""],["三日不见黄子邕，使我茆塞于心胸。\n书床虚连竹色净，酒斝间覆柳阴浓。\n每于月下重相忆，何事湖边独不逢。\n急欲移书杨宪史，山房须遣白云封。",""],["络纬声如劝饮，筼筜青好题诗。\n风转银灯不动，月来瑶席频移。\n草色亭西晚径，水声篱外秋池。\n此夕龙湾佳会，南楼千载襟期。",""],["圣学何学，天灵天觉。\n睿启颜愚，勇征季诺。\n无知有知，不获乃获。\n虚室白生，澄源觱泼。\n蒲彀其张，虞机自跃。\n觉觉相承，后先率喝。\n意以神传，妙难口说。\n呼寐而醒，聊以提掇。","圣学何学，天灵天觉。\n睿启颜愚，勇徵季诺。\n无知有知，不获乃获。\n虚室白生，澄源觱泼。\n蒲彀其张，虞机自跃。\n觉觉相承，后先率喝。\n意以神传，妙难口说。\n呼寐而醒，聊以提掇。"],["高山尔名，龙岩尔姓。\n尔息尔游，静定动定。",""],["据后天后，悟先天前。\n盘桓盘桓，永矢弗諠。",""],["欲澄尔心，用照尔面。\n既识尔污，尔羞自见。",""],["狂风倏起，埃霾障天。\n阻我中路，微亦有缘。\n狂风且恶，摇摇我衣。\n我脚则定，岂风动则移。",""],["煦煦者和，维时之春。\n物胥以育，于胥海滨。\n胥斯海滨，荣斯欣欣。\n物斯欣斯，矧伊人斯。\n浩浩者流，曰维珠江。\n萃彼百川，其沛滂滂。\n可以济桴，可以载航。\n无曰德则小，谁哉子量。\n丽彼春江，朝阳孔熙。\n彼山则翠，于江之湄。\n中有行舟，其鸣咿咿。\n维鸥鶒则飞，维鸳鹭则飞。\n鸟之扬矣，江之长矣。\n鸟之悦矣，江之阔矣。\n壮哉子观，目云豁矣。\n莫予物违，形之脱矣。\n既载我酒，亦将我殽。\n酌别春江，其情交交。\n其情交交，其行逼逼。\n水岐路分，维子之适。\n作此好歌，以慰戚戚。",""],["明明天子，嘉靖殷邦。\n率地普天，万方来王。\n北虏晨遁，倭奴夕襄。\n矧尔广潮，居国南乡。\n而抗车辙，臂若螗螂。\n明明天子，赫震厥怒。\n我有方文，我有召武。\n桓桓于征，阚如虓虎。\n歼厥渠魁，仍执丑虏。\n俾民突有烟，俾民室斯堵。\n海涛既清，京观峨峨。\n潮方既平，厥功孰多。\n予曰有奔奏，政清人和。\n予曰有奔奏，先驱震那。\n人亦有言，抚制惟烈。\n以峙其粻，戢寇有截。\n维我蔡公，炳先作哲。\n人亦有言，政在元戎。\n以逭其逋，以馁其锋。\n俾获就擒，实维蔡公。\n于惟蔡公，仁而有勇。\n缓带轻裘，不戁不竦。\n大憝既澄，群奸滋恐。\n谁则剥脂，谁则窃俸。\n言奏肤功，蕃锡斯宠。\n爰握政枢，爰司宪总。\n俾霖雨于八方，华夷一统。",""],["曷云不足，曷云有馀。\n物有尽时，同归太虚。\n独这点灵根，流行天地，万古如如。",""],["坐柏之下，晷移八尺。\n期子不来，诵遍姬易。\n槐阴午闲，鸟鸣树间。\n与鹤者游，鹤舞翩反。\n汝鹤汝鹤，能行且飞。\n能作我驾，吾将汝依。","坐柏之下，晷移八尺。\n期子不来，诵遍姬易。\n槐阴午閒，鸟鸣树间。\n与鹤者游，鹤舞翩反。\n汝鹤汝鹤，能行且飞。\n能作我驾，吾将汝依。"],["欲行欲行，顾子行行。\n惯与子亲，子作吾仆。",""],["毋曰隐矣，莫予闻觏。\n川流斯逝，声谷传叩。",""],["广而非旷，高而非迂。\n仰察俯观，泼哉鸢鱼。",""],["洞有鼓钟，泉奏管籥。\n况有嘉朋，云胡不乐。\n以咏以游，载歌载酌。\n仰视青霄，浮云野鹤。\n愿言从之，以永佳约。\n翱翔八虚，谁羁谁缚。",""],["云霾净宿曀，太宇空无垠。\n昭明乃日月，伸诎为鬼神。\n六经岂必作，点画非有文。\n真见亦不见，无闻有至闻。\n摸盘叹冥瞽，听拟徒缤纷。\n我有双莫邪，奋志凌千军。\n同游者谁子，斩钥开重阍。",""],["盈盈沟中潦，赴海浑自多。\n聒聒山涧流，激石扬鸣波。\n夏虫难语冰，井蛙宁谈河。\n蠡管恣窥测，潢渤终殊科。\n达人纵遐视，况陟崇山阿。\n山高望逾迥，海阔环包罗。\n玉宇秋气澄，一色天光和。","盈盈沟中潦，赴海浑自多。\n聒聒山涧流，激石扬鸣波。\n夏虫难语冰，井蛙宁谈河。\n蠡管恣窥测，潢渤终殊科。\n达人纵遐视，况陟崇山阿。\n山高望踰迥，海阔环包罗。\n玉宇秋气澄，一色天光和。"],["伊昔岁戊申，而我寓姑孰。\n送送别梅冈，朱夏月正六。\n今庚六月闰，三金火旋伏。\n执手遽言别，曳舄黄山麓。\n飔飔袭璚树，冷冷漱湍玉。\n入火能不炎，即此良自足。\n聊以把赠君，一洗烦与酷。",""],["康时在长策，会合良所难。\n霜蹄信奇捷，岂困槽枥间。\n君今入承明，驱车出齐山。\n浮云敛天末，长风纵飞翰。\n东南满疮痍，愿言借神丹。\n款语开宸旒，无为空叩关。",""],["玉女开澄潭，璇房閟枌栱。\n高阁倚千寻，遐观目可纵。\n悬厓有奇树，似是飞仙种。\n缥渺架壑桥，临之神欲恐。\n渊渊岂无源，伏流藏其用。\n中有素心人，默与澄潭共。",""],["矫矫凌寒姿，竹梅并萧爽。\n徙倚挹清芬，宴坐绝尘想。\n佳兴动官阁，清阴入书幌。\n太极天窍露，长歌澳风响。\n愿言肖令德，岂直颜色仿。\n清时不避地，聊焉托孤往。",""],["泉出漱玉轩，奔流迤东首。\n水石固有所，行遇嗔相偶。\n天河落万丈，直出龙门口。\n砥柱屹不动，壮哉遏湍浏。\n乍惊龙马饮，下破虬鼍走。\n此可凭观澜，君莫笑迂朽。",""],["晓渡漱玉桥，凝眸立溪涘。\n中有古璚树，莫自开天始。\n磊砢四十围，经吟独孤史。\n樗散每见掷，嘉乐有君子。\n北山秀豫樟，几见复同此。\n君莫悲明堂，空谷良足喜。",""],["奋羽凌仙台，芙蓉最高级。\n招手期众仙，二姑闯来集。\n悠然脱苍弁，岂为长缨絷。\n道旁遇果老，遥下青骡揖。\n琼株映双洞，云气互嘘吸。\n罗浮有佳址，宛宛故相及。",""],["风雨拿小舟，侧瞰龙湫洞。\n中空幻层室，石髓结融湩。\n跨犀出君阳，佳境谁伯仲。\n伏水浮盘来，白龙宛迎送。\n漏石错蹄股，冰瑶自隆栋。\n水声答啸和，谷神两茫偬。",""],["六管嘘芦灰，万壑动春意。\n旋整舞雩衫，疑醉兰亭觯。\n鲁戈如可挥，羲驭当还辔。\n独立留仙桥，青鸟忽来异。\n吾欲鞭石羊，一障狂澜驶。",""],["石窍通玄冥，云是禅僧窟。\n有时发祥光，影漏西方月。\n一叶波心度，菩提手中揭。\n自能灭相火，渐见离白骨。\n却笑红尘隈，有人系缨笏。",""],["风雷敛太虚，偃卧山中石。\n雷风动地起，转泽沟中瘠。\n卷舒亦何心，暗与通消息。","风雷敛太虚，偃卧山中石。\n雷风动地起，转泽沟中瘠。\n捲舒亦何心，暗与通消息。"],["千金重一瓢，借我中流度。\n觉岸倘先登，游刃与时措。\n东西南北辕，适国为大道。\n行矣慎所之，无惑多岐路。",""],["时事百忧逼，放下还全休。\n况兹得归来，驾言值高秋。\n罗浮两股合，猿鹤故悠悠。\n天末金飙起，嶂外浮云收。\n诸生夙同约，四美兼来遒。\n仰止山愈近，步步从公游。\n始入朱明庐，载陟青霞丘。\n层楼敞明觉，盼远舒长愁。\n越宿瞻天华，藻苹荐前修。\n四贤可五七，志愿刚应酬。\n仙人煮白石，至坚亦能柔。\n为山始一篑，峻极何足忧。","时事百忧逼，放下还全休。\n况兹得归来，驾言值高秋。\n罗浮两股合，猿鹤故悠悠。\n天末金飙起，嶂外浮云收。\n诸生夙同约，四美兼来遒。\n仰止山愈近，步步从公游。\n始入朱明庐，载陟青霞丘。\n层楼敞明觉，盼远舒长愁。\n越宿瞻天华，藻蘋荐前修。\n四贤可五七，志愿刚应酬。\n仙人煮白石，至坚亦能柔。\n为山始一篑，峻极何足忧。"],["长江纵一叶，飒然御天风。\n凌晨出层城，信宿龙潭东。\n崇楼瞻斗岳，匝院长麻蓬。\n山光四抱合，水势潆回冲。\n迩吞凤凰台，远瞰天华宫。\n潭深潜海若，雨化乘丰隆。\n气类重孚感，云龙故相从。\n出门旷于野，入室殊归同。\n自然匪人力，大造天为工。\n前茅既有作，继继当无穷。",""],["皇风泛遐轨，周道丛榛芜。\n太羹杂浓胾，澄源变潢污。\n谁将挽颓流，崄巇共匡扶。\n缅怀在西方，美人挹子都。\n棠荫弘仁渥，嘤鸣故相呼。\n华筵敞薇幄，旨酒芬醒壶。\n邺中启寒盟，建安美朋徒。\n皎皎玉树林，而乃容葭莩。\n八月天气佳，四美良且俱。\n岂直驰艺苑，引我康庄涂。\n康庄在何许，倚衡见中孚。\n堂颜卓克念，允矣千圣谟。\n愿言各努力，至德恒不孤。",""],["生来托孤根，滋培得深护。\n朱夏花殷红，尔独守贞素。\n逢时试一开，沾沾雨和露。\n晓晴朝暾披，夜月流光布。\n清阴能几何，停停矢自固。\n本无摘实功，而岂争妍妒。\n移根且归来，植向空齐路。\n观生生不穷，趋庭步亦步。\n旧时冰雪肌，犹向苍根吐。\n喜尔瘦且癯，不为缁尘污。\n扬州鹤本无，大嚼谁能副。\n酌水一劝之，清风时自度。\n清白如可传，姚魏宁荣慕。",""],["玑台树玉表，影远肖其形。\n怀哉百世遥，能否见韶英。\n沨沨听遗响，所喜集大成。\n太和运元气，芳绪垂六经。\n吾将绘天地，荡荡谁能名。",""],["精力苦日短，乘闲强登眺。\n登山陟其顶，倚云发孤啸。","精力苦日短，乘閒强登眺。\n登山陟其顶，倚云发孤啸。"],["有客时扣门，云是商山侣。\n石鼎旋烹茶，对之共玄语。",""],["送尔今出门，挟策游帝京。\n长途慎初步，屋漏通明庭。",""],["送尔今出门，行行守清素。\n举足不违亲，便是趋庭度。",""],["通家二三伴，楚楚同年子。\n愿言升公同，同寅赓喜起。",""],["新剑始出匣，老剑频濯磨。\n共斩长桥蛟，于焉息鲸波。",""],["澄渟开一鉴，树色隐秋光。\n暑气晨迎涤，柔飔晚送凉。\n扁舟荡兰桨，淼淼蒹葭苍。\n美人浑在望，疑隔水中央。",""],["筑室远城市，入山如未深。\n林坰有黄鸟，为我贻清音。\n欲拊来仪石，和之无弦琴。\n调高不可作，冥然谐素心。",""],["南国憩棠阴，东人歌九罭。\n胡不信宿留，而遄西行迹。\n轮辕相附依，封疆良匪逖。\n八桂清狼烟，海隅藉肩息。",""],["蹑足登崇台，九级凌云巅。\n天高望逾迥，斗极玑环璇。\n肃肃栖乌署，明明柱史篇。\n行行重远适，宛宛参吾前。","蹑足登崇台，九级凌云巅。\n天高望踰迥，斗极玑环璇。\n肃肃栖乌署，明明柱史篇。\n行行重远适，宛宛参吾前。"],["把握重贞素，真精焕其光。\n嘘噫气靡定，瞬息异炎凉。\n太和吾自有，舒卷亦何常。\n秋入吾已捐，盛时子相将。\n持此去酷吏，于以报君王。","把握重贞素，真精焕其光。\n嘘噫气靡定，瞬息异炎凉。\n太和吾自有，舒捲亦何常。\n秋入吾已捐，盛时子相将。\n持此去酷吏，于以报君王。"],["罗浮薄青霄，掩映西樵峰。\n百川汇南海，淼淼银潢通。\n匪且萃珍贝，清淑人文钟。\n前茅驾张崔，奕奕驱长风。",""],["送送登仙舟，珠海晴不波。\n卷尔天山易，听我粤社歌。\n处以同心合，出以同心和。\n行矣济时泰，包荒用冯河。","送送登仙舟，珠海晴不波。\n捲尔天山易，听我粤社歌。\n处以同心合，出以同心和。\n行矣济时泰，包荒用冯河。"],["粤秀山南麓，名贤两庙开。\n太极披图蕴，通书启圣胎。\n三才兼两立，一要藉深培。\n谁复浑沦秘，渔歌紫水隈。\n蒲茵穿钓席，碧玉育英才。\n道东原有属，狂简岂无裁。\n哲人嗟并远，瞻仰思悠哉。\n心灵今古共，筌蹄祇群猜。\n欲洗从前障，依归斗与台。",""],["别子粤山隅，送子珠江涘。\n瞬息万里行，帆张一何驶。\n勉哉绳先公，鞅辙故相似。",""],["长才驾大宇，谈吐悬长河。\n到海百折心，不落漩与涡。\n狂澜须汝砥，世路慎风波。",""],["玉河夙泂酌，天关叩堂室。\n鄞水文献邦，天真浚源窟。\n大道不尔孤，同心应超忽。",""],["莫邪剸犀革，严锋畜玭琫。\n明镜开煌煌，玉台戢其用。\n试看中天辉，昨宵发空洞。",""],["昔年五十三，赐老致所仕。\n今蒙致仕恩，年光六十二。\n先致致国猷，再致委家计。\n天地一闲身，何物能撄系。\n炯炯方寸心，愿从子绝四。\n太虚净无云，往来任光霁。","昔年五十三，赐老致所仕。\n今蒙致仕恩，年光六十二。\n先致致国猷，再致委家计。\n天地一閒身，何物能撄系。\n炯炯方寸心，愿从子绝四。\n太虚净无云，往来任光霁。"],["床头微雨过，月光透桐影。\n徘徊步玉除，徙倚绝人境。\n洒落三五星，亏蔽微明景。\n隋珠惜所投，贝叶翻来冷。\n润渥已不多，离披孰为整。\n感此偶适逢，悠然发深省。\n阴晴本无常，明晦须臾顷。\n风雨任时变，太虚自悬迥。\n刮垢镜斯晃，去醨酲乃醒。\n请看蟾蜍光，万古飞云巅。",""],["蒸湘江口合，古院辟江埏。\n悬厓挺古木，栋宇撑云烟。\n朱张昔嘉会，七日浑何言。\n昌黎一过耳，勒石仍诗篇。\n明明湛夫子，耋颐再腾骞。\n予齿日以暮，愿言执前鞭。\n嘤鸣和伐木，出谷拟乔迁。\n吉仁二山长，两凤苞文鲜。\n鸣阳与戢羽，无计远招延。\n道左见棣杜，我心良忧煎。\n且去探天柱，凌风蹑其巅。\n漫与天者游，默默归玄玄。",""],["衡岳山本高，岂待奇幻征。\n天柱俨颅脊，祝融储真精。\n七十二关节，节节含英灵。\n神潜本无朕，化行互充盈。\n有时作云雨，有时鼓风霆。\n恍然明睿启，倏忽晦蒙萦。\n一日三时变，化机曷其停。\n扩之育万物，肇资生以成。\n三广联地轴，五岭交青冥。\n元气时磅礴，太和自薰蒸。\n肃拜轻千里，瓣香曷为情。\n吾生素已祷，谅兹格明馨。","衡岳山本高，岂待奇幻徵。\n天柱俨颅脊，祝融储真精。\n七十二关节，节节含英灵。\n神潜本无朕，化行互充盈。\n有时作云雨，有时鼓风霆。\n恍然明睿启，倏忽晦濛萦。\n一日三时变，化机曷其停。\n扩之育万物，肇资生以成。\n三广联地轴，五岭交青冥。\n元气时磅礴，太和自薰蒸。\n肃拜轻千里，瓣香曷为情。\n吾生素已祷，谅兹格明馨。"],["石翁钓江门，所志在衡岳。\n拟踏祝融峰，终老恒此乐。\n云胡菽水羁，神游梦虚托。\n厥后甘泉师，黾勉承先觉。\n白沙建祠亭，此愿酬昔昨。\n闻者有兴起，斯道愈弘扩。\n顾予何人斯，仰述愧前作。\n瞻拜重踌躇，愿言鞭矍铄。",""],["山深路且长，吾兹扣贤扃。\n二贤不可作，三匝绕前庭。\n此地方而广，人杰地滋灵。\n方从直内出，广乃阖中生。\n惟神无方体，荡荡应难名。\n二贤夙昔讲，渺渺云何征。\n神交已夙昔，千里还合并。\n岂在言语间，意气相薰蒸。\n时来二三子，深造同此行。\n心期旷百代，真感讵骸形。","山深路且长，吾兹扣贤扃。\n二贤不可作，三匝绕前庭。\n此地方而广，人杰地滋灵。\n方从直内出，广乃阖中生。\n惟神无方体，荡荡应难名。\n二贤夙昔讲，渺渺云何徵。\n神交已夙昔，千里还合并。\n岂在言语间，意气相薰蒸。\n时来二三子，深造同此行。\n心期旷百代，真感讵骸形。"],["宇宙本一家，万物吾同体。\n痛痒长相关，岂其隔道里。\n海滨怅泬寥，翩翩兹焉至。\n幸是出门交，视我犹同气。\n恨不久相依，分携若割臂。\n愿言永同心，勿予远遐弃。\n为师如为父，继志以述事。",""],["衡山始倾盖，即结同心盟。\n渊源吉阳翁，单父流政声。\n揖予论圣学，援言多明征。\n予言学晦久，常觉乃常明。\n觉岂自外求，良知启灵扃。\n浮云撤重蔽，太虚自流形。\n仕学岂两涂，尸居凛明庭。\n惭予固谫劣，岂足窥微精。\n一贯垂孔训，日新诵盘铭。","衡山始倾盖，即结同心盟。\n渊源吉阳翁，单父流政声。\n揖予论圣学，援言多明徵。\n予言学晦久，常觉乃常明。\n觉岂自外求，良知启灵扃。\n浮云撤重蔽，太虚自流形。\n仕学岂两涂，尸居凛明庭。\n惭予固谫劣，岂足窥微精。\n一贯垂孔训，日新诵盘铭。"],["扁舟驾长风，道遇武冈守。\n烨烨俨凤仪，芬芬佩兰揉。\n因之衔舻尾，载月驰清溜。\n细与话同心，倾盖恍然旧。\n忆昔赤壁游，几人共杯酒。\n扣舷吹洞箫，水月空明偶。\n一苇纵所如，岂能事拘纽。\n霸业归寒灰，长江赋同久。\n今古几人豪，与君重携手。",""],["黄龙古洞天，旧雨剪新蹊。\n切磋此幸同，一体真犹台。\n夜光发长炬，海派涓滴微。\n看境不在山，挹酒不在卮。\n天空月如洗，云净山偏奇。\n杖策信所往，高深惟其宜。\n惓惓不忍别，万古订心期。",""],["天地本无言，万物自化生。\n美利利天下，保合归鸿冥。\n弥纶六合普，岂大色与声。\n造化吾具足，空虚亦何名。\n所以圣门学，默识阐其精。\n赐也匪不敏，性道晚斯聆。\n如愚有颜子，斋心顿忘情。\n圣衷念念契，万祀师其贞。\n多言每多蔽，常晦始常明。\n戒哉慎尔言，毋徒发盈庭。",""],["夜发汾水阳，凌晨舣樵麓。\n七十有二峰，矗矗凝云簇。\n关路盰翳门，肩舆涉坂曲。\n泉师正开先，而我冼子属。\n钓石凄寒泉，水帘卷飞瀑。\n更有壁立岩，天门窍一簇。\n转路跻云门，整衣谒云谷。\n缘阶入大科，登楼见堂局。\n万派一派通，四峰一峰足。\n周罗俯儿孙，潇森秀琅玉。\n洞左迤九龙，蛇蜒亦九曲。\n铁泉可濯缨，广朗迥怡目。\n仰宸俨威颜，怀沙绍芳躅。\n悠悠重我思，寤寐耿怀服。\n愿借半席光，嵚岑搆居屋。","夜发汾水阳，凌晨舣樵麓。\n七十有二峰，矗矗凝云簇。\n关路盰翳门，肩舆涉坂曲。\n泉师正开先，而我冼子属。\n钓石凄寒泉，水帘捲飞瀑。\n更有壁立岩，天门窍一簇。\n转路跻云门，整衣谒云谷。\n缘阶入大科，登楼见堂局。\n万派一派通，四峰一峰足。\n周罗俯儿孙，潇森秀琅玉。\n洞左迤九龙，蛇蜒亦九曲。\n铁泉可濯缨，广朗迥怡目。\n仰宸俨威颜，怀沙绍芳躅。\n悠悠重我思，寤寐耿怀服。\n愿借半席光，嵚岑搆居屋。"],["干即吾之父，坤即吾之母。\n性体父母遗，藐然兹下土。\n民皆吾同胞，物乃吾侪与。\n天下本一家，兄弟浑散处。\n顾彼有我私，藩篱隔抵牾。\n岂不均属毛，岂不均离里。\n大君乃嫡子，约法族所宗。\n大臣家之相，协力胥寅共。\n卑弱幼吾幼，高年长吾长。\n鳏寡残疾徒，兄弟失所仰。\n在我宜抚之，我心重养养。\n贤圣乃克肖，济恶何不才。\n害仁与悖德，兄弟良可哀。\n安得顿革奸，烝乂以不回。\n有怀日匪懈，无忝馀所生。\n明发耿不寐，靡靡迈以行。\n愿言顾常棣，骨肉情相亲。\n兄弟乐且孺，以慰予二人。\n吁嗟酿失德，干糇不以分。\n剖柑贵同味，有无安足论。\n闭门独腹饱，同室私啼饥。\n膏粱岂不甘，吾心亦以悲。\n同室私号寒，吾身独缊燠。\n裘帛岂不安，已颦亦以蹙。\n小忿萌懿亲，阋墙忽相搆。\n被发缨我冠，救之尚恐后。\n况乃手相刃，溅血濡禁庭。\n田地本易得，同气何相倾。\n相彼豆与萁，相煎乃太急。\n我生念同根，隐忧涕以泣。\n相彼一尺布，缩缩亦可缝。\n乃尔弟与兄，云胡不相容。\n怀哉百忍子，同居睦且久。\n遵彼李氏谟，钱帛不私有。\n愿作长枕被，寒暄共依依。\n炙艾以分痛，四海疗疮痍。\n兄弟各得所，父母当怡怡。\n百犬均同牢，物我非尔私。","乾即吾之父，坤即吾之母。\n性体父母遗，藐然兹下土。\n民皆吾同胞，物乃吾侪与。\n天下本一家，兄弟浑散处。\n顾彼有我私，藩篱隔牴牾。\n岂不均属毛，岂不均离里。\n大君乃嫡子，约法族所宗。\n大臣家之相，协力胥寅共。\n卑弱幼吾幼，高年长吾长。\n鳏寡残疾徒，兄弟失所仰。\n在我宜抚之，我心重养养。\n贤圣乃克肖，济恶何不才。\n害仁与悖德，兄弟良可哀。\n安得顿革奸，烝乂以不回。\n有怀日匪懈，无忝馀所生。\n明发耿不寐，靡靡迈以行。\n愿言顾常棣，骨肉情相亲。\n兄弟乐且孺，以慰予二人。\n吁嗟酿失德，乾糇不以分。\n剖柑贵同味，有无安足论。\n闭门独腹饱，同室私啼饥。\n膏粱岂不甘，吾心亦以悲。\n同室私号寒，吾身独缊燠。\n裘帛岂不安，已颦亦以蹙。\n小忿萌懿亲，阋墙忽相搆。\n被发缨我冠，救之尚恐后。\n况乃手相刃，溅血濡禁庭。\n田地本易得，同气何相倾。\n相彼豆与萁，相煎乃太急。\n我生念同根，隐忧涕以泣。\n相彼一尺布，缩缩亦可缝。\n乃尔弟与兄，云胡不相容。\n怀哉百忍子，同居睦且久。\n遵彼李氏谟，钱帛不私有。\n愿作长枕被，寒暄共依依。\n炙艾以分痛，四海疗疮痍。\n兄弟各得所，父母当怡怡。\n百犬均同牢，物我非尔私。"],["五行橐天地，黄土为中央。\n五德钟人心，惟信为之纲。\n所以信属友，以友经天常。\n迁鸟求友声，甡鹿俟且行。\n何必重踽踽，杕杜无与双。\n所贵在择交，丽益相磨光。\n不辨菽麦者，疏粺集为粮。\n一膜已胡越，肺腑那相将。\n谷风动遗叹，下石徒悲伤。\n颓波岂无源，势利泊以泷。\n饮食共征逐，策赛均亡羊。\n结好盟骨肉，懋恶摩矛斨。\n不念松柏枝，风霜何凉凉。\n茑罗一相附，固结不可忘。\n勿以炙热趍，贻灾焚昆冈。\n勿以寒谷避，层阴发和阳。\n天鉴亦孔昭，循转自相当。\n安得归说人，怆恍忧以痒。",""],["浣衣惠山泉，回舟访玉女。\n飘发东南来，翻然作霖雨。\n山灵岂妒客，徉徜固相拒。\n谷口云空蒙，玉潭杳何许。\n青鸟衔书至，开缄诵细语。\n玉女不出山，云震重夙侣。\n懒散云鬟装，采药时倾筥。\n闻君突然至，走讶仍却沮。\n落莫洗头盘，莓苔半沮洳。\n谁为膏沐资，九天借兰湑。\n栉罢时褰帷，出门重延伫。\n君行五月蒸，得无惮轩举。\n再叱呵云师，为君涤烦暑。\n侧径尘不扬，短葛生凉踽。\n君莫畏沾濡，重湿裳与黼。\n我有鹤氅衣，雰雰振零羽。\n君莫畏泥滑，长桥架河浒。\n我有九节杖，步步君堪拄。\n客子划然笑，长追入云里。\n玉女明且都，凝然快双睹。\n莫是登天庭，尘寰隔下土。\n洗心向澄潭，授我素问谱。\n揽衣不可留，长揖归仙府。\n玉女不可见，再拜玉阳主。\n洞天何时开，玉虚敞堂宇。\n周罗布羲画，群阳互三五。\n蹑足澄观楼，八窗玲珑俯。\n远山失前峰，近山觉环屿。\n地底殷鸣雷，奔湍击石鼓。\n晶光泽琪树，黛色隐灵榉。\n花重枝稀垂，竹低笋芽竖。\n滴滴松虬香，黯黯栗蜂午。\n稚儿竞奔跣，戴笠向庄妪。\n摘茶且抱瓮，旋汲新泉煮。\n山翁献猴果，野虞贡獐脯。\n畦蔬入蔟肥，石窍分香乳。\n且倒莲花樽，共究玄黄理。\n剪烛话未央，庭树鸡声曙。","浣衣惠山泉，回舟访玉女。\n飘发东南来，翻然作霖雨。\n山灵岂妒客，徉徜固相拒。\n谷口云空濛，玉潭杳何许。\n青鸟衔书至，开缄诵细语。\n玉女不出山，云震重夙侣。\n懒散云鬟装，采药时倾筥。\n闻君突然至，走讶仍却沮。\n落莫洗头盘，莓苔半沮洳。\n谁为膏沐资，九天借兰湑。\n栉罢时褰帷，出门重延伫。\n君行五月蒸，得无惮轩举。\n再叱呵云师，为君涤烦暑。\n侧径尘不扬，短葛生凉踽。\n君莫畏沾濡，重湿裳与黼。\n我有鹤氅衣，雰雰振零羽。\n君莫畏泥滑，长桥架河浒。\n我有九节杖，步步君堪拄。\n客子划然笑，长追入云里。\n玉女明且都，凝然快双睹。\n莫是登天庭，尘寰隔下土。\n洗心向澄潭，授我素问谱。\n揽衣不可留，长揖归仙府。\n玉女不可见，再拜玉阳主。\n洞天何时开，玉虚敞堂宇。\n周罗布羲画，群阳互三五。\n蹑足澄观楼，八窗玲珑俯。\n远山失前峰，近山觉环屿。\n地底殷鸣雷，奔湍击石鼓。\n晶光泽琪树，黛色隐灵榉。\n花重枝稀垂，竹低笋芽竖。\n滴滴松虬香，黯黯栗蜂午。\n稚儿竞奔跣，戴笠向庄妪。\n摘茶且抱瓮，旋汲新泉煮。\n山翁献猴果，野虞贡獐脯。\n畦蔬入蔟肥，石窍分香乳。\n且倒莲花樽，共究玄黄理。\n剪烛话未央，庭树鸡声曙。"],["携家向玉阳，是处即吾里。\n砌台养云蓍，当门植桐梓。\n峧谷希足音，寤歌独永矢。\n聒聒飞玉泉，聊藉洗尘耳。\n抱志三十年，日月惊逝矣。\n周文杳西郊，希夷卧未起。\n执易登玉虚，无言隐玉几。\n扣开后天门，直透先天里。",""],["望望太湖峰，烟云杳相阻。\n缥缈凭孤亭，聊为散烦暑。\n左引碧玉盘，云浆映霞醑。\n右招众灵集，凤麟舞前署。\n王母西献桃，仙姑送羞髓。\n去去凌超然，中天豁眸矃。",""],["晴林漏疏日，下荡岩光连。\n入观悟明水，出盼罗诸天。\n青牛幸一过，百世非无缘。\n睡法传希夷，愿借凭虚眠。\n云笙肃高调，霓裳舞翩跹。\n翻身入蓬莱，悠然对群仙。",""],["何物观世音，灵岩重出世。\n炼性洪悲慈，岂能顾睚眦。\n玉莲座下起，珠黍空中系。\n本来已无种，谁将拟根柢。\n善材一撒手，金刚亦失势。\n行矣扣狮子，业缘了诸切。","何物观世音，灵岩重出世。\n炼性洪悲慈，岂能顾睚眦。\n玉莲座下起，珠黍空中繫。\n本来已无种，谁将拟根柢。\n善材一撒手，金刚亦失势。\n行矣扣狮子，业缘了诸切。"],["钟山郁龙蟠，天阙开牛首。\n康作承累朝，积养百年后。\n焕发征人文，济士兴如云。\n探玄窥孔室，奋藻摛皇坟。\n猗嗟公善鸣，结发驰上京。\n一策惋流涕，五规赞綦平。\n螭蚴昂独立，牡辔代巡省。\n破柱狼途冲，逊舄鳄潮境。\n天王幸圣明，诏许图终成。\n贞心矢珉铁，唾迹随风萍。\n棠阴重遗爱，玉笋跻崇班。\n握符靖闽越，勒迹旗常间。\n阴晴知雪𬀪，急流遄归饯。\n虞山旧考槃，种竹傍巍𪩘。\n跃渚常观鱼，兢冰重履虎。\n亹亹未敢荒，休休自适取。\n小子罗浮阿，藐兆何足多。\n涓涘翕河岳，意气绸茑萝。\n海虞迩行乐，降陟观泉壑。\n傍柳移小舟，清风访庄落。\n仰止盂巅期，绻复圯桥约。\n小子诚不聪，勉旃宁自薄。","钟山郁龙蟠，天阙开牛首。\n康作承累朝，积养百年后。\n焕发徵人文，济士兴如云。\n探玄窥孔室，奋藻摛皇坟。\n猗嗟公善鸣，结发驰上京。\n一策惋流涕，五规赞綦平。\n螭蚴昂独立，牡辔代巡省。\n破柱狼途冲，逊舄鳄潮境。\n天王幸圣明，诏许图终成。\n贞心矢珉铁，唾迹随风萍。\n棠阴重遗爱，玉笋跻崇班。\n握符靖闽越，勒迹旂常间。\n阴晴知雪晛，急流遄归饯。\n虞山旧考槃，种竹傍巍巘。\n跃渚常观鱼，兢冰重履虎。\n亹亹未敢荒，休休自适取。\n小子罗浮阿，藐兆何足多。\n涓涘翕河岳，意气绸茑萝。\n海虞迩行乐，降陟观泉壑。\n傍柳移小舟，清风访庄落。\n仰止盂巅期，绻复圯桥约。\n小子诚不聪，勉旃宁自薄。"],["桑榆收暮景，旸谷曙光升。\n日中盈就昃，既晦当复明。\n屈伸本循环，欲亨守其贞。",""],["完璞日已琢，天性民不虞。\n岂无煨中烬，六籍空遗书。\n抚卷发浩叹，愿言见子都。\n之子在何方，山高水难逾。\n幸有乘木质，岂徒饰轮舆。\n招招利载者，曷不吾与俱。\n怅怅独云迈，一行一踟躇。\n前川渐佳境，少乐众不如。\n岐端误失道，适足丛蓁芜。\n行矣慎所之，勿使纷忧娱。\n告汝利载者，与尔良不疏。\n勉旃觅子睹，窈纠当复舒。","完璞日已琢，天性民不虞。\n岂无煨中烬，六籍空遗书。\n抚卷发浩叹，愿言见子都。\n之子在何方，山高水难踰。\n幸有乘木质，岂徒饰轮舆。\n招招利载者，曷不吾与俱。\n怅怅独云迈，一行一踟躇。\n前川渐佳境，少乐众不如。\n岐端误失道，适足丛蓁芜。\n行矣慎所之，勿使纷忧娱。\n告汝利载者，与尔良不疏。\n勉旃觅子睹，窈纠当复舒。"],["青松何郁郁，山石何崔嵬。\n下有皤然翁，煮石丹霞隈。\n火烘六逾纪，鼎沸初一回。\n千年捣为脂，万年结成胎。\n皎皎碧玉翰，不以凌风埃。\n顿息青松根，鼓鼾声如雷。\n一息春叶落，再息蟠桃开。\n起觉陵谷迁，洞口空莓苔。\n莫是王子乔，拂舄从天来。","青松何郁郁，山石何崔嵬。\n下有皤然翁，煮石丹霞隈。\n火烘六踰纪，鼎沸初一回。\n千年捣为脂，万年结成胎。\n皎皎碧玉翰，不以凌风埃。\n顿息青松根，鼓鼾声如雷。\n一息春叶落，再息蟠桃开。\n起觉陵谷迁，洞口空莓苔。\n莫是王子乔，拂舄从天来。"],["仰止中离山，欲泛惠江艇。\n叱仆驱前途，问道丰湖境。\n东有白鹤峰，西有黄洞岭。\n半径通湖光，双江蘸云影。\n美人宛中央，苍洲隔芳艼。\n漱玉流且湍，归云日将暝。\n韶华迅以逝，逍遥复能拯。\n过客悲邮亭，对子良独省。",""],["云汉矫鸿鹄，樛枝集鹩雀。\n阔视齐物篇，隘迹堪舆博。\n候人重何戈，择仕贵击柝。\n职称谅所宜，官卑亦不恶。\n西湖故佳胜，而子足欣乐。\n况有说驾贤，未肯封人却。\n抗志昂藏间，翻飞向寥廓。",""],["种松护林麓，引泉出林陬。\n餴饎煮白石，驾驷腾苍虬。\n可以同岁寒，宁知有春秋。",""],["直北三四星，祥光射南极。\n中有一老人，子孙布云奕。\n弧矢驰四方，文章烂奎壁。\n老人复何事，散发卧松石。\n朝汲丹霞浆，莫饮盘露滴。\n古洞盟千年，双凫驾飞舄。",""],["朝诵湘累篇，夜闻惜颜操。\n俯仰怀哲人，感慨悲长道。\n所遇固有穷，馀芬岂同耗。\n壮哉蓝氏子，抗志跻堂奥。\n千里负琴书，远向罗浮到。\n良冶开铸炉，品物欣洪造。\n飞云顶未穷，薤露歌先报。\n菀结同心言，邈矣将谁告。\n达人宇为家，易地皆吾靠。\n莫更嗟罗浮，朱明有丹灶。",""],["夙驾迎春来，孰报春归去。\n斗酒欲送春，流莺唤留住。\n春去来几时，春光常在树。\n寒谷生融辉，枯杨复枝旟。\n眷此增徘徊，相期本无语。",""],["踞榻罗浮峰，曾识博罗簿。\n遗爱垂贞珉，大道式章甫。\n委吏尚可为，况乃民父母。\n子行适京山，勉旃在师古。",""],["五羊奔走地，双阙空蒙隈。\n卧游托殷勤，信步空迟回。\n振衣陟嶙峋，滑履欹莓苔。\n岂无葛仙骨，已养罗浮胎。\n何当妒阴雨，隐谷鸣春雷。\n愿言借晴明，极盼穷纮垓。\n且向虎跑泉，静洗尘寰埃。\n菩提识灵种，宝塔凌虚台。\n笑呼猿鹤群，对舞欢徘徊。","五羊奔走地，双阙空濛隈。\n卧游托殷勤，信步空迟回。\n振衣陟嶙峋，滑履欹莓苔。\n岂无葛仙骨，已养罗浮胎。\n何当妒阴雨，隐谷鸣春雷。\n愿言借晴明，极盼穷纮垓。\n且向虎跑泉，静洗尘寰埃。\n菩提识灵种，宝塔凌虚台。\n笑呼猿鹤群，对舞欢徘徊。"],["爽籁晴潇湘，轻绡映寒碧。\n节高风自清，中虚体常直。\n何物撑嶙峋，无乃玉屏石。\n依此盘错根，砥砺时相益。\n愿得歌卫风，□□□□□。\n对此图淇澳，千年仰圭璧。",""],["忠诚未格天，大风撼我舟。\n志仁幸安土，长滩若为留。\n柔泥不着石，傲睨登瀛洲。\n鸡鸣黯月色，龙眠聒惊流。\n滔天玉雪涌，拍拍驱群牛。\n樯颠楫欲摧，衣袽戒且忧。\n却忆淮浦吟，整襟法前修。\n须臾藉晴曙，长空敛云浮。\n青山秀绿树，沽酒听渔讴。\n眷眷侧席怀，至德侔商周。\n干城有元老，克壮咸嘉猷。\n蠢虏诚匪茹，大邦敢为仇。\n风狂不过日，阳出阴旋收。\n岂尔螳螂资，乃肆当辙游。\n直捣向贺兰，勒石燕然陬。\n四海瞻皇图，万年固金瓯。",""],["罗浮亘天地，与子聊相违。\n冥鸿事高举，奚必差池飞。\n居诸遄流迈，起卧观时几。\n适意亦自得，是处真谁非。\n首阳与莘墅，千古争巍巍。\n丘隅鸟所止，民乃同邦畿。",""],["袅袅驰虚车，钟陵寄檀轴。\n报国惭匪才，阅人惯迂目。\n几见大道周，平陂往还复。\n旷野栖麟凤，幽岩足虺蝮。\n阴晴互态变，暑雨迭寒燠。\n我爱王阳冈，坦坦夷边幅。",""],["宰我对问社，误看周人栗。\n千载嘘遗风，竞言淬刀笔。\n吹疵摘细故，脔胾凌万物。\n哀我同胞民，楚钳剥肤骨。\n谁将一拯之，春和布穷窟。\n我爱王阳冈，明刑在钦恤。",""],["朝登采石矶，莫宿采石祠。\n俯仰百代豪，风流尚依依。\n解靴挫力士，秉砚轻蛾眉。\n蕃夷信桀骜，一纸馀麾披。\n渔阳有鼙鼓，何乃旋致之。\n才高世难用，宠过忌亦随。\n祢生老瞒沮，贾傅文皇师。\n英辙固同迈，羁靮良所宜。\n世有万镒珍，愿我戢光辉。",""],["驱车出滇左，道旁式齐衰。\n棘挛眷容墨，黯惨令心哀。\n停车急前步，问子从何来。\n云是永昌产，奔奔蜀中回。\n忆昔乃父翁，蹑足青云垓。\n鸣琴播遗响，振铎群英才。\n刑于拟逑德，胆丸亦滋开。\n闵子绍泮涣，接武鞭驽骀。\n春官弃桃李，荣阳藉深培。\n青毡席亦暖，白发颜双颓。\n昊天杳何极，北风吹崔嵬。\n心折道路长，靡靡行且猜。\n披襟诉明府，泪血倾河隈。\n予闻转酸恻，欲语徒邅回。\n为子废蓼莪，且陟阿丘台。",""],["人言一日养，不以三公换。\n况乃桑梓邦，王藩作明宦。\n禄养既尽欢，承颜复泮奂。\n礼乐诚嘉猷，河间即东献。\n贾传良足师，临湘莫重叹。\n治安策可陈，早为明廷赞。",""],["东海驱灵鳌，蓬山驾浮岛。\n千里赴所思，硕人丘中老。\n钓竿卷周纶，畏涂释商缴。\n跃鳞纵深渊，飞鸿信派爪。\n孔操鸣猗兰，王孙履芳草。\n爰有九节根，服之以终老。","东海驱灵鳌，蓬山驾浮岛。\n千里赴所思，硕人丘中老。\n钓竿捲周纶，畏涂释商缴。\n跃鳞纵深渊，飞鸿信派爪。\n孔操鸣猗兰，王孙履芳草。\n爰有九节根，服之以终老。"],["太一判元始，百川汇鸿蒙。\n淼淼甲子门，吞吐骊龙宫。\n鼓入珠江潮，堑隔陀城东。\n纳污本无意，洗日谁言功。\n凭高寄遐瞩，爽豁夷心胸。\n愿言驾一苇，直探瀛与蓬。\n翻然越长思，感尔良冲冲。\n昔焉济商舶，百货殷成丰。\n今乃集夷丑，群妖煽其凶。\n水角天且遥，驱民以从戎。\n海若固有灵，海滨馘蜺虹。\n再见波不扬，皞皞成周风。","太一判元始，百川汇鸿濛。\n淼淼甲子门，吞吐骊龙宫。\n鼓入珠江潮，堑隔陀城东。\n纳污本无意，洗日谁言功。\n凭高寄遐瞩，爽豁夷心胸。\n愿言驾一苇，直探瀛与蓬。\n翻然越长思，感尔良冲冲。\n昔焉济商舶，百货殷成丰。\n今乃集夷丑，群妖煽其凶。\n水角天且遥，驱民以从戎。\n海若固有灵，海滨馘蜺虹。\n再见波不扬，皞皞成周风。"],["岁律更新序，疑当混沌初。\n冥云连岁隔，积雨两旬过。\n鸡犬凄寒晦，牛羊怯陟阿。\n策马欲出门，将行复蹉跎。\n天运有旋转，阴极当阳和。\n且喜逢人日，忽忽开云罗。\n祥光烛太宇，漏照翘林坡。\n万木欣向荣，好鸟鸣且歌。\n故老相传语，占年生意多。\n朝野庆熙皞，海戎息干戈。\n亿载仰大明，重离照山河。","岁律更新序，疑当混沌初。\n冥云连岁隔，积雨两旬过。\n鸡犬悽寒晦，牛羊怯陟阿。\n策马欲出门，将行复蹉跎。\n天运有旋转，阴极当阳和。\n且喜逢人日，忽忽开云罗。\n祥光烛太宇，漏照翘林坡。\n万木欣向荣，好鸟鸣且歌。\n故老相传语，占年生意多。\n朝野庆熙皞，海戎息干戈。\n亿载仰大明，重离照山河。"],["大音久不作，干羽云潜凋。\n慨无札观鲁，喜有齐闻韶。\n获麟遽穷泣，仪凤安可招。\n聊为语师挚，于焉托颜瓢。\n苟得行武城，莞尔良逍遥。\n岂图千载下，俎豆崇累朝。\n礼明乐具举，情备文亦昭。\n合止谐祝圉，升歌间笙箫。\n两阶列籥翟，万武扬飘绡。\n美善见韶箾，揖逊亲唐尧。\n昔曾俨对越，奏假凝焄蒿。\n今来谒庭庑，钧天闻青霄。\n岂徒象删述，德迈功前超。\n生民绍物轨，百王式宗标。\n邈予寄遐想，旷世神交遥。\n愿言继忘味，岂曰知音寥。",""],["寒食不寒食，广与邺俗殊。\n感此寒食辰，怆然罢琴书。\n晋文亦英君，患难与之俱。\n而乃忘安乐，弃置绵山居。\n臣心有如石，屹立不可渝。\n臣心有如火，烈烈谁能濡。\n吾闻古来相，梦肖筑岩壖。\n亦有勤故交，物色勤劬劬。\n胡为烈山泽，虐焰无遗株。\n抱木以自完，长使行人吁。",""],["江水何茫茫，北风送南寒。\n搅我幽人怀，极目驰江干。",""],["曲江植芙蓉，大道良不远。\n乘风说飞翰，爰葺甘泉馆。",""],["此去即梅关，一窍谁凿之。\n千秋仰嵯峨，金鉴真人师。",""],["望望青原山，昔侣白鹤仙。\n杳矣东廓翁，念之成潸然。",""],["桐江即严江，挺挺念庵宅。\n安得从明斋，于焉永嘉客。",""],["新泉浚留都，济济濯缨侣。\n语默本同心，岂以岐出处。",""],["玉女开澄潭，盘盘玉阳洞。\n养静时闭关，煮石谁人共。",""],["欲驾扬州鹤，憩息甘泉窝。\n仰瞻仰宸楼，下盼庭树柯。",""],["我怀孔多方，道远莫致之。\n酩然事高酌，以慰遐相思。",""],["东北有佳人，独抱长吟膝。\n去予尺五天，宛隔中央突。\n洛社罗襟裾，折简故相屈。\n振缨时一来，共嗅芝兰室。\n忽然风雨惊，乍走龙蛇笔。\n莫是左太冲，深衣变君实。",""],["石门控沙表，空中见中阁。\n洒洒遗世氛，勇脱簪缨缚。\n蜿蜒迤三台，乌石层城角。\n一表李密情，肯以三公博。\n东西各天隅，乌兔自腾跃。\n梦寐隔蒹葭，中央讵能泊。\n幸有缩地缘，共赴香山约。\n九老联衣冠，七贤岂遗落。\n江湖轸忧君，窈窕聊寻壑。\n出岫云何心，归飞鸟自乐。\n沉吟续骚雅，图书阐河洛。\n与之同逍遥，翱翔遍寥廓。",""],["缀补芰荷衣，笑入荷花渚。\n翠盖擎珠图，花娇似能语。\n酌酒时劝花，爽袂空中举。\n花神为我宾，我作花神主。\n岂以颜色谐，通直真吾与。\n濯濯清涟漪，亭亭出沮洳。\n芳馨掇其花，嘉实良可茹。\n世有濂溪徒，共结同心侣。",""],["筦山有奇石，其趾沃以平。\n云嘘石作润，雨足郊原青。\n释耕馌垄上，刺史谁知名。\n愿言扩同人，与之盟坚贞。",""],["大道久蓁芜，侧径多岐别。\n子欲适通都，问途意弥切。\n开门在见山，射虎石可裂。\n得一流大和，四时自成节。\n子归遇龙江，再订常明说。\n濯濯星江源，家庭有真诀。\n会意即传神，在处通脉血。\n愿借鸳鸯针，为绣同心结。",""],["虬干高插天，溪水常在地。\n仙客归罗浮，飞舄几人至。\n酌水餐茯苓，共服先天气。\n妙诀有真传，谁解忘言意。",""],["五岭三江会，星躔应斗牛。\n越佗分汉治，宫阙奠羊州。\n白云隆北镇，南汇海珠浮。\n文物驯开拓，衣冠入鲁邹。\n何年轻作改，城角斜分流。\n顿令风气泄，百疹生疵忧。\n穷极有变通，群公集嘉猷。\n东西引泉涧，合注城南陬。\n若臂抱心腹，若襟敛重裘。\n精淑自此完，祯福交来遒。\n人和挽地利，天时亦为谋。\n景山员维河，商业云孔修。\n姬周卜洛食，伊瀍亦绸缪。\n再拜贺吾广，永言遘鸿休。",""],["哲王重胥宇，山原慎陟降。\n远观阴阳宜，俯察泉流漾。\n地维缺可补，天工亦人相。\n吾广称名藩，带海森云障。\n世远桑田迁，抚时偶增怆。\n浚水交城流，回沙亦盘向。\n适兹甲子新，人物肇新创。\n况尔开贤科，继继魁名状。\n淑气回海滨，幽谷春融盎。",""],["朱英罕皆实，硕果无丽容。\n物理固难兼，孰咎钧陶工。\n独爱濂溪莲，乃有君子风。\n花实既双美，外直而中通。\n灿灿丛牡丹，及兹芍药侣。\n色盛随飘风，靡实奚足取。\n适适君子庭，植盘见山茶。\n树高仅逾尺，方春已呈葩。\n向来本无实，今秋实如瓜。\n握之颇盈指，菁菁泽琼华。\n借问何以然，习远即成性。\n栽厚天固培，况乃因人胜。\n慥慥君子心，华实此相证。","朱英罕皆实，硕果无丽容。\n物理固难兼，孰咎钧陶工。\n独爱濂溪莲，乃有君子风。\n花实既双美，外直而中通。\n灿灿丛牡丹，及兹芍药侣。\n色盛随飘风，靡实奚足取。\n适适君子庭，植盘见山茶。\n树高仅踰尺，方春已呈葩。\n向来本无实，今秋实如瓜。\n握之颇盈指，菁菁泽琼华。\n借问何以然，习远即成性。\n栽厚天固培，况乃因人胜。\n慥慥君子心，华实此相證。"],["蚤拔南宫隽，归卧樵山云。\n逢时征召起，嗣服皆明君。\n世美良克济，膴仕安足云。","蚤拔南宫隽，归卧樵山云。\n逢时徵召起，嗣服皆明君。\n世美良克济，膴仕安足云。"],["表表怀先公，舍子荫其侄。\n官子亦可轻，何物足吾屈。\n扩此仁一家，缨冠救同室。",""],["先公利社稷，出境陈所知。\n况兹有专城，邻封即慈溪。\n目中惯夷险，熟路随所之。",""],["峡庙熄邪妖，江心石徙避。\n峡山刻移文，雷风猛虎毙。\n动物慎真诚，群邪岂能閟。",""],["士无德举主，先公忘己恩。\n子今酬知己，惟报君与民。\n向彼潝潝徒，太虚过浮云。",""],["朝阳有奇凤，间世时一鸣。\n雷在地中复，当秋敛其声。\n所以不言信，混混原默成。",""],["我爱龟峰秀，同公陟嶙峋。\n芳枝虬欲动，细草翠成裀。\n化雨时敷足，和风正好人。\n话入芝兰室，香交桃李芬。\n何当遽然别，握手弥殷勤。\n河间文献地，喜得相明禋。\n乐和礼备举，于以谐人神。\n行见通河洛，大地回氲氤。",""],["南国挺奇树，密叶披华盖。\n辉映紫薇楼，青葱护晨霭。\n星霜阅岁久，雨露从天霈。\n继咏甘棠篇，谁能拜剪害。\n愿言培其根，长春物同泰。\n何以钟爱深，邹侯此停旆。\n清标琴鹤随，夜告焚香酹。\n扩此生生仁，覃恩及无外。",""],["皎日丽长空，潜幽亦可觏。\n云胡蔽亏者，繁枝暗未透。\n造化本至公，赋予因材授。\n攘剔固有宜，匪意行诛宥。\n窗牖兹玲珑，重门敞前后。\n谁实为此功，对有曰时茂。\n堂虚早生白，清风散炎昼。\n切磋成有斐，七贤非晋旧。\n有箦金斯纯，扶疏月可漏。\n欲挹伶伦子，截作长筒奏。","皎日丽长空，潜幽亦可觏。\n云胡蔽亏者，繁枝闇未透。\n造化本至公，赋予因材授。\n攘剔固有宜，匪意行诛宥。\n窗牖兹玲珑，重门敞前后。\n谁实为此功，对有曰时茂。\n堂虚早生白，清风散炎昼。\n切磋成有斐，七贤非晋旧。\n有箦金斯纯，扶疏月可漏。\n欲挹伶伦子，截作长筒奏。"],["粤徼闻啼鸟，恍惚乡国音。\n停云在树杪，尺五连苍阴。\n出门寄遥瞩，乃隔庾江岑。\n乘风欲插羽，安得从飞禽。\n抚弦重叹息，聊作兼葭吟。\n我有南薰调，可以开烦襟。\n昔贤异出处，意气仍盍簪。\n范老忧时念，且罄平生心。",""],["忆昔长白居，画粥断齑菜。\n此时意可忘，移根种园内。\n肉食岂不甘，藿食味终在。\n举箸逾万钱，寰中几人再。\n欲寡心自恬，风波亦可耐。\n正己端垂裳，茹草曾躬耒。\n貌瘦天下肥，恶食良自爱。\n持此一介严，行行陟台鼐。","忆昔长白居，画粥断齑菜。\n此时意可忘，移根种园内。\n肉食岂不甘，藿食味终在。\n举箸踰万钱，寰中几人再。\n欲寡心自恬，风波亦可耐。\n正己端垂裳，茹草曾躬耒。\n貌瘦天下肥，恶食良自爱。\n持此一介严，行行陟台鼐。"],["有美温婺源，簿政适伊始。\n三月期可观，期年政声起。\n民方借长惠，云胡遽归止。\n斯道废与兴，天乎岂人使。\n好赋渊明词，遗经教诸子。\n岂无燕山桂，跨灶光前趾。",""],["两江西北来，合流注南海。\n一六本同根，朝宗永不改。\n挽舟溯天河，支机石可采。",""],["上滩思买篙，防雨思买伞。\n况乃当危湍，阴云布微霰。\n谁为杞人忧，长歌待明旦。",""],["日午暂停舟，回岐抱水口。\n赖汝遏狂澜，谁从蛟龙走。\n近水新筑城，一角摧湍溜。\n负薪有反裘，惜尔皮毛朽。",""],["跏趺瞿昙石，对酌定心泉。\n中心本自定，岂藉泉涓涓。\n常感固常寂，顺应通自然。\n岂能作槁木，岂能息无烟。\n可以纳大麓，可以门市廛。\n雅歌莅兵甲，端坐波涛颠。\n静定动亦定，请诵程子篇。",""],["君莫弃浊流，湜湜见泾沚。\n莫谓流本清，扬渭混渣滓。\n是处有清溪，溪清流亦驶。\n白石露齿齿，潜鳞照渊底。\n歌沧浪者谁，千古伯夷子。",""],["泰山忽东摧，沧海还桑田。\n人事有废兴，千古理亦然。\n昔我湛夫子，韶阳舣归船。\n振衣帽峰麓，济济罗诸贤。\n爰兹辟院宇，永以开讲筵。\n阐扬六字符，习心俾销煎。\n迄今三十载，圣贤有真传。\n曲江重徙学，此院乃借迁。\n让贤尚云可，让圣岂为愆。\n千仞宫墙在，门深室且玄。\n升堂集朋侣，仰钻谈高坚。\n人心解求放，文礼见目前。\n匪前亦匪后，岂在天与渊。\n勿忘勿助间，默识同勉旃。",""],["予晤默成子，最爱默成义。\n何以默而成，忠信为实地。\n植培真种根，沃以灵泉泚。\n删剔去繁枝，含英葆元气。\n夜息微初萌，勿俾牛羊恣。\n自养自得之，谁能说衷秘。\n太虚本何言，声臭两无自。\n惟翕始有辟，专一为直遂。\n是以广大生，无穷亦无际。\n古有孔圣师，无言法天地。\n心斋以坐忘，如愚有颜氏。\n千载同心盟，吾兹见吾是。",""],["宵征达管铺，晓发如安流。\n向无峡中鸟，兹焉浮江鸥。\n一峰兀水浒，宛宛见盘尘。\n亦有万仞壁，列卦铺玄畴。\n葭灰动六管，山坳指群丘。\n一阳庆道长，君子朋来求。",""],["平石舟更小，君莫嫌局促。\n但得心宇宽，山川尽可目。\n分流入宜章，溪小丛且曲。\n舟人行亦劳，聊借石岩宿。",""],["章溪有泷小，不如昌泷雄。\n亦有泷神庙，问之云吴公。\n此庙据奇石，真山假山同。\n进进官陂头，山平村野通。\n焚芟辟草埔，预为事春农。\n临溪浣衣妇，汲爨事姑翁。\n章邑谅不远，知政占民风。",""],["舠沿郴水北，五虹跨长江。\n岂无泷滩迅，险石如宜章。\n行行出江口，迤东岐桂阳。\n吾直纵一苇，顺流赴衡湘。\n水滨勿惊鸥，与尔机相忘。",""],["石壁联江浒，岂石坚且贞。\n何物幻化工，斩削浑天成。\n方若磨崖碑，长若张围屏。\n微风荡柔波，漾影文章呈。\n读之本无字，玩意空群经。\n谁图辋川者，万古留丹青。",""],["载煤湘船黑，洗锡江水浑。\n江船体本洁，而乃污泥尘。\n吾欲挽天河，涤濯回素真。",""],["衡故多秀峰，源泉止涓涓。\n乃兹朱明洞，水石兼奇观。\n群玉错湍流，珠帘挂崖端。\n日晴飞瀑布，风寒谷深盘。\n枕流堪洗耳，漱石砺齿间。\n安得驾铁桥，与朱明往还。",""],["八峰绕莲瓣，一刹当莲心。\n左右夹清流，玉池交前襟。\n霞光散紫馥，云盖擎青阴。\n亭亭观鹤立，隐隐听龙吟。\n谁据莲花座，说法开来今。",""],["武夷船驾壑，此船曷飞来。\n神功巧斲削，制度从天裁。\n船底砺剑脊，仓面长平开。\n夜深载明月，不怕风波推。",""],["忆予湛夫子，看山酬夙缘。\n行年八九十，两陟衡岳巅。\n紫云开讲院，丹壑引流泉。\n背倚南台峰，天柱联撑天。\n左襟岳宇秀，右邻文定贤。\n洞深奥复奥，翠屏抱当前。\n高建白沙祠，低处开井田。\n更有祝圣台，祝圣千万年。\n重门辟大道，纳级升堂轩。\n乡约集诸老，青衿开心传。\n文风忽丕变，礼乐相交先。\n遗泽在一方，庙貌肃俨然。\n嗟予系天关，三约逾十年。\n今朝始一到，点检多遗愆。\n两斋已颓圮，门墙颇更迁。\n岌岌白沙宇，欹斜亦将颠。\n乃亟鸠众工，爰方斲且虔。\n植邪以有立，易腐以为坚。\n斋廊且有待，两垣筑环联。\n心勤力不违，弱驾谁能鞭。\n岂无同心者，勖哉成予言。","忆予湛夫子，看山酬夙缘。\n行年八九十，两陟衡岳巅。\n紫云开讲院，丹壑引流泉。\n背倚南台峰，天柱联撑天。\n左襟岳宇秀，右邻文定贤。\n洞深奥复奥，翠屏抱当前。\n高建白沙祠，低处开井田。\n更有祝圣台，祝圣千万年。\n重门辟大道，纳级升堂轩。\n乡约集诸老，青衿开心传。\n文风忽丕变，礼乐相交先。\n遗泽在一方，庙貌肃俨然。\n嗟予系天关，三约踰十年。\n今朝始一到，点检多遗愆。\n两斋已颓圮，门墙颇更迁。\n岌岌白沙宇，欹斜亦将颠。\n乃亟鸠众工，爰方斲且虔。\n植邪以有立，易腐以为坚。\n斋廊且有待，两垣筑环联。\n心勤力不违，弱驾谁能鞭。\n岂无同心者，勖哉成予言。"],["衡岳最高峰，泉自山顶出。\n何以山顶泉，阴阳有呼吸。\n山泽自通气，涓流喷觱沸。\n观泉观我生，沛此育万物。",""],["我爱桐冈翁，桐冈集岐凤。\n凌风奋灵羽，千仞翱翔共。\n庭今产凤雏，天池日光烘。\n仰兹绳德辉，甘泉亦增重。",""],["生生自天性，山木昔尝美。\n胡乃交斧斤，继之群牧驶。\n幸兹日夜息，萌蘖见端倪。\n栽培滋息之，参天立可拟。\n吾心有良知，吾性即天理。\n生生固不息，养之惟在己。\n息息常存存，圣贤域可抵。\n唐君自树名，汝滋乃其字。\n自养还自滋，进进今未已。\n虽未登栋梁，亦可远棘枳。\n夏日苦炎蒸，凉阴足憩止。\n隆冬畏冱寒，岂随众芳萎。\n愿言永培根，浚源沃清泚。\n硕果种且蕃，千百传孙子。\n于以长秀林，仰之亦兴起。",""],["半山山已高，山顶高几许。\n太卑人易凌，太高独踽踽。\n吾宅山中央，高下都吾与。",""],["秀林特高致，伴子衡岳游。\n穷探绝灵窟，奥旨偕冥搜。\n祝融观日出，圆明漱清流。\n再拜甘泉院，托之重董修。\n言穷意未已，心期默相求。",""],["幽谷有奇芳，移来植前庭。\n天风播天香，惟德与之馨。\n绻绻不忍采，握之泪盈盈。\n培根固自昔，岂以旦夕成。\n手泽今犹在，于以吐含英。\n纫佩随鹓行，馨香达明廷。\n岂不堪瀼露，浥露如沾缨。\n岂无贤人亲，眷此伤我情。\n愿言再培植，沃以流泉清。\n龙孙日蕃茁，千载承芳名。",""],["山中已浃旬，郭外仍三宿。\n剥漕断行舟，凄雨霏屑玉。\n知己时邀留，杯盘叙寒燠。\n贤哉二地主，借棹乘朝旭。",""],["已发清平市，帽峰望渐远。\n武溪今古流，长滩几回转。\n俯仰怀昔贤，丰采见遗卷。\n吾欲溯兼葭，水口中坻宛。",""],["晓霜散晴旭，北风收微寒。\n谷车见牛转，绵贝归舟盘。\n赖此济荒岁，可以无饥寒。\n共听沧浪曲，知尔百口安。",""],["合江通彬江，仅仅五里许。\n昨始见暄晴，风寒遽抵牾。\n风逆水顺行，天意岂偏与。\n上下往来舟，莫更相嗔语。","合江通彬江，仅仅五里许。\n昨始见暄晴，风寒遽牴牾。\n风逆水顺行，天意岂偏与。\n上下往来舟，莫更相嗔语。"],["川行发清晓，顷焉日东升。\n烟清护玉盘，水光淼盈盈。\n云胡转雾霾，咫尺舟迷冥。\n两岸不见人，市语空闻声。\n谩说流霞紫，流霞亦有青。\n白衣变苍狗，此理良足征。","川行发清晓，顷焉日东升。\n烟清护玉盘，水光淼盈盈。\n云胡转雾霾，咫尺舟迷冥。\n两岸不见人，市语空闻声。\n谩说流霞紫，流霞亦有青。\n白衣变苍狗，此理良足徵。"],["舟达三汊河，雷家铺滩急。\n一水来茶陵，永新从此入。\n左江摩空青，衡岳参前立。\n衡邑尚几许，计程里三十。",""],["荡荡焦陵滩，舟人不敢过。\n问渠怯何为，下有石坎坷。\n乃觅长年师，为之一把柁。\n履险如履平，人从天上坐。\n治国如操舟，戒险常安妥。",""],["支流见陆口，云是醴陵河。\n去去入湘东，袁宜从此过。\n江湖仅分脊，车辅其如何。",""],["此舟即兰舟，棹拂天香游。\n贤人与之俱，如在天上头。\n相逢有三老，能辨薰与莸。\n世固多贤者，意气来相求。",""],["湘潭若富庶，两水交襟聚。\n西水宝庆流，东水长沙注。\n盘樯蔌如猬，岂直夸樟树。\n独叹衡山邑，孤舟无觅处。","湘潭若富庶，两水交襟聚。\n西水宝庆流，东水长沙注。\n盘樯蔌如猬，岂直誇樟树。\n独叹衡山邑，孤舟无觅处。"],["日光涵远山，霞彩蘸波底。\n柔风帆慢扬，澄江练如洗。\n暖气来𬘡缊，寒衣欲渐委。\n莫是春初迎，阳和转新轨。","日光涵远山，霞彩蘸波底。\n柔风帆慢扬，澄江练如洗。\n暖气来絪缊，寒衣欲渐委。\n莫是春初迎，阳和转新轨。"],["巨舻扼长风，遄予觅小艇。\n美人在蕲阳，愿言一往省。\n逆风乱中流，浪翻不能竟。\n几年驰梦思，咫尺丰颜迥。\n耿耿饥渴怀，坐看江云暝。",""],["予兹爱中陵，四山环四宅。\n晓观东日红，晚见西月白。\n北斗近紫薇，南箕扇尘陌。\n吾中集太和，四时春拍拍。\n不以炎燠蒸，岂为霜威剥。\n出门游泰华，驱车遍恒霍。\n回旋河洛间，兀然憩中岳。\n山垤无崇卑，宇宙谁宽窄。\n芝芷丛芝兰，危巅挺松柏。\n坐荫挹幽香，于以寻颜乐。\n瓢饮自足甘，蔬食亦不恶。\n况已饶膏粱，何忧亦何愕。\n勉之贵及时，坚固我可作。\n夷惠流高风，清和各有托。\n伊尹诚天民，耕莘乃先觉。\n圣偏吾岂居，孔时固愿学。",""],["大君即吾父，百姓为吾儿。\n天下本一家，爱敬无二歧。\n尽心尽吾职，岂敢他求知。\n吾祖耕鹿门，颇识民之依。\n愿推衣与食，忍见啼寒饥。\n虽有尧舜心，敢谓无其咨。\n偏反常棣华，愧乏甘棠枝。\n昔予忝京兆，民乃留生祠。\n惺弟按全浙，生祠重见之。\n兹予过常邑，行道传口碑。\n见予问同姓，述旧喜以悲。\n不有按治良，何以安流移。\n为建长生位，以系吾民思。\n徐氏实倡义，民心同秉彝。\n民风足征厚，岂以笑貌私。\n寄谢诸父老，种德弘镃基。","大君即吾父，百姓为吾儿。\n天下本一家，爱敬无二歧。\n尽心尽吾职，岂敢他求知。\n吾祖耕鹿门，颇识民之依。\n愿推衣与食，忍见啼寒饥。\n虽有尧舜心，敢谓无其咨。\n偏反常棣华，愧乏甘棠枝。\n昔予忝京兆，民乃留生祠。\n惺弟按全浙，生祠重见之。\n兹予过常邑，行道传口碑。\n见予问同姓，述旧喜以悲。\n不有按治良，何以安流移。\n为建长生位，以系吾民思。\n徐氏实倡义，民心同秉彝。\n民风足徵厚，岂以笑貌私。\n寄谢诸父老，种德弘镃基。"],["大化旋元根，无声亦无臭。\n时行自物生，处处春光漏。\n人心曷睹闻，岂以形迹觏。\n一实殊万分，弥漫遍宇宙。\n云无亦无无，云有宁有有。\n虚实动静间，寂感相参透。\n来也以此生，归也以此复。\n但保勿自亏，岂能强增凑。\n月窟通天根，时复倏时姤。\n盈虚本无常，此理原不朽。\n云胡一偏者，强向玄关叩。\n触处固跃如，冥心更何究。\n婴儿吾自存，坎离每相遘。\n若自煮空铛，于何问火候。\n老子固犹龙，学之恐差谬。\n孔圣真时中，天地等高厚。","大化旋元根，无声亦无臭。\n时行自物生，处处春光漏。\n人心曷睹闻，岂以形迹觏。\n一实殊万分，瀰漫遍宇宙。\n云无亦无无，云有宁有有。\n虚实动静间，寂感相参透。\n来也以此生，归也以此复。\n但保勿自亏，岂能强增凑。\n月窟通天根，时复倏时姤。\n盈虚本无常，此理原不朽。\n云胡一偏者，强向玄关叩。\n触处固跃如，冥心更何究。\n婴儿吾自存，坎离每相遘。\n若自煮空铛，于何问火候。\n老子固犹龙，学之恐差谬。\n孔圣真时中，天地等高厚。"],["予本樗栎资，早遂归林壑。\n爰结同心盟，天关亦足乐。\n独抱匡时忧，俯仰将谁托。\n抗宗有奇英，楼前韡花萼。\n始聘百里车，渐展骐骝脚。\n四省肃埋轮，清风动山岳。\n节钺齐扬间，直驰九边角。\n岂翳独贤劳，养器需盘错。\n今朝重出门，八闽再挥霍。\n且慰苍生谣，伫看登台阁。",""],["曾公来几年，相见时亦稀。\n今归云何许，问民民不知。\n持以问庠序，庠序交赞之。\n谓公待士礼，谓公爱民慈。\n明明秉素质，可以民不欺。",""],["吾邑有令长，兼庶政庶狱。\n职本粮储司，钱粮非吾属。\n才本听断能，民词匪吾鞠。\n官清有馀闲，艺圃课诸仆。\n薪俸或缺时，易蔬以自足。","吾邑有令长，兼庶政庶狱。\n职本粮储司，钱粮非吾属。\n才本听断能，民词匪吾鞠。\n官清有馀閒，艺圃课诸仆。\n薪俸或缺时，易蔬以自足。"],["重明洞普照，片云障其辉。\n雨露岂不广，尺蔀遏其滋。\n矧兹道兴废，实维命所司。\n尼使或有时，行止非人为。\n行矣安所遇，朗赋归来词。",""],["玉骨明皎皎，清风凉飕飕。\n空中矻砥柱，贞姿本无求。\n碧草如有情，金石遥相投。\n何以独爱萱，玩之能忘忧。\n吾心托太虚，造化原与游。\n浮云我何有，相忘空悠悠。",""],["下帷见董子，三载不窥园。\n登楼有湛生，誓不出庭轩。\n针成在磨柱，心坚石自穿。\n由此希往圣，岂徒盖前愆。\n人皆可为舜，勿谓今无贤。",""],["峄阳借根荄，楚宫植堂窔。\n欲制焦尾音，写此同心调。\n金井风乍来，深院月中照。\n感秋若为悲，放怀且舒啸。",""],["吾病笑也歌，放歌三百篇。\n我歌夫何为，故人有高迁。\n驱车出羊城，迢迢适闽壖。\n嘤鸣起幽谷，鹾政两当权。\n轻车就熟道，良造相后先。\n万里指顾间，行行复何言。\n齐人富煮海，周官布流泉。\n氓农已瘁力，摧商未为偏。\n矧兹南北祲，所守在疆边。\n士马愿夙饱，日费浑几千。\n子行慎足国，常股通车船。\n务期化斥卤，万灶繁朝烟。\n子行慎足民，生生浚其源。\n反裘以负薪，皮敝毛亦穿。\n培根在剔蠹，本固枝叶蕃。\n和衷乃有济，仲伯吹篪埙。\n万物皆可爱，吾道有正传。\n咨彼太极翁，何以独爱莲。\n岂徒羡虚直，出污泥不沾。\n吾言愧予耄，或可方韦弦。",""],["方塘净云影，碧水涵天光。\n鹙梁已潜伏，鸥机亦浑忘。\n于焉白鹭见，爰浴清涟央。\n志匪窥鱼在，心期附凤飏。\n肯以皎玉质，而污青泥湘。\n澡身事高洁，振羽任徜徉。\n波摇动素月，粉落凌秋霜。\n发梳孤帜白，爪弄双茎苍。\n晞日忻回照，乘风纳晚凉。\n沚荇回疏叶，汀兰袭异香。\n自得盘涡性，宁饥螾蛭肠。\n一水中分地，群飞太剧忙。\n拟向西雍渡，还从駜乘翔。\n冯夷欣击鼓，瀛女罢吹簧。\n但希离蚌祸，敢复恋鹓行。\n我有旧氅衣，复制新荷裳。\n浴沂集童冠，濯缨歌沧浪。\n岂知岁月老，同适水云乡。",""],["龙光转迟轨，虬影布清阴。\n凉飔落高树，侧翠分遥岑。\n爰言徙幽几，于以开烦襟。\n九皋有奇羽，几岁伴鸣琴。\n开笼悦客到，拍手谐主心。\n初飞薄穹汉，再戢下疏林。\n晴涛乍激发，寂籁何萧森。\n乐奏云和曲，幡移宝盖临。\n振奋霜翎展，蹁跹玉爪侵。\n丹砂回九转，轮毂匝千寻。\n临霞衣拟彩，映日背横金。\n星转双晴丽，簪垂独啄沉。\n八风羞祝态，九舞协韶音。\n阖辟随伸缩，低昂类纵擒。\n云翔原应节，子和识知音。\n忆昔成胎化，昂藏异众禽。\n燕鹰摩太液，凤翼浣清浔。\n紫盖翱翔旧，青田预养深。\n岂羡乘轩贵，还期入帐钦。\n舒迟方得所，真乐岂能禁。",""],["芳春万卉苍烟稠，鸣鸟伐木声相求。\n粤山徙倚何公囿，振衣一上澄心楼。\n洞门断隔市尘迹，澄心楼高几千尺。\n本无竹肉奏新声，止有图书环四壁。\n香烟忽起炉中蛇，话到羲皇日未斜。\n素琴欲和高深调，猗兰太息知音遐。\n凭栏且纵元龙目，白云控抱珠江曲。\n灵洲西引樵云巅，天华东峙罗浮麓。\n城头栋宇晕如飞，朝汉台荒霸业隳。\n风幡法性今何在，穗石真仙迹亦微。\n乾坤尚属浮沤沫，今古虚名能不没。\n纵然苍狗浮云遮，万里虚空原自阔。\n澄心常澄冥心期，万有何存众妄非。\n胸中至乐是谁知，胸中至乐是谁知。",""],["山颓木蒌几星纪，日抱遗经卧蓬累。\n敢将己物并蘧庐，黄鸟丘隅难共止。\n昔云见圣未克由，前参衡倚谁真修。\n光明洞见瑶台烛，须臾仿佛炉烟浮。\n精华日月空颅首，两耳之傍南北斗。\n衣冠俨雅纡绅垂，隐隐太公犹在手。\n高风已远不可攀，遗像依希千仞间。\n追随再拜诸公后，俯仰前瞻祇汗颜。",""],["洞阳本是纯阳侣，惯向洞庭弄烟渚。\n药洲穗圃时来过，块然薜荔丛间处。\n胸中在昔富明经，眼底英才沐时雨。\n赢得康民济世方，授与庭趋肇光绪。\n玉皇眷宠来自天，凤诏龙章旌汝贤。\n黄堂远寄南山颂，紫府今开北海筵。\n麟凰之脯蟠桃鲜，佩环趋跄并岛仙。\n雅歌投壶洽贞素，肯烦舞袖荐婵娟。\n惭予蹑履香山后，乍听钧天乐始奏。\n清商一曲薄太清，叠转薰风民物阜。\n仰视榴花燃，俯挹芝兰臭，美景芳晨婉相凑。\n主人乐意欣陶陶，嘉宾式燕何妨又。\n酒酣试问今何时，冲年天子神尧资。\n八埏九土皆恬熙，众星环绕紫垣微，炯炯南极当南离。\n丈人孙子常相依，谁云七十称古稀。\n远拉篯铿子，近与安期期。\n蒲涧菖蒲至今在，洞阳考卜共逶迤。\n千秋万秋究遗易，观无始而寤皇羲。",""],["去年六月终风恶，贼舟驶向河南泊。\n凶渠逆竖戈纷横，飞腥溅血严城角。\n今年六月风气好，闽帅直向潮阳岛。\n鸣钲伐鼓总天声，凶残魂魄戈前倒。\n一战玄钟再柘林，艨艟应击皆成沉。\n三战长驱向莲澳，如山楼橹失高深。\n虐焰消磨十八九，长奔潜望马耳走。\n广兵犄角随火攻，渠魁竟缚俞君手。\n俞君故是方叔俦，骐骥岂与骀驽侔。\n浙闽伊昔么么起，斩蛟窜鳄功名遒。\n东隅莫问昨朝事，桑榆人识鲁阳辔。\n向誓此贼不俱生，三捷居然副初志。\n老将料敌真吁谟，太平永巩帝皇图。\n先张之矢后脱弧，福兵福船云岂徒，福兵福船云岂徒。",""],["天章银汉夜的烁，亘汉祥光耀南极。\n个中原有老人星，丈人子孙相对明。\n几元几会几运世，历数绵延浑莫计。\n帝庭有命下南陬，安南郁翠山川绸。\n宪皇乙未升平日，税驾辕门系麟绂。\n箓中瑞庆悬桑弧，年年二月二十一。\n春和景媚暄长天，当歌对酒花正妍。\n嫦娥仙乐虚空下，朱颜粉黛总当前。\n王母桃，安期枣，龙羞杂荐蓬壶岛。\n鹿鸣鹤舞天风和，长伴仙真同不老。\n膝下有子为李官，不论小，不论尊。\n斑衣昼锦都成欢，况有善养兼贤孙。\n今年八十四，明年八十五，百岁千秋从此数。\n洋洋海屋时添筹，南山常苍日常午。\n从教彩凤衔丹图，希夷稳卧空山庐。\n但祝明皇万万祀，康平四海皆无虞。\n行握杖，倦枕书，静观日月澄太虚。\n掷却瓠瓢无聒耳，康衢里巷亦得闻都俞。",""],["广南妇节几垂芬，伦门节妇黎为真。\n百年伉俪仅数月，稿砧一丧何酸辛。\n抚摩遗腹摧肝腑，誓言甘作九泉人。\n届期天遣生男子，夫有男子夫不死。\n遗田二亩何足供，忍饿凌寒执麻枲。\n斗横夜永风凄凉，衡门破屋天为霜。\n剔灯顾影茕茕在，纫针细补儿衣裳。\n课儿昼遣从师读，归向窗前共𫗴粥。\n更期学作一等人，勉从尔舅罗浮麓。\n莫言远去膝下悲，吾心已惯阖门独。\n黄龙讲席春风深，阿母闻之亦慰心。\n蓝衣随换班衣旧，青云有路仍须寻。\n阿母年来逾六秩，纲常铸就丹衷铁。\n霜台御史偶知闻，特耀褒章厉高节。","广南妇节几垂芬，伦门节妇黎为真。\n百年伉俪仅数月，稿砧一丧何酸辛。\n抚摩遗腹摧肝腑，誓言甘作九泉人。\n届期天遣生男子，夫有男子夫不死。\n遗田二亩何足供，忍饿凌寒执麻枲。\n斗横夜永风凄凉，衡门破屋天为霜。\n剔灯顾影茕茕在，纫针细补儿衣裳。\n课儿昼遣从师读，归向窗前共饘粥。\n更期学作一等人，勉从尔舅罗浮麓。\n莫言远去膝下悲，吾心已惯阖门独。\n黄龙讲席春风深，阿母闻之亦慰心。\n蓝衣随换班衣旧，青云有路仍须寻。\n阿母年来踰六秩，纲常铸就丹衷铁。\n霜台御史偶知闻，特耀褒章厉高节。"],["壮哉何黄李氏子，厉志三馀了经史。\n闭门对榻膝欲穿，孰为龙头孰腹尾。\n英华吐出胸中藏，斗牛气贯虹霓光。\n天马行空拟联步，青钱万选谁争长。\n朅来快睹醒尘目，璀璨珠玑千百斛。\n同人意气乐已深，旧游况是通家族。\n通家自昔爱后生，庆有贤嗣光前躅。\n愿言继孔迹伊周，谫谫尔一芥之功，名岂以为诸君足。",""],["送春归，短葛换罗衣，城南城北花正飞。\n寻芳直探若耶浦，欸乃歌长杂鸣橹。\n渚莲叶绿花殷红，欲采不采心徒苦。\n心徒苦，去去频回驻。\n忆昔相期花信风，花开顿觉年迟暮。\n年光迟暮祇惊花，馨香那得似侬家。\n外直中通尘不染，蕣英肯与斗繁华。\n蕣英朝暮间，转盼纷成雪。\n侬独抱贞姿，流丹霞满颊。\n何兹却违兹，相逢知几时。\n玉臂花根藕，百折惜连丝。\n白月不常好，白露不常滋。\n明日有花重可采，何事流连归去迟。\n啼鵙催佳节，倦翼莫须歇。\n毕星好雨箕好风，牛女年年会且逢。\n夫君之裘今蒙茸，屈指归期在信宿，岂隔溪山千万重。",""],["白下江连古石城，三山云耸天外青。\n淮淝草木空闻鹤，杨孽舟舻已剪鲸。\n偏安霸业随流圮，骏德神功掀日起。\n即看禹鼎奠尧疆，载咏周文丰有芑。\n芃芃禾黍江之湄，郇伯阴霖泽已稀。\n公恕堂高传石匾，雨花台畔遗生祠。\n嗟予独愧凤雏祖，治中别驾翻成驽。\n苍梧彩凤别有真，九苞七德翔天府。\n忆昔初鸣水国时，冲繁路口摩疮痍。\n廉循赫赫追前史，惠爱洋洋溢口碑。\n君今别去吾何祝，润入皇都花正蔟。\n和风甘雨昼溟蒙，万紫千红春馥郁。\n兴高时探钟陵山，鸣鹿呦呦苍翠间。\n可以歌民阜，可以瞻帝颜。\n天威咫尺天衢近，蹑足层霄自不难。\n烦君试问秣陵道，亩菑能勿弥芳草。\n闲时再过新泉宫，弦诵有无继昏早。","白下江连古石城，三山云耸天外青。\n淮淝草木空闻鹤，杨孽舟舻已剪鲸。\n偏安霸业随流圮，骏德神功掀日起。\n即看禹鼎奠尧疆，载咏周文丰有芑。\n芃芃禾黍江之湄，郇伯阴霖泽已稀。\n公恕堂高传石匾，雨花台畔遗生祠。\n嗟予独愧凤雏祖，治中别驾翻成驽。\n苍梧彩凤别有真，九苞七德翔天府。\n忆昔初鸣水国时，冲繁路口摩疮痍。\n廉循赫赫追前史，惠爱洋洋溢口碑。\n君今别去吾何祝，润入皇都花正蔟。\n和风甘雨昼溟濛，万紫千红春馥郁。\n兴高时探钟陵山，鸣鹿呦呦苍翠间。\n可以歌民阜，可以瞻帝颜。\n天威咫尺天衢近，蹑足层霄自不难。\n烦君试问秣陵道，亩菑能勿弥芳草。\n閒时再过新泉宫，弦诵有无继昏早。"],["王藩守国惟典章，小臣奉法厘封疆。\n分符邈邑能几许，爱民即是尊天皇。\n皇恩浩荡涓埃竭，铮铮不改衷肠铁。\n民穷岂令污吏横，民柔岂忍淫威轶。\n抗言誓欲挽狂河，死生富贵奚足多。\n尧天怒霁轻垂罚，谪官犹寄番禺阿。\n史可典簿领，低徊愆尤免。\n孤臣矢志祇自知，讵计芳名常不殄。\n君不见梁傅贾，流涕至死悲堕马。\n又不见汲黯忧，戆忠直寝淮南谋。\n千古万古将谁仇，千古万古将谁仇。","王藩守国惟典章，小臣奉法釐封疆。\n分符邈邑能几许，爱民即是尊天皇。\n皇恩浩荡涓埃竭，铮铮不改衷肠铁。\n民穷岂令污吏横，民柔岂忍淫威轶。\n抗言誓欲挽狂河，死生富贵奚足多。\n尧天怒霁轻垂罚，谪官犹寄番禺阿。\n史可典簿领，低徊愆尤免。\n孤臣矢志祇自知，讵计芳名常不殄。\n君不见梁傅贾，流涕至死悲堕马。\n又不见汲黯忧，戆忠直寝淮南谋。\n千古万古将谁仇，千古万古将谁仇。"],["白云在山腰，青山出云顶。\n出入山之间，俄别人天境。\n山下人指云为天，山上更有山相连。\n白云无尽山无尽，瞬转云随山顶遁。\n延缘九叠即九霄，天门万里原非遥。\n劝君更着竿头力，翱游八极同逍遥。",""],["陈家有女珍琅璆，时年十六归哉周。\n齐眉举案逾九秋，拆鸾破镜嗟莫留。\n城隅哭倒天为愁，凄霜黯日风飕飕。\n铁心祇与夫君谋，百年冢穴誓相求。\n谁云孀年二十四，网常一醮终天地。\n身未即亡姑不俟，勉拊犹儿即吾嗣。\n训之远执甘泉贽，已分侄存家可替。\n何知多难罄簪揥，祇今贫食逾古稀，屋漏可对天可知。\n乡评月旦交相推，士林拂拭生光辉。\n君不见葛岸水中流，白石清泉洗。\n又不见桂林埃贞枝，独柏霜犹翠。\n千年女训妇之箴，付与观风载笔采入彤庭史。","陈家有女珍琅璆，时年十六归哉周。\n齐眉举案踰九秋，拆鸾破镜嗟莫留。\n城隅哭倒天为愁，凄霜黯日风飕飕。\n铁心祇与夫君谋，百年冢穴誓相求。\n谁云孀年二十四，网常一醮终天地。\n身未即亡姑不俟，勉拊犹儿即吾嗣。\n训之远执甘泉贽，已分侄存家可替。\n何知多难罄簪揥，祇今贫食踰古稀，屋漏可对天可知。\n乡评月旦交相推，士林拂拭生光辉。\n君不见葛岸水中流，白石清泉洗。\n又不见桂林埃贞枝，独柏霜犹翠。\n千年女训妇之箴，付与观风载笔采入彤庭史。"],["越台西麓城西阿，琪宫宝塔高嵯峨。\n中有菩提几千岁，琼枝贝叶霄云摩。\n风幡无意随舒卷，佛日相轮几回转。\n昔年衣钵今属谁，昙花落地和□软。\n欲缘绣黼问金针，且喜山门幽更深。\n岩窝正在苍岩畔，密竹丛中路可寻。\n荜门瓮牖天光辟，蜗文蠹迹生苔壁。\n连袪六七同素心，共息岩窝究羲易。\n主人茶果城中回，道说东君消息来。\n相忘静对蒲团坐，欲去不去长徘徊。\n年来欲结栖霞侣，况值山门今得主。\n苏公留带分已深，我亦留题作筌语。","越台西麓城西阿，琪宫宝塔高嵯峨。\n中有菩提几千岁，琼枝贝叶霄云摩。\n风幡无意随舒捲，佛日相轮几回转。\n昔年衣钵今属谁，昙花落地和□软。\n欲缘绣黼问金针，且喜山门幽更深。\n岩窝正在苍岩畔，密竹丛中路可寻。\n荜门瓮牖天光辟，蜗文蠹迹生苔壁。\n连袪六七同素心，共息岩窝究羲易。\n主人茶果城中回，道说东君消息来。\n相忘静对蒲团坐，欲去不去长徘徊。\n年来欲结栖霞侣，况值山门今得主。\n苏公留带分已深，我亦留题作筌语。"],["一元淑气回磅礴，阳光布暖先旸壑。\n群材长养年复年，大可栋梁小榱桷。\n明王治举开明堂，偏遣求材罗四方。\n寸长寸短亦兼取，千山万卉无留良。\n古来效用均为贵，低昂岂必分洪细。\n方虔斫削固自天，莫怨工师与匠艺。\n君不见孔氏师，乘田委吏何曾卑。\n又不见赵中令，始从记室匡时政。\n君行三载期有为，功成巨室原同归。",""],["峄阳之桐兮太古遗声，鼓南薰兮寄衷情。\n曲终忘言兮乐正深，知不知兮何庸心。",""],["我生六龄君八岁，东吴南越殊天际。\n凄风早晚落桐秋，幽萱两地交零瘁。\n哀哀镪负离几时，出门许许追群儿。\n归来唤母母不应，就床口食犹含悲。\n手书读学开蒙瞽，旧裳欲破针停补。\n隔邻偶听断机声，不必丸熊自荼苦。\n我今生已四十年，与君同仕佐应天。\n皇恩浩荡真如海，龙章共贲重九泉。\n翟冠历录珍珠粒，捧起欲焚转酸泣。\n目前钟鼎岂不甘，愿言追养将何及。\n松楸万里乌夜号，忍听南山风拂拂。\n我为君且作荣思篇，君报我可无蓼莪什。",""],["君不见咸阳宫广容屯骑，翻然炬烬丛蓁地。\n又不见齐云峻彩连落星，高岸为谷深为陵。\n古人丽美崇相夸，今人吊古重咨嗟。\n相公厅事仅旋马，千年敝屋生光华。\n凉凉踽踽真谁践，碧江江侧重相见。\n茫茫俯仰天地宽，新亭小小空中建。\n石阶朴桷数椽楹，素栏粉槛窗珑玲。\n斗方物外无馀长，可以容鹤旋修翎。\n冰壶月朗天气肃，洞箫袅袅天外声。\n主人拍手鹤亦舞，悠悠物我俱忘形。\n翩跹舞罢歌声歇，援琴更凑双清节。\n惯闻老鹤如知音，依依欲作同心结。\n玉炉夜久香云销，起视疏星半明灭。\n须臾澥渤腾羊角，埃氛万里清寥郭。\n主人跨鹤凌风巅，遨游四海将安泊。\n瀛洲别是小壶天，独与诸仙作朋膊。\n瀛洲好景何时归，环亭绿草空萋萋。\n日中亭午朱轮皎，翻壁夕照生斜晖。\n流光苦不惜，岁月与我违。\n适意欲及时，营营复何为。\n主人有亭一非小，胸襟活泼青天齐。\n泌水能忘饥，衡门亦可栖。\n愿君永矢丰亨戒，任是琼楼玉宇千门万户，永与此亭不相违。",""],["璇玑夜干窥穷冥，斗枢下泄摇光精。\n千年异质传苍种，七星炯炯毫间明。\n昔乘老子扶云下，龙舆凤旆争骖跨。\n风镳六马不可追，却向衡阳说仙驾。\n有时泛水游荆门，灵踪托秘栖薇垣。\n公来岳麓时相植，追随挟毂欣盘桓。\n年年四月旦十一，公始悬弧系麟绂。\n芳樽再倒琼筵开，庆见双麑兆嘉茀。\n三公粉画未足多，呦鸣濯养皆修和。\n铜牌岁岁记寿考，锡环叠叠纷云罗。\n满堂朱履青霄客，歌舞欢声杂弹拍。\n引杯再酌呼卢卢，却问几时变玄白。\n任他沧海成桑田，独与龟鹤长相旋。\n天无际，地无边。\n一十二万逾八千，运穷贞下还起元。\n君不见飞凫子，曳朝赤舄凌风起。\n又不见卖药翁，青囊掉臂东海东。\n帝师已佐兴刘业，韬光亦自游赤松。\n愿公功成早归洛，行且会耆英结九老，相与联四驾，游八极，遍蓬岛之诸峰。","璇玑夜干窥穷冥，斗枢下泄摇光精。\n千年异质传苍种，七星炯炯毫间明。\n昔乘老子扶云下，龙舆凤旆争骖跨。\n风镳六马不可追，却向衡阳说仙驾。\n有时泛水游荆门，灵踪托秘栖薇垣。\n公来岳麓时相植，追随挟毂欣盘桓。\n年年四月旦十一，公始悬弧系麟绂。\n芳樽再倒琼筵开，庆见双麑兆嘉茀。\n三公粉画未足多，呦鸣濯养皆修和。\n铜牌岁岁记寿考，锡环叠叠纷云罗。\n满堂朱履青霄客，歌舞欢声杂弹拍。\n引杯再酌呼卢卢，却问几时变玄白。\n任他沧海成桑田，独与龟鹤长相旋。\n天无际，地无边。\n一十二万踰八千，运穷贞下还起元。\n君不见飞凫子，曳朝赤舄凌风起。\n又不见卖药翁，青囊掉臂东海东。\n帝师已佐兴刘业，韬光亦自游赤松。\n愿公功成早归洛，行且会耆英结九老，相与联四驾，游八极，遍蓬岛之诸峰。"],["矗矗连天万马奔，垂缰直出羊城会。\n中峰叠叠起白云，白云飞去青山在。\n青山玉骨来几时，芙蓉削出天边奇。\n九龙泉引西来佛，鹤舒展翼腾安期。\n安期已去惠能老，秋风落地凄寒草。\n白衣苍狗时变更，闲云翠壁云谁扫。\n龙泉突出甘泉居，鹤舒今已为著书。\n白云三变亭台异，太虚万古终如如。\n本来面目谁能识，云去云来俱尘迹。\n丹梯蹑上五层楼，飘然四顾真无极。\n欲将插羽凌天风，翱游八表无何中，万有万劫都成空。","矗矗连天万马奔，垂缰直出羊城会。\n中峰叠叠起白云，白云飞去青山在。\n青山玉骨来几时，芙蓉削出天边奇。\n九龙泉引西来佛，鹤舒展翼腾安期。\n安期已去惠能老，秋风落地凄寒草。\n白衣苍狗时变更，閒云翠壁云谁扫。\n龙泉突出甘泉居，鹤舒今已为著书。\n白云三变亭台异，太虚万古终如如。\n本来面目谁能识，云去云来俱尘迹。\n丹梯蹑上五层楼，飘然四顾真无极。\n欲将插羽凌天风，翱游八表无何中，万有万劫都成空。"],["频年岭海风尘恶，阴霾白昼常漠漠。\n蜂屯石寨拥干戈，猬集风樯鸣鼓角。\n向时三五陵孤村，今来千数扫村落。\n向时伏火惊入来，今来掩取勒赎博。\n峻宇层楼已毁坚，荜门蔀屋空灾连。\n生人血肉尚堪走，枯骨原泉忍发迁。\n民苦跃地号叩天，苍天有耳应可怜。\n吾皇赫震雷霆怒，简书特下扬威武。\n壮猷指画有方公，洸旅经营属召虎。\n貔貅百万降自天，旌旗闪闪飞云烟。\n渊渊鼓动钲铙奏，止如山立行如川。\n先锋幸有元戎奋，铁马金戈突驰阵。\n捣巢破竹势莫当，爨釜游鱼倏成困。\n凯歌献馘归仍仍，崇朝夙曀开清明。\n急书露布报天子，长挽银河洗甲兵。",""],["丁家有母身姓岑，母慈妇节令人钦。\n嗟哉逢时生不辰，于归方庆谐瑟琴。\n二十三载成商参，两孤一襁一怀衿。\n霜天雪月照我心，事姑冀绍前徽音。\n云胡降割天重阴，姑亡叔夭双泪淋。\n苦持麻枲缝金针，教儿岂惜贫捐簪。\n伤哉复丧长子任，爱钟季子行独深。\n岂于行也偏爱深，吾夫一脉逾千金。\n万年血食将渠歆，岂期海岛腾妖祲。\n母子播遁栖丛林，行也遇贼翻成擒。\n母痛急出号喑喑，但希救子存夫身。\n宁知断臂魂凄沉，百年此恨谁能禁。\n有子吁诉恳且谌，恶贼闻之亦沾襟。\n俾得葬母从父嵚，九原双穴联琼琛。\n慈节芳名传古今，山与齐高乔木森。\n我来浙西湖之浔，乃子倒屦时趋临。\n论心问道意且勤，断机画荻之源遥可寻。\n子贤母教那能堙，问之细得原来因。\n予亦感慨酸且辛，呜呼子贤母教那能堙。\n愧无史笔扬幽芬，为之哀歌三叹聊长吟。","丁家有母身姓岑，母慈妇节令人钦。\n嗟哉逢时生不辰，于归方庆谐瑟琴。\n二十三载成商参，两孤一襁一怀衿。\n霜天雪月照我心，事姑冀绍前徽音。\n云胡降割天重阴，姑亡叔夭双泪淋。\n苦持麻枲缝金针，教儿岂惜贫捐簪。\n伤哉复丧长子任，爱钟季子行独深。\n岂于行也偏爱深，吾夫一脉踰千金。\n万年血食将渠歆，岂期海岛腾妖祲。\n母子播遁栖丛林，行也遇贼翻成擒。\n母痛急出号喑喑，但希救子存夫身。\n宁知断臂魂凄沉，百年此恨谁能禁。\n有子吁诉恳且谌，恶贼闻之亦沾襟。\n俾得葬母从父嵚，九原双穴联琼琛。\n慈节芳名传古今，山与齐高乔木森。\n我来浙西湖之浔，乃子倒屦时趋临。\n论心问道意且勤，断机画荻之源遥可寻。\n子贤母教那能堙，问之细得原来因。\n予亦感慨酸且辛，呜呼子贤母教那能堙。\n愧无史笔扬幽芬，为之哀歌三叹聊长吟。"],["明皇驭寓绥群邦，海宇万里来越裳。\n蠢尔倭奴不自茹，敢窥惠涘连潮阳。\n况乃横戈纵深骛，莞东内瞰罗浮麓。\n九江水陷铁场摧，杀人如麻满溪谷。\n官军始战向源头，帷幄谁者诚疏谋。\n狼兵一败四千死，可怜蔽海僵尸流。\n倭奴得志扬扬去，声联广海群倭驻。\n横侵突劫逾几旬，帝怒赫然孰能恕。\n握戎幸有王将军，剪擒曾寇先声闻。\n倭奴竟落将军手，馘俘百级馀宵奔。\n一时渤海风波息，共说王戎功最硕。\n源头之耻聊刷之，旧地创残今衽席。\n将军树下休言功，滨滨京观未全封。\n备倭再整先朝略，浪静须防忽起风。","明皇驭寓绥群邦，海宇万里来越裳。\n蠢尔倭奴不自茹，敢窥惠涘连潮阳。\n况乃横戈纵深骛，莞东内瞰罗浮麓。\n九江水陷铁场摧，杀人如麻满溪谷。\n官军始战向源头，帷幄谁者诚疏谋。\n狼兵一败四千死，可怜蔽海僵尸流。\n倭奴得志扬扬去，声联广海群倭驻。\n横侵突劫踰几旬，帝怒赫然孰能恕。\n握戎幸有王将军，剪擒曾寇先声闻。\n倭奴竟落将军手，馘俘百级馀宵奔。\n一时渤海风波息，共说王戎功最硕。\n源头之耻聊刷之，旧地创残今衽席。\n将军树下休言功，滨滨京观未全封。\n备倭再整先朝略，浪静须防忽起风。"],["羲皇画易开天地，讼师协济随成比。\n蛮夷贼宄内外殊，虞廷总属皋陶士。\n才堪平理能治兵，禁非正义原同行。\n莱兵远却惟司寇，泮宫献馘归明刑。\n圣贤矩度遗芳轨，古人亦可今人拟。\n渊泉浚养时之出，左宜右有皆相似。\n来公本是浙中英，少年甲第腾蜚声。\n龙光初奋镆铘匣，十二屠牛立解铏。\n潮邦正值风涛恶，横奔毒噬棼鲸鳄。\n惟公戢暴在安民，声色刑威本无作。\n冰清玉润阳春旋，期年民自以不冤。\n驰驱愿效同仇志，荷戈执挺争相先。\n曾贼渠魁已擒掊，党孽倭奴亦授首。\n赞猷辑士公居多，让德让功公不有。\n口碑载道讴歌频，誉声上彻通苍旻。\n康侯晋锡从天下，补衮行应入紫宸。\n乘风巨翮今未已，九万图南从此始。\n姬朝方吉承周公，壮猷共赞宣王理。\n有文谟，有武备，出将入相皆吾事。\n伫见勒绩燕然收功铜柱，纪万年之青史。",""],["君不见康乐翁，淮淝有侄成肤功。\n又不见记室史，宋家平定由兹始。\n天生杰士济时难，岂与樗栎甘投闲。\n老骥伏枥志千里，况在青春鬓未斑。\n桑弧蓬矢悬门冀，请缨投笔吾人事。\n文谟武略张弛间，俎豆戎行非有二。\n忆公初试闽幕时，读书读律弘兼资。\n致君尧舜已有术，俗格拘孪未尽施。\n沧溟正刷鹏抟羽，碧汉秋风待时举。\n三尺干将重淬磨，搴旗伐鼓陈师旅。\n可以阖，可以开，九天震动鸣风雷。\n可以进，可以退，蛟龙伸屈谁能会。\n胸中数万藏甲兵，萧曹伊吕相峥嵘。\n指挥勿浪徒夸评，神机默运真难名。\n向年已奏牂牁续，今兹渌水波澄碧。\n干戈载戢牛马归，率土普天皆版籍。\n皇明一统浑为家，谁哉铜柱分茅石。","君不见康乐翁，淮淝有侄成肤功。\n又不见记室史，宋家平定由兹始。\n天生杰士济时难，岂与樗栎甘投閒。\n老骥伏枥志千里，况在青春鬓未斑。\n桑弧蓬矢悬门冀，请缨投笔吾人事。\n文谟武略张弛间，俎豆戎行非有二。\n忆公初试闽幕时，读书读律弘兼资。\n致君尧舜已有术，俗格拘孪未尽施。\n沧溟正刷鹏抟羽，碧汉秋风待时举。\n三尺干将重淬磨，搴旗伐鼓陈师旅。\n可以阖，可以开，九天震动鸣风雷。\n可以进，可以退，蛟龙伸屈谁能会。\n胸中数万藏甲兵，萧曹伊吕相峥嵘。\n指挥勿浪徒誇评，神机默运真难名。\n向年已奏牂牁续，今兹渌水波澄碧。\n干戈载戢牛马归，率土普天皆版籍。\n皇明一统浑为家，谁哉铜柱分茅石。"],["惯蜡登山屐，春山伴客游。\n宛见江门钓，疑登碧玉楼。\n浩气乾坤薄，闲情雪月谋。\n两生存礼乐，三代可伊周。\n为恋圭峰日，频旋燕邸舟。\n尼封谁复待，昼出岂能留。\n紫陛挥金马，沧江狎玉鸥。\n功名超帝霸，轩冕傲公侯。\n花柳东风晓，藤蓑北国秋。\n渔歌听自足，鸿造句偏酬。\n问道来燕楚，抠衣遍越欧。\n嗟予生独晚，仰止亦何求。\n沙贝惭遗钵，天关溯末流。\n岁供苹藻礿，时接鼎烟浮。\n去住踪难定，羹墙梦岂休。\n空中虚立木，安得足巅头。","惯蜡登山屐，春山伴客游。\n宛见江门钓，疑登碧玉楼。\n浩气乾坤薄，閒情雪月谋。\n两生存礼乐，三代可伊周。\n为恋圭峰日，频旋燕邸舟。\n尼封谁复待，昼出岂能留。\n紫陛挥金马，沧江狎玉鸥。\n功名超帝霸，轩冕傲公侯。\n花柳东风晓，藤蓑北国秋。\n渔歌听自足，鸿造句偏酬。\n问道来燕楚，抠衣遍越欧。\n嗟予生独晚，仰止亦何求。\n沙贝惭遗钵，天关溯末流。\n岁供蘋藻礿，时接鼎烟浮。\n去住踪难定，羹墙梦岂休。\n空中虚立木，安得足巅头。"],["双舄下枫宸，炎蒸渡海垠。\n蔽芾频怀召，东南喜借恂。\n衣冠仍夙范，雨露渥新仁。\n乐国清狐鼠，中原见凤麟。\n□□□□□，□□□□□。\n令甲遗镌在，仓箱稔粟陈。\n天涯重戴日，海国又逢春。\n何幸康衢里，歌同击壤民。",""],["地与人俱杰，千年淑气回。\n生成知帝造，楼阁倚天开。\n帘卷云霞宅，花明锦绣堆。\n鸟喧时到枕，蜃气自成台。\n翠入阶前草，阳生岭上梅。\n苍云天外变，紫气日边来。\n水势环双玉，山光秀列台。\n疏钟晴报寺，好月夜浮杯。\n华国书香远，名家宦业恢。\n迎仙徒缥缈，望省已崔嵬。\n桃李当门盛，同声咏有莱。","地与人俱杰，千年淑气回。\n生成知帝造，楼阁倚天开。\n帘捲云霞宅，花明锦绣堆。\n鸟喧时到枕，蜃气自成台。\n翠入阶前草，阳生岭上梅。\n苍云天外变，紫气日边来。\n水势环双玉，山光秀列台。\n疏钟晴报寺，好月夜浮杯。\n华国书香远，名家宦业恢。\n迎仙徒缥缈，望省已崔嵬。\n桃李当门盛，同声咏有莱。"],["地启南山胜，春开北海樽。\n论乡知谊厚，缩席见温存。\n兀石云黏护，磨崖字剥痕。\n山腰笼古树，𪩘侧敞晴轩。\n烟火孤城隐，蚕桑旧俗敦。\n迎阳花欲舞，悦客鸟能言。\n纳履跻云顶，攒衣坐石根。\n薜窗牵蔓蒂，药圃长芽荪。\n河洛开畴画，麟凰见野原。\n逢时欣舜日，浪迹寄山门。\n问奕吾生拙，焚香且细论。\n凭虚观太始，见水觅真源。\n机息鸥邻席，烹茶鹤避烟。\n橐枢归造化，裘葛付寒暄。\n自得山林寂，宁知朝市喧。\n抟鹏穷日表，瞿蝶托宵魂。\n天阔眸逾迥，山幽俗避繁。\n荷衣随泻适，绣绂敢攀援。\n虚引山涵泽，弘含地势坤。\n花封琴静鼓，萝径约同扪。\n玉浸晶光合，屏联翠色屯。\n锦鬐舒泳跃，仙羽出笼樊。\n凤去凌霄翥，龙来蜿地蟠。\n春融千里邑，风动万家村。\n鸡犬鸣朝接，牛羊下夕昏。\n燎红人未散，举白酒频温。\n何幸投簪客，金龟藉渥恩。","地启南山胜，春开北海樽。\n论乡知谊厚，缩席见温存。\n兀石云黏护，磨崖字剥痕。\n山腰笼古树，巘侧敞晴轩。\n烟火孤城隐，蚕桑旧俗敦。\n迎阳花欲舞，悦客鸟能言。\n纳履跻云顶，攒衣坐石根。\n薜窗牵蔓蒂，药圃长芽荪。\n河洛开畴画，麟凰见野原。\n逢时欣舜日，浪迹寄山门。\n问奕吾生拙，焚香且细论。\n凭虚观太始，见水觅真源。\n机息鸥邻席，烹茶鹤避烟。\n橐枢归造化，裘葛付寒暄。\n自得山林寂，宁知朝市喧。\n抟鹏穷日表，瞿蝶托宵魂。\n天阔眸踰迥，山幽俗避繁。\n荷衣随泻适，绣绂敢攀援。\n虚引山涵泽，弘含地势坤。\n花封琴静鼓，萝径约同扪。\n玉浸晶光合，屏联翠色屯。\n锦鬐舒泳跃，仙羽出笼樊。\n凤去凌霄翥，龙来蜿地蟠。\n春融千里邑，风动万家村。\n鸡犬鸣朝接，牛羊下夕昏。\n燎红人未散，举白酒频温。\n何幸投簪客，金龟藉渥恩。"],["万里音书迥，千峰障雨秋。\n多君越国步，慰我入乡愁。\n缩席期宵话，鸣和晓发驺。\n愧无琼玖在，何以寄绸缪。",""],["路马金台别，江鱼尺素多。\n梦魂徒想像，肥瘠近如何。\n日暖迎阳石，风晴珠海波。\n相携定何日，樽酒对长歌。",""],["面缔人群易，心符古道难。\n犹期双凤起，未惜一龙蟠。\n绿树罗山合，缁尘蓟北寒。\n春来知有寄，能不付飞翰。",""],["霜蹄趋冀北，玉殿迥天开。\n六善躬敷奏，重瞳首屡回。\n乡关曾不念，国本藉深培。\n细酌杯中物，称诗咏有莱。",""],["百川吴越会，千顷自回环。\n浴日浮金晕，乘风涌雪山。\n扁舟饶蠡趣，只鹤伴逋闲。\n独有先忧思，临流亦泪潸。","百川吴越会，千顷自回环。\n浴日浮金晕，乘风涌雪山。\n扁舟饶蠡趣，只鹤伴逋閒。\n独有先忧思，临流亦泪潸。"],["九转登崇秩，分符尚远陬。\n明王孚化外，赖尔洽民遒。\n问俗垂朱绂，论心接素秋。\n甘棠南国颂，应作裔氓讴。",""],["乾坤浑逆旅，信宿又行期。\n浪迹成何事，虚名愧自縻。\n春藏杉柏古，月朗鹤琴随。\n明发燕台路，芳樽且对时。",""],["乔木千章古，丛林一径通。\n亭依苍障立，人在翠华中。\n逸兴朝随鹿，冥心晚托鸿。\n小坡偏忆汝，吾欲驾长风。",""],["洛社开春会，江船向晚移。\n停云天尺五，隔水月微熹。\n梦切飞凫舄，怀多采葛诗。\n百年珍重意，何以答吹篪。",""],["斓彩阶前舞，纶音日表来。\n周邦良翰喜，铁面绣衣回。\n孝重光前烈，猷需济世才。\n独怜狂简在，吾党向谁裁。",""],["昌期千载会，圣政一时新。\n访落追遗诏，耕莘起逸民。\n生成天共远，优渥海重仁。\n宿学欣逢展，龙颜日见亲。",""],["峭壁开灵洞，春山杖短藜。\n花光霞掩映，泉溜石争奇。\n洗盏侵龙沫，扪萝蹑鸟逵。\n追欢情不极，挥翰共裁诗。",""],["渭滨人去远，岳岳斗边看。\n入室思追步，乘风愧刷翰。\n纲常千古重，胆气万奸寒。\n孰揭擎天柱，颓波一障澜。",""],["四峰初雪霁，孤顶拥银城。\n返照天光入，禅灯月并明。\n简书封禅古，松竹岁寒盟。\n欲作擎天汉，毋为虚此生。",""],["凌晨发都石，薄晓抵焦陵。\n云暗树疑暝，风号滩有声。\n双眸悬岳色，一梦赘乡情。\n岁律忽云暮，扁舟湘水行。",""],["念女悬弧日，从予适楚行。\n灵椿长在侍，宿草若为情。\n冷祲连云谷，晴曛隔穗城。\n感今伤往事，能不重沾缨。",""],["岭海伤离索，湖郧故远来。\n路从花径入，门傍水洲开。\n秉烛惊看面，随裾愧短才。\n夜深宵露冷，且得煦春台。",""],["皎月开云际，和风荡柳边。\n逢春应倍喜，叙旧总堪怜。\n葭水盈坻址，星霜阅岁年。\n特携二三子，端的问心传。",""],["湖海天同迥，居诸日并修。\n传灯惭太乙，采药自罗浮。\n郊野联嘉会，江山借胜游。\n多君医国手，药圃匝旬留。",""],["犹羡郧阳水，源通粤浦沙。\n成人方浻酌，稚子讵当家。\n海若从今识，蹄涔敢自夸。\n预愁退省日，漂泊竟无涯。","犹羡郧阳水，源通粤浦沙。\n成人方浻酌，稚子讵当家。\n海若从今识，蹄涔敢自誇。\n预愁退省日，漂泊竟无涯。"],["剪烛夜殊永，论心席每前。\n绝尘偏我后，登岸喜公先。\n珠匮应兼在，金针是此传。\n六年空筑室，一唯独曾贤。",""],["白首耆英会，青云伟器多。\n德星联的烁，沂点意如何。\n傍柳寻幽赏，临流发浩歌。\n韶光容易过，同趁肯蹉跎。",""],["放舟辞楚泽，击楫向吴宫。\n五岭牵愁杳，三山入望中。\n一天俱着月，何地再逢公。\n汉北江南夜，相思意未穷。",""],["灵山钟地脉，古洞隐云台。\n路引千松入，门临一鉴开。\n振衣怜晚步，倒屣漫相催。\n会合天应定，披蹊拟剪莱。",""],["廿年违缩地，千里庆登台。\n蟾桂丛丛发，绥桃岁岁开。\n称觞霞共割，觅句雨初来。\n欲缵南山什，赓歌愧有莱。",""],["沙贝留芳躅，江门峙钓台。\n万年洙泗泽，一派石塘开。\n不老朱颜在，宁因白发催。\n况多沂点伴，信足是蓬莱。",""],["绝壁开灵窍，飞湍落翠微。\n坐来尘鞅寂，听彻太音稀。\n雾湿栖玄豹，霞光映彩晖。\n乘槎天上事，何必问支机。",""],["古道夹长松，高贤不易逢。\n干旌今日见，玉简旧时封。\n紫府三千界，青螺四百峰。\n谈经初隐地，曾叩午时钟。",""],["涧路倚天斜，穿林破晓霞。\n空中楼阁见，阶左药苗赊。\n入室惭窥奥，开门喜到家。\n幸逢传道叟，相对碧桃花。",""],["石室寒仙迹，离宫没草痕。\n偶依华盖麓，真辟洞天门。\n九曲清歌合，诸贤过化存。\n重来薇省辙，山岳此逾尊。","石室寒仙迹，离宫没草痕。\n偶依华盖麓，真辟洞天门。\n九曲清歌合，诸贤过化存。\n重来薇省辙，山岳此踰尊。"],["下瞰疑无地，翘瞻别有天。\n飞云登此日，浮岛自何年。\n岁事开元始，春光溢海埏。\n默从观化坐，休更问言诠。",""],["草色环幽砌，花光悦赏眸。\n酒添春日兴，宾为主人留。\n石壁方回照，银灯欲上楼。\n相期今夜月，还与细赓酬。",""],["已知生计薄，戛釜待丰年。\n运转三阳泰，晴占八日天。\n秋租方半赐，斗米欲三钱。\n早办菑涂耒，勤耕北廓田。",""],["久负龙江约，俄鞭鹤驾行。\n金兰联旧会，玉宇肃秋清。\n寺隐岩扉合，香浮石磬鸣。\n共歌天保颂，千载祝皇明。",""],["古洞藏勾漏，琪宫挹太清。\n执鞭瀛岛客，飞舄紫芝城。\n烛底流金液，云中起玉笙。\n廿年尘鞅外，时得寄幽情。",""],["路引朱明宅，楼高倚翠霞。\n江门曾授钵，沙贝此移家。\n坐榻光风远，敲诗到日斜。\n玉梢梅吐白，端可记年华。",""],["骑牛仙子远，卜筑隐人居。\n阁有匡时策，亭庋问字书。\n云烟随杖屦，霖雨入耕锄。\n客至冠裳倒，休嫌礼数疏。",""],["耽山偏我僻，阅世总云浮。\n屋角游丝静，庭空积翠稠。\n出门迎道侣，入室愧前修。\n五百乾坤会，今经到几秋。",""],["颇厌英皇宅，偏宜冷翠间。\n绡烟笼月脸，膏雨洗云鬟。\n瘦骨卑春态，真丹驻老颜。\n瑶池疑有约，翘首玉门关。",""],["四百撑天柱，孤高是此峰。\n霄中红日绚，崦半白云封。\n控引沧溟阔，衡分岱岳宗。\n微茫归路晚，应听定禅钟。",""],["怀云贤邑宰，意气若予谋。\n琴鹤初来郡，图书一去舟。\n浃时新雨露，问俗见歌讴。\n海甸殷民瘼，仍期疏衮旒。",""],["跃出飞云嵿，人从天上行。\n八埏归一撮，千岳洞双明。\n有物都观我，还谁博爱生。\n欲乘云雨施，枯槁尽流形。",""],["伊洛渊源远，人推伯子贤。\n奇文应拟古，卓行允开先。\n会意三山月，知音一素弦。\n江湖夙昔念，去去庙廊宣。",""],["五百乾坤会，千流脉派明。\n光风连半席，寒雨话分更。\n广誉瞻乔岳，真诚动帝京。\n不禁游子梦，偏自速归程。",""],["买醉分春道，凭高忆少汾。\n洞中长爱日，树杪几怀人。\n叱驭青牛出，移书白鹿新。\n倘然双燕在，遥借日同论。",""],["为语栖霞子，朱明石阁中。\n象棋柯斧烂，龙鼎汞丹烘。\n醉枕麻姑秘，闲房仙女东。\n客从人世去，飞锡又谁同。","为语栖霞子，朱明石阁中。\n象棋柯斧烂，龙鼎汞丹烘。\n醉枕麻姑秘，閒房仙女东。\n客从人世去，飞锡又谁同。"],["松菊欹陶径，芝兰忆谢家。\n暖风鸣剑叶，春雨长琼芽。\n入室香随化，同心味更加。\n丈人能识取，徽轸共年华。",""],["玉笋凌千仞，虹轮跨九霄。\n拂衣红日近，回首白云遥。\n树色通阛阆，山光入画描。\n暂同登眺乐，心已在明朝。",""],["一毡怜独冷，九载尚儒官。\n过雨兼时洽，看春易地宽。\n树深云外叶，丹老鼎中丸。\n万里风初厚，天池翮正抟。",""],["忆别愁多绪，临笺愧懒予。\n椿荆宜肖旧，兰桂近何如。\n鼓棹千江月，传家万卷书。\n紫霄别平地，随意各怡愉。",""],["简书专阃外，节钺出天涯。\n八阵骧龙虎，三驱殪兕豝。\n金瓯元已固，铜柱绩非遐。\n从此安南地，车书大一家。",""],["郭野苍茫合，湖山隐映开。\n永怀千古杰，遥上四贤台。\n绕壁看题句，临风数举杯。\n醉归明烛夜，金炬愧非才。",""],["爽籁金飙发，明河玉辇过。\n秋光怜尔独，古照阅人多。\n笔战犹金鼓，笙歌忆绮罗。\n有人桐影下，笑笑问嫦娥。",""],["棘闱夜寂寂，凉月秋涓涓。\n影动三千界，光盈二八前。\n较材归艺圃，聚彩烛金躔。\n皓魄知人好，今宵觉倍圆。",""],["岳伯分符日，湘江祝寿时。\n两辰开夙燕，双鹿产新儿。\n挟毂占嘉茀，悬铜纪秀眉。\n世南原有赋，谁为缵骚词。",""],["青衫还忆旧，白下更依然。\n解识驰驱范，宁分尺五天。\n雪寒征旆道，日近衮衣前。\n寿粒灵丹在，东南肯借怜。",""],["淑景开元旦，祥光护玉宸。\n陛墀千丈晓，海宇万年春。\n旧爱惟金鉴，孤忠有棘臣。\n炉烟回合处，喜气正鲜新。",""],["署判南京兆，遥思章斗阳。\n蜀高山月白，吴阔树云苍。\n陋巷时方乐，过门心正忙。\n何当风雨夜，兰刹复联床。",""],["洞僻烟萝古，山回涧竹幽。\n小桥双岛合，深径落霞收。\n玉井莲长夏，金飙树早秋。\n梧空潭影静，身世亦虚舟。",""],["温泉移旧地，高赏复同君。\n野曲乘流渡，空箫隔洞闻。\n韶光将到律，暝色欲留云。\n斗酒欣良夕，何妨更论文。",""],["路旁吼狮子，洞门隐伽佛。\n既登崇明台，直探玄虚窟。\n滴溜悬黍珠，玉田养丹粒。\n试问乔与松，如何永呼吸。",""],["紫府隔人寰，青莲偶共扳。\n鱼凫归瞬睫，乌兔迭双圜。\n仰眺天通窟，穷探洞转湾。\n达摩犹面壁，何日锡飞还。",""],["绝壁孤根起，中天积翠浮。\n看春谁是伴，伐木故相求。\n路入寒云湿，窗涵晚壑秋。\n耽山吾有癖，还尔共傲浮。",""],["出郭凌风眺，沿郊趁晚凉。\n凄枫惊落叶，彧稌游成行。\n溉釜需燎急，催租走檄忙。\n万方今有喜，逋待得新偿。",""],["我爱右洲子，相怀隔曲湄。\n汀葭秋水合，村树晚云移。\n砚榻交情在，琴樽逸兴驰。\n何当频缩地，细与话心期。",""],["观生观我得，适意且观鱼。\n泳跃心何有，浮沉体自虚。\n忘机常罢钓，到倦总抛书。\n一曲沧浪调，闻之亦起余。",""],["揽衾起中夜，抱膝故沉吟。\n未了心头话，谁拈指上琴。\n去云天共远，来月夜同深。\n何物凭消遣，惟应酒自斟。",""],["城隅真隐地，扫迹远逃名。\n坐到嚣尘寂，忽闻莺鸟鸣。\n金梭随柳转，玉律细风迎。\n宛奏咸和曲，浑疑广莫行。",""],["八月已无雨，冬来尚熯云。\n硕苗含稿穗，遐土尽焦焚。\n作旱疑凶寇，荒年岂大军。\n欲赓云汉什，何以慰民勤。",""],["龙斗江中息，渔歌泽上苏。\n盘堆仍角黍，杯沥带菖蒲。\n月向将弦上，风从隔竹呼。\n池亭欣避暑，谁复吊湘无。",""],["槛外闲窥沼，水深多纵鳞。\n升沉原自性，游跃故相亲。\n洗砚吞吐墨，忘机罢钓纶。\n畏途风已静，吾亦水云身。","槛外閒窥沼，水深多纵鳞。\n升沉原自性，游跃故相亲。\n洗砚吞吐墨，忘机罢钓纶。\n畏途风已静，吾亦水云身。"],["入境诸天寂，跃鱼时在津。\n岂因琴出听，应罢钓来驯。\n鬣破龙门锦，波翻禹浪银。\n济时云雨具，应与后生论。",""],["元宵开此夕，里社始悬灯。\n岂识常明照，还当最上层。\n清光瞻兔腹，梵语净伽楞。\n适意归吟弄，逍遥寄大鹏。",""],["瑶池分玉液，流出绩溪东。\n月漱晶光满，山涵镜彩融。\n建庵遗竹圃，启院有花封。\n一派渊源远，盈科与海通。",""],["四峰雷送雨，短夹怯春寒。\n遣兴偏宜酒，凭虚共倚栏。\n泉声和涧底，树色隐云端。\n喜得看山伴，阴晴总壮观。","四峰雷送雨，短袷怯春寒。\n遣兴偏宜酒，凭虚共倚栏。\n泉声和涧底，树色隐云端。\n喜得看山伴，阴晴总壮观。"],["自惜驰驱地，遨游今独闲。\n不因筵祖道，已破利名关。\n适意鸢鱼外，忘形天地间。\n德云苏老逝，休更问回环。","自惜驰驱地，遨游今独閒。\n不因筵祖道，已破利名关。\n适意鸢鱼外，忘形天地间。\n德云苏老逝，休更问回环。"],["高山盘郁处，兜率古禅庵。\n两壁悬清溜，诸峰拥翠岚。\n德星人几聚，奇迹我幽探。\n缱绻欲留带，高僧谁共谈。",""],["石径缘兜率，肩舆憩此台。\n南轩遗句在，北斗暮云开。\n百级阶前迥，千峰岭后摧。\n登临无限意，天霁约重来。",""],["汉左云连岸，郧阳月到船。\n棹歌聊劝酒，灯夕此开筵。\n绮阁辉银烛，琼楼沸玉弦。\n五羊东一望，凄况泬寥天。",""],["舞雩多夙伴，半月共云林。\n远眺天空眼，长吟月在襟。\n百年真此乐，千里祇同心。\n不有知音者，谁为浪鼓琴。",""],["震泽波翻定，层轩敞户楹。\n春来先着暖，日出早生明。\n地胜人同杰，孙贤祖有声。\n千年遗泽在，新沐振朝缨。",""],["雄藩罗岭海，突兀建宫墙。\n首善同文地，殊方会极场。\n阙林连拱秀，台斗焕文光。\n引步看秋色，庭槐已报黄。",""],["百粤风光丽，三城秋倍妍。\n祥云连粉堞，皎月耀晴天。\n水播鲲翎变，花明骥足先。\n河南原有谶，重见辂生鞭。",""],["美人违去久，杳杳隔芙南。\n青鸟岂无信，白鹅空有潭。\n樽开三度醉，赋辍几玄谈。\n树色秋光暮，临风意每含。",""],["野服囊孤剑，飘萧世外游。\n浮名几欲误，初服返真修。\n已蜕苍龙骨，时登黄鹤楼。\n洞庭明月夜，一啸碧天秋。",""],["半亩潮田云外陇，一区蔬圃水中洲。\n蓑衣犁透桃花雨，扣角无人问饭牛。",""],["天际罗帆诗景多，更添诗思入晴波。\n桥边月涌鱼翻藻，亭外风掀鹭闪荷。",""],["竹径茅庐是我家，三湾流水半溪沙。\n疏慵镇日浑无事，一灶秋云煮菊花。",""],["万籁无声山更幽，一泉绕屋石中流。\n才闻鹤向云间度，风送梨花上枕头。",""],["王气萧条向北都，犹勤天讨下蓬壶。\n江舟不解荆胥剑，南国空传蜀相图。\n古庙青觞灵马伏，野桥芳草白麟孤。\n谁知一别厓门震，楚水燕山恨未苏。",""],["晨昏二十四敲钟，声彻前峰并后峰。\n试问岩岩诸学士，已闻曾与未闻同？",""],["柳枝侵夏意仍怯，山麓出泉寒不流。\n我已十年穿虎窟，地今四月尚狐裘。\n思乡路远频挥泪，报主身轻何所忧。\n不惜千金求死士，雕戈直向古丰州。",""],["此日东篱菊放时，故人怀我正裁诗。\n玄晖疑有春池梦，潘岳应多秋兴词。\n汐落沧洲鲳鳜晚，霜寒梅岭橘橙迟。\n遥思清夜山阳会，玉笛声残月未移。",""],["良家初入未承恩，谩著罗襦锦凤纹。\n独向深宫倍萧瑟，不知何处望春云。",""],["屈指当年惊戊午，今年戊午益堪伤。\n甘泉烽火三韩急，濒海风涛八月狂。\n复以梧摧增涕泪，更于星变转仓皇。\n幸当此夕销除尽，坐待明朝瑞气翔。",""],["成仁取义忆前贤，异代同心几自鞭。\n血比苌弘新化碧，魂依望帝久为鹃。\n曾无尺寸酬高厚，惟有孤丹照简篇。\n万卷诗书随一炬，千秋霜管俟他年。",""],["千年雪耻事何如，十载人寰气颇舒。\n已向羊城收狡窟，更从龙塞觅狼居。",""],["竹马迎来冬日温，条风远拂陇头村。\n首阳亦属周疆里，敢道食薇不是恩。",""],["一扫浮氛今已清，几家鸡犬月中行。\n道人只合孤峰顶，卧听康衢击壤声。",""],["斗室行藏卧起徐，飘飖久矣白云居。\n世远桑麻乔木里，情闲风月短蓑馀。\n谢安不倦登临兴，阮籍真忘礼法疏。\n惆怅哲人今寂寞，孤吟搔首思踌躇。","斗室行藏卧起徐，飘飖久矣白云居。\n世远桑麻乔木里，情閒风月短蓑馀。\n谢安不倦登临兴，阮籍真忘礼法疏。\n惆怅哲人今寂寞，孤吟搔首思踌躇。"],["丘壑方求位置，烟霞遂结居诸。\n莫云此日关闭，茅径今朝手锄。",""],["有意林泉自得，忘机鱼鸟相和。\n八千里外藏迹，一勺堂中啸歌。",""],["回首风尘暂息，考槃寤寐相甘。\n试看云物如昨，始信劳人太憨。",""],["东山随地堪作，人境结庐未喧。\n苔径孤宜折屐，荆篱自止高轩。",""],["数卷图书作主，三春花鸟为邻。\n其馀无复长物，此内况容俗人。",""],["在水之中构室，开窗于此高眠。\n何知汉与魏晋，自谓无忧葛天。",""],["千林秋色回薄，四壁寒声悄然。\n晨起登楼眺远，苍苍满目飞烟。",""],["寒月空庭夜影，落梅满砌霜华。\n岭南白雪稀少，欲问阳春此花。",""],["秦地渔津日杳，漆园蝶梦时生。\n非关与世殊俗，聊亦从吾素盟。",""],["盆花次第依令，园果后先得时。\n物物深情可见，年年好景须思。",""],["晓树临风骤舞，昏潮带月潜来。\n忘言独对终日，静掩柴扉不开。",""],["酒熟惟思座上，花开移置阶前。\n有时少长咸集，几度幽人未眠。",""],["日落榕阴翠匝，风摇兰径芳微。\n梦蝴枕上初觉，啼鸟枝头未归。",""],["雨过忽变芳草，潮退时翻落花。\n清景当前屡易，浮生此际何涯。",""],["习静因知得力，逃禅本觉无心。\n朔望一变潮汐，今古随流浅深。",""],["髀肉经时易满，剑光每夜难韬。\n独惭纸上青汗，空付床头白醪。",""],["执戟多年倦客，步兵累岁闲身。\n草玄独俟知己，眼白相看世人。","执戟多年倦客，步兵累岁閒身。\n草玄独俟知己，眼白相看世人。"],["何须问众清浊，且自观心逸劳。\n在我应从古制，于人合让时豪。",""],["屈指粤东名丛，曲江南海瑶山。\n斯文未丧今日，后死谁人可班？",""],["一往深情诵读，半生乐事诗书。\n承明著作还彼，百代风骚待予。",""],["十载游心抱白云，醉翁亭记醒中文。\n分明庆历当时事，五百年馀独付君。",""],["醉醒惟许二能翁，兴废难移百代风。\n若道水山无定属，今之健者岂惟公。",""],["留得丰山故主人，诸贤后死始堪怜。\n当年醉意今如在，但掬清泉似饮醇。",""],["峰回路转尽繁阴，独立萧然见古心。\n为问诸宾从太守，何如禽鸟乐山林。",""],["不愧梅花是此人，环山得一永为邻。\n冰心独壮千秋雪，老干还滋万古春。",""],["潺潺泻出两峰间，刮尽云根破石悭。\n香冽寻尝归众口，清辉独洗醉翁颜。",""],["千年唐宋文章价，江海潮如此亦然。\n淘泻心胸存底物，盈科万古视原泉。",""],["水山幽至便通灵，云壑虚生动窈冥。\n一自天言河汉落，龙渊千载尚留形。",""],["雨作山游兴以心，良知一炬照云林。\n忽然夜半求真觉，独有春山动古吟。",""],["春薄难分千树色，台幽独剩数梅新。\n林泉付与公馀乐，鱼鸟繇来择地亲。",""],["丰山幽谷共清泉，千载惟馀永叔篇。\n遮莫山灵容刻露，几多残碣费磨刬。",""],["醉时乐事醒时心，异代空将耳目寻。\n惟有山泉供俯仰，幽芳作意劝登临。",""],["光烟一缕导游心，回马盘纡出秀深。\n庶子泉流寒石动，玉皇殿倚碧霄临。",""],["着意探山山见情，无心出谷谷相鸣。\n独惭车马喧幽寺，可有文章答友声。",""],["危阶根向青冥底，古刹烟浮淡薄中。\n鸟聚龙参真法界，泉飞竹舞下虚空。",""],["冥漠中窥小有天，蛟螭徙窟让游鞯。\n奇山信有玲珑骨，不遇奇人腹自坚。",""],["千里川原似一毡，胸中丘壑转悠然。\n及兹心目方无障，何处云峰欲比肩。",""],["蟠龙见首百峰收，神物依人出旷搜。\n日落春风鳞甲动，云归夜壑爪牙浮。",""],["山从游熟转相深，十日钩玄满素心。\n赢得诸峰难偃蹇，春云无数绕衣簪。",""],["风光初与醉游颜，半是春情半是山。\n颇怪林泉如故识，自今清兴每来还。",""],["诗骚作性，兰雪居胸。\n神希太始，气轹王公。\n束发筮仕，南北西东。\n三仕三已，国尔忘躬。\n天光云影，得丧穷通。\n老依玄老，空此百空。\n遭逢一经，身许丹青。\n忧时遁俗，意洁情馨。\n翁马恒失，庄蝶未醒。\n甘苦异节，壮老殊形。\n收而远志，归我澹宁。\n古之遗直，今之沉冥。",""],["湖山相联，云汉中悬。\n湖山相得，星河下食。\n溯流在央，莫褰衣裳。\n从水一方，中心委徨。\n大之岩谷，小之石木。\n悠悠藻洒，望北飞瀑。",""],["挂席过鄱阳，匡庐压湖内。\n舟行二十日，一与名山对。\n弥旬风雨调，及此霁光贷。\n陵峦宿浮阴，绝顶舒叆叇。\n豁然峙澄流，近遥有馀态。\n出自珠玑口，苍然青壁块。\n倏忽暂逢迎，历历诸峰剀。\n插石拂层穹，积林吞众薆。\n紫氛生其上，将无白日碍。\n下飞瀑布泉，潈射奔空溃。\n洒落云天珠，势向扁舟碎。\n举头一挹之，烟颜坐可靧。\n而我览胜怀，初符宿所爱。\n敢云默祝开，晴明我适逮。\n虽云望中游，眼到身应在。\n云间意自清，尘外胸无退。\n灵秀远相披，况与明湖载。\n因知造物奇，以湖作山配。\n二三百里中，依依如襟佩。\n横侧一舟行，千岭争向背。\n日暮征帆遥，杳然波上黛。",""],["百里山行迷碧草，息心对山觉山好。\n六朝僧去忽千霜，三秋招隐惟五老。\n一峰初上晓松哀，瀑布声闻客绪开。\n舍车纵步过东寺，山僧谓我结莲来。\n莲社年来孰为首，我亦渊明性耽酒。\n颓颜独倩菊英滋，酣情易令苍山朽。\n祇今望阙复趋庭，云舍南溟动远汀。\n他时散发罗浮上，对望仙庐九叠青。",""],["自有庐山岁几千，鄱湖相对是何年。\n自有湖山初见我，一十四载九洄沿。\n每从南极瞻五老，及到西江望比肩。\n芙蓉削出珠玑口，银河倒泻香炉烟。\n九叠苍屏空杳杳，千寻瀑布亦溅溅。\n阴阳此际藏真宰，流峙分形俱后天。\n天生名山必有配，高广依稀二者传。\n非山莫与湖吐噏，非湖孰任山蜿蜒。\n雨后洪泉飞洒落，秋来惊浪恣腾骞。\n澄流舒卷如涘滴，芳麓沉浮但浣湔。\n不向湖情窥浩漠，安知山德备泓渊。\n湖山阅人亦有数，何人独领湖山全。\n百里舟行异横侧，多年望眼破拘挛。\n空灵一气开昏晓，幽光百道变黄玄。\n随意犹能招俯仰，息心或可尽中边。\n及此方求江汉始，因之欲向斗星连。\n耳目今朝如是耳，湖山万古自悠然。",""],["洪泉飞九叠，万壑动群氛。\n势落悬峰日，光摇出岫云。\n晦明殊所见，近远各为闻。\n顿令萦心目，孤情冷复氲。",""],["湖尽匡山际，江通汉水浮。\n朝烟生夹岫，夜月识扁舟。\n远望多为感，乡心少不愁。\n自怜身似苇，朝夕与波求。",""],["苍屏九叠尽飞荣，风雨千岩欲怒鸣。\n泉石初开天籁发，水山相杂大文生。\n每乘清气阴阳御，渐出光华人世迎。\n不是银河天际落，峰头那得挂长庚。",""],["四望苍屏尽渺然，松开忽见紫炉烟。\n怪来九叠祥光出，独向东林瑞像前。\n竺影难留图里迹，素沙犹自雨中研。\n几回频就山僧问，谁忆当年论五篇。",""],["白云作意令山深，平卷诸峰上客襟。\n欲因康乐寻幽兴，顿拨渊明入社心。\n薪火相传无异昔，愿文初发已从今。\n若待辞荣来此地，千年空属远公岑。",""],["终南成诟厉，所处失其亲。\n遥揖山灵语，慎居捷径人。",""],["相对无缘认岭峰，入看只与白云同。\n江舟竟日分横侧，真面遥临一水中。",""],["庐山如屏湖如镜，白云其容月其性。\n湖偏宜月山宜云，风以为媒初相娉。",""],["庐山误出此篇垂，多少徐人欲李辞。\n今日徐人才更倍，谪仙跽请主僧诗。",""],["五老峰深近远迷，六朝灯在色空倪。\n林僧索我庐山句，不尽游踪未敢题。",""],["征车偃蹇出松林，望入云丛最顶岑。\n为问三千三百六，可容一步一孤吟。",""],["点点云山在水旁，清沙碧渚侵晨光。\n西峰落月衔烟树，影到波心万顷苍。",""],["欲识庐山真面难，先从芳麓见髀髋。\n五老云中银汉落，香炉雪后紫烟寒。",""],["乔木森森望郁苍，相传岭国古榕乡。\n四时霜盖烟疏密，一片云丛绿混茫。\n道左何年歌杕杜，州南此日诵甘棠。\n天为炎土垂休息，故使馀阴百里凉。",""],["玉川如带绕城阴，入眼丛青翠影侵。\n已淈污泥从水出，遥参碧汉倩云禁。\n连翩各有扶疏质，独立犹馀萧飒心。\n不信松寒非可并，多年海国挺孤森。",""],["春光早向紫峰生，渐出峰容与世迎。\n古黛凝云初映晓，新苔转日久曛晴。\n啼莺城北衔幽至，舞燕溪南逐翠行。\n传语东风无造次，时留烟景作山情。",""],["城头北望晚山逢，久对悠然净俗胸。\n泉石情因深色见，烟霞癖与素心封。\n积云每见堆双洞，新月时来照一峰。\n十里幽光难可即，千秋苍质自为容。",""],["双溪垂带曳榕城，最爱光潮涌晚生。\n半落市埃分皓白，平开天镜下孤清。\n遥山助色烟云扫，近野浮空藻荇迎。\n长忆玄晖如练语，更添月意作江情。",""],["烟霞有意日相求，双洞林光竞远投。\n青霭春来如迸发，白云秋去尚群游。\n郁纡遥结山灵秘，冥寞中开佛象幽。\n试看今朝松竹影，方知千载色空留。",""],["龟山宝塔字涵元，灵杰相因表独尊。\n欲锁螭宫雄海柱，先驱鳌背壮天根。\n南来百水俱朝会，北拱诸峰各骏奔。\n若问参云尚有级，人文地气此初掀。",""],["溪城如岛水环之，西驾东流此一丝。\n万里海风浮汉影，百重山色压虹眉。\n于秋倍觉潮声壮，有月常窥钓影垂。\n每听沧浪歌曲罢，眼中清浊意中知。",""],["山途历四省，逾山步百邦。\n山从地分域，地因山别疆。\n穿山繇山径，依山止山乡。\n山蔬备晚食，山鸡促晓行。\n行行周山绕，宛在山中央。\n山心含故意，入山独彷徨。\n迤逦擐山足，跌踼陟山嶈。\n山岚蒙山暖，山树拂山凉。\n山容撤山景，山气发山光。\n山日浮幌荡，山峰破混茫。\n山风吐山响，山云焕山妆。\n山中静藏月，山外远连江。\n山峡流清潎，山谷激飙飏。\n山泉幽以泶，山林静而芳。\n山陵断还续，山蹊纡复障。\n山舟横山渡，山榾引山梁。\n屴崱连山脉，㠎嶪郁山冈。\n山居宅山曲，山家隐山傍。\n山城山作邑，山民桀如狼。\n山田多硗埆，山村掩寂荒。\n山中何所有，山坂富牛羊。\n山童啸山歌，两两在山畼。\n秋深山薄绿，冬至山敛黄。\n离叶散山翠，振条落山苍。\n山花孤承露，山卉半染霜。\n山松开山籁，山桂郁山香。\n山篱垂山菊，山竹披山篁。\n山骨劳巧匠，山鬼筑夜墙。\n山门溜夹水，山观寂飞窗。\n雨蒙山先翳，天霩山自旸。\n山庵如鸡栖，山路多羊肠。\n崒嵂崇山髻，嶕峣结山鬃。\n山石参山势，山滩竞山强。\n环山多郁垒，梯山就崆㟅。\n祇随山俯仰，莫计山短长。\n近山历可数，远山叠可望。\n期着东山屐，先拟北山章。\n全挹西山爽，还归南山阳。\n久从山朝暮，微识山行藏。\n赋成百山语，歌与百山商。","山途历四省，踰山步百邦。\n山从地分域，地因山别疆。\n穿山繇山径，依山止山乡。\n山蔬备晚食，山鸡促晓行。\n行行周山绕，宛在山中央。\n山心含故意，入山独彷徨。\n迤逦擐山足，跌踼陟山嶈。\n山岚蒙山暖，山树拂山凉。\n山容撤山景，山气发山光。\n山日浮幌荡，山峰破混茫。\n山风吐山响，山云焕山妆。\n山中静藏月，山外远连江。\n山峡流清潎，山谷激飙飏。\n山泉幽以泶，山林静而芳。\n山陵断还续，山蹊纡复障。\n山舟横山渡，山榾引山梁。\n屴崱连山脉，㠎嶪郁山冈。\n山居宅山曲，山家隐山傍。\n山城山作邑，山民桀如狼。\n山田多硗埆，山村掩寂荒。\n山中何所有，山坂富牛羊。\n山童啸山歌，两两在山畼。\n秋深山薄绿，冬至山敛黄。\n离叶散山翠，振条落山苍。\n山花孤承露，山卉半染霜。\n山松开山籁，山桂郁山香。\n山篱垂山菊，山竹披山篁。\n山骨劳巧匠，山鬼筑夜墙。\n山门溜夹水，山观寂飞窗。\n雨濛山先翳，天霩山自旸。\n山庵如鸡栖，山路多羊肠。\n崒嵂崇山髻，嶕峣结山鬃。\n山石参山势，山滩竞山强。\n环山多郁垒，梯山就崆㟅。\n祇随山俯仰，莫计山短长。\n近山历可数，远山叠可望。\n期着东山屐，先拟北山章。\n全挹西山爽，还归南山阳。\n久从山朝暮，微识山行藏。\n赋成百山语，歌与百山商。"],["齐国有奇士，卓行由性真。\n霸馀俗尚利，忽见三代民。\n兵荒家不残，货充廪粟陈。\n视义重丘山，黄金轻一尘。\n疾疢虽在亲，痛实切已身。\n拜医奉汤药，省养谨夕晨。\n钟爱赐厚资，誓与兄弟均。\n居丧逾礼制，毁慕泣苍旻。\n田屋让同气，举族怀其仁。\n慷慨割腴产，惠利饫孤贫。\n庾衮救疫勤，宋清焚劵频。\n元振给葬费，三人罕儗伦。\n今乃兼能之，恩义周乡邻。\n孝友万善原，任恤与睦姻。\n全德古所难，事状付史臣。\n旌褒光宅里，眉寿馀八旬。\n象贤乌府宾，宠秩绯鱼新。\n彩庭侍燕喜，几席生阳春。\n滔滔济河流，入海去无垠。\n福泽同其深，永以遗后人。","齐国有奇士，卓行由性真。\n霸馀俗尚利，忽见三代民。\n兵荒家不残，货充廪粟陈。\n视义重丘山，黄金轻一尘。\n疾疢虽在亲，痛实切已身。\n拜医奉汤药，省养谨夕晨。\n钟爱赐厚资，誓与兄弟均。\n居丧踰礼制，毁慕泣苍旻。\n田屋让同气，举族怀其仁。\n慷慨割腴产，惠利饫孤贫。\n庾衮救疫勤，宋清焚劵频。\n元振给葬费，三人罕儗伦。\n今乃兼能之，恩义周乡邻。\n孝友万善原，任恤与睦姻。\n全德古所难，事状付史臣。\n旌褒光宅里，眉寿馀八旬。\n象贤乌府宾，宠秩绯鱼新。\n綵庭侍燕喜，几席生阳春。\n滔滔济河流，入海去无垠。\n福泽同其深，永以遗后人。"],["李杜日已远，畴能振风雅。\n淫哇既纷靡，视古气益下。\n雷鸣喧瓦缶，遂谓黄钟哑。\n鱼目轻夜光，驽骀鄙宛马。\n独立天地间，长怀何由写。\n白雪非不弹，举俗和者寡。",""],["人生宇宙间，愚哲惰与勤。\n年华不可再，努力思超群。\n大禹寸阴竞，陶侃惜其分。\n不见东流波，昼夜方沄沄。\n吾徒但饱食，与俗同缤纷。\n既无良平智，又乏贾邓勋。\n立言著当代，庶以期斯文。",""],["习之习之，古自我作。\n习乎自然，学而不学。\n化工在手，天机可握。\n误笔成蝇，运斤去垩。",""],["临深履薄，匪曰觳觫。\n震不丧匕，心非槁木。\n上帝若临，天君自靖。\n有所于恐，不得其正。",""],["厥初生民，昊天降极。\n如冰斯寒，如火斯炽。\n相协尔居，日用饮食。\n尔识尔知，莫匪尔德。\n物有挠之，遂淫其则。\n其则不远，民用僣忒。\n鸡犬其心，见鹄思射。\n先民有言，不有博弈。\n眇兹寡陋，学也不力。\n若存或忘，终罔有得。\n汨汨厥灵，桑榆日逼。\n告尔同志，毋忘夕惕。\n上帝其临，兢兢翼翼。\n敬恭尔思，戒尔颇僻。\n载锄其骄，灵根其植。\n涵而泳之，河浸膏泽。",""],["古劳之下，有川洋洋。\n洋洋曷以，可濯可航。\n泛彼兰舟，与子同行。\n时届重阳，朗天清霜。\n临流怀旧，伊人云亡。\n俛仰今昔，云胡不伤。\n古劳之上，云山霅霅。\n霅霅曷以，以跻以悬。\n乘此柴车，与子同联。\n峍乎郁葱，于葵之根。\n登高望远，伊人不存。\n爰卜幽宅，以慰精魂。",""],["腊月既望，我徂自藤。\n云木翳翳，零雨其冥。\n有山如戟，有石如城。\n云餐雨立，仆夫于征。\n联我兰舟，与子同行。\n念彼室处，感兹靡宁。",""],["渔渊水深，采芝云迷。\n寄怀云水，抗志高栖。\n严霜陨木，归鸿背飞。\n天寒日短，途长行迟。\n岁云暮矣，我心则悲。\n神游八极，身囿两仪。\n宇宙为旅，万物为徒。",""],["瞻彼爱日，实慰我心。\n自我室处，天光下临。\n我行千里，弥月霾阴。\n仆夫痡矣，修途阻深。\n我行不辰，昊天何心。\n爱日熙熙，实系我思。\n于盘之子，尔暄尔曦。\n自我弥旬，风雨凄凄。\n我心忧矣，阻于涂泥。\n实命不偶，昊天何私。",""],["风云自天，龙蛇起陆。\n君子敬止，渊渊穆穆。",""],["𪾢睆黄鸟，遗音千山。\n怀我良朋，声闻其先。\n我之思矣，矧兹德言。\n黄鸟𪾢睆，响传千岑。\n怀我好友，弗思德音。\n我之忧矣，矧彼盍簪。","睍睆黄鸟，遗音千山。\n怀我良朋，声闻其先。\n我之思矣，矧兹德言。\n黄鸟睍睆，响传千岑。\n怀我好友，弗思德音。\n我之忧矣，矧彼盍簪。"],["瞻彼东山，巍巍南极。\n我怀君子，于山之侧。\n有渰其云，不雨而泽。\n秪以淹望，永言思德。\n将哦将思，陈侯是式。\n谁其赋之，少师无斁。",""],["坎坎击鼓，于樵之巅。\n乃荐乃献，尹公之贤。\n于贤维何，德义迁迁。\n坎坎击鼓，烟霞之下。\n乃咏乃歌，饯尹公者。\n于咏维何，德音雅雅。\n亦既击鼓，亦既考钟。\n以宴以乐，公坐于宫。\n维公在宫，威仪颙颙。\n击鼓喤喤，考钟锵锵。\n以乐以宴，公坐于堂。\n维公在堂，德容不忘。\n维钟维鼓，维瑟维琴。\n何以假之，嗣此德音。\n维此德音，维樵之岑。\n维琴维瑟，维钟维鼓。\n维以足蹈，维以手舞。\n其乐未央，公晏灵府。\n作乐歌舞，出饯尹公。\n声影悬矣，送之九龙。\n九龙跃跃，导之以樵风。\n谁其主之，兀厓来同。",""],["皇天眷德，全畀所覆。\n至于海隅，薄广左右。\n惟兹两广，实惟荒遐。\n顽氓聚啸，互相爪牙。\n屡廑南顾，屡简重臣。\n顺抚逆戮，均之圣仁。\n韩公用武，以严厥始。\n朱公用文，克和厥中。\n文武并济，将在今公。\n既和而玩，治久而隳。\n习为姑息，如病痿痹。\n天子神圣，天子曰嘻。\n顾兹不振，畴克振之。\n惟尔萧卿，懋兹六德。\n仁信智勇，文武是克。\n惟兹六德，乃懋厥功。\n率时六馆，奏尔鼎镛。\n公拜稽首，对扬天休。\n臣罔于家，聿来胥谋。\n惟时桂林，爰始兴事。\n贼方跳梁，将骄卒敝。\n公始下车，不遑煖席。\n亲秉旄钺，勇气有激。\n智以先之，仁以结之。\n信以成之，我军张威。\n六月于征，载穷其巢。\n俘获十千，凯旋告劳。\n广人有言，昔若奄奄。\n中丞是作，顽懦有廉。\n广人有言，昔尚萎靡。\n萧公来严，士皆作气。\n文武严和，成自公今。\n侯谁记之，守臣周任。\n周侯记之，太史文之。\n以奏成功，以告鼎彝。",""],["进履之心，可以授道。\n惜哉师传，未闻何奥。",""],["不醒是梦，醒亦是梦。\n既同是梦，长年何用。",""],["奕奕大族，世于乐清。\n维诗维礼，维以簪缨。\n匪维缨也，维礼维诗。\n维彼瓜瓞，胤庆无期。\n奕奕令族，世于高奥。\n维孝维弟，勿替尔祚。\n匪伊祚矣，维以孝弟。\n维以慈让，于庆千祀。",""],["心无一物，天理见前。\n何为天理，本体自然。\n廓乎浑兮，四时行焉。\n勿忘勿助，圣则同天。",""],["忘独忘寡，忘寡忘贫。\n七十六春，忘厥女身。\n贞一不分，乃通于神。\n是谓圣善，奚节之云。\n姥如未信，询尔舅孙。",""],["煌煌金芝，维山之辉。\n云谁之瑞，玉厓维祺。\n玉厓巍巍，金芝离离。\n金玉交映，君子以之。\n我有灵根，先天地春。\n美斯毓斯，维天维人。\n光于宇宙，瑞于无垠。\n思遗怀人，道远奚因。",""],["朔风飕飕，送子归舟。\n出饯于江，写我离忧。\n虽则离忧，匪厉则逸。\n人亦有言，召命不日。",""],["陟彼泉山，其山崇崇。\n其崇曷以，坯土之丛。\n坯土之受，坯土之积。\n于千万仞，维以崇德。\n崇德曷以，忠信其址。\n谁学此山，子朱子礼。",""],["奕奕钜汪，司马昌之。\n嗣子胤孙，无匮其祺。\n昭昭越王，生而前知。\n神明日发，不可测思。\n不可测思，矧可忘思。",""],["视彼牛尾，牧者骇异。\n威慑六州，六州控制。\n有而不有，于唐之世。\n留守九宫，王号是畀。\n矧可忘斯，念兹厥始。",""],["登源之茔，萎木再荣。\n千春枯槁，谓匪神功。\n氓曰神哉，曷感而通。\n鞠哉冢宰，树此感忠。\n树此感忠，念祖无忘。",""],["其忠维何，岭表寔多。\n积十馀稔，经略威和。\n亦职海道，朗机扬波。\n公乘长风，夺其长技。\n曷不怀嗟，曷不怀嗟，念此荣柯。",""],["何以怀云，视尔赤心。\n贼濠逆天，奋戈入擒。\n言誓妻子，告尔有神。\n所不如愿，宁殒厥身。\n宁殒厥身，顾念忠勋。",""],["忠勋念兹，何日忘之。\n君尔忘身，公尔忘私。\n摅谋决策，坐亡群疑。\n惟此忠悃，惟帝眷知。\n感兹眷忠，无忝孝思。",""],["思彼槁木，犹感忠诚。\n矧伊人矣，云胡不灵。\n感忠以劝，联楼峥嵘。\n拄地撑天，聿怀永宁。\n聿怀永宁，勿替休征。","思彼槁木，犹感忠诚。\n矧伊人矣，云胡不灵。\n感忠以劝，联楼峥嵘。\n拄地撑天，聿怀永宁。\n聿怀永宁，勿替休徵。"],["天地合德，为阴为阳，为雨为霜。\n圣人合德，为喜为怒，为文为武。\n或以揖让，或以毅果。\n如人一身，弛张在我。\n在我弛张，文武一道。\n一道在我，无施不可。",""],["我怀铁江，宝安之阳，隔水汤汤。\n有美一人，水中之央。\n水中之奇，中气粹之。\n何彼德星，生宁馨儿。\n其馨维谁，柱也之材。\n黄堂之祯，邦家之维。\n亦治九华，寿祝无涯。\n维以大耋，维德之遐。\n维神斯听，竹实是征。\n颍川之治，凤凰来鸣。\n遐以寿昌，遐以显扬。\n寿斯永斯，君子之光。","我怀铁江，宝安之阳，隔水汤汤。\n有美一人，水中之央。\n水中之奇，中气粹之。\n何彼德星，生宁馨儿。\n其馨维谁，柱也之材。\n黄堂之祯，邦家之维。\n亦治九华，寿祝无涯。\n维以大耋，维德之遐。\n维神斯听，竹实是徵。\n颍川之治，凤凰来鸣。\n遐以寿昌，遐以显扬。\n寿斯永斯，君子之光。"],["陈乐高堂，华筵广张。\n寿山为俎，北海引觞。\n贞哉圣善，笃生二郎。\n维孟有轲，维范有滂。\n伯供戏彩，仲捧翟裳。\n伯氏吹埙，仲氏吹篪。\n乐从天来，人自不知。\n宛宛王母，宴于瑶池。\n三千之实，偷桃之儿。\n昭昭圣善，亦严亦慈。\n既寿且荣，封章有辉。\n自兹古希，万寿无期。",""],["昔我视尔，兄弟不犹。\n今尔既立，视我如雠。\n虽则如雠，我心不尤。\n事我之心，转而他人。\n凡今之人，薄如秋云。\n虽如秋云，我心贞珉。\n昔操我戈，今入我室。\n匪则入室，道命不一。\n其一不一，我心中实。",""],["窈窕者谁子，绝代亮无双。\n不谙小姑性，以直终见伤。\n虽则终见伤，中情容何妨。\n谁为别鹄吟，此曲多慨慷。",""],["迟迟别帝都，迟迟胡乃尔。\n臣躯易弃捐，臣心讵能死。\n天王会圣明，帝阍亦孔迩。\n援琴不成声，掩抑泪横泗。",""],["黄鸟亦有友，空谷遗之音。\n相呼上乔木，意气感人深。\n君今脱网罟，遗我在远林。\n自我初识君，道义日与寻。\n一身当三益，誓死以同襟。\n生别各万里，言之伤我心。",""],["北风吹湖船，帆挂南岳树。\n祝融下玉坛，却立问来去。\n知君有仙骨，相期事轻举。\n胡为凌风波，恐为蛟龙取。\n君若访五峰，愿留共君住。","北风吹湖船，帆挂南岳树。\n祝融下玉坛，却立问来去。\n知君有仙骨，相期事轻举。\n胡为淩风波，恐为蛟龙取。\n君若访五峰，愿留共君住。"],["行行过湘浦，举首望九疑。\n若见重华墓，为我三拜之。\n三拜之不足，稽首重致辞。\n都俞事久阔，嗟予将安归。",""],["我有三尺木，囊括久不弹。\n一朝遇知音，为君初上弦。\n上弦含清响，未弹意先传。\n赠君别鹤操，报我以孤鸾。",""],["皇天常无私，日月常盈亏。\n圣人常无为，万物常往来。\n何名为无为，自然无安排。\n勿忘与勿助，此中有天机。",""],["穷索不穷索，穷索终役役。\n若惟不穷索，是物为我隔。\n大明无遗照，虚室亦生白。\n至哉虚明体，君子成诸默。",""],["天地我一体，宇宙本同家。\n与君心已通，离别何怨嗟。\n浮云去不停，游子路转赊。\n愿言崇明德，浩浩同无涯。",""],["长鱼有奇种，运鬣翳南溟。\n一朝生羽翼，九万起云程。\n二仪范淑质，日迈月斯征。\n霜风吹百草，百草为不馨。\n愿言自栽培，不逐众衰荣。",""],["吾慕严先生，殊非巢许徒。\n出处似合道，为义匪为高。\n宾友分已定，从官何乃劳。\n展足卧故人，故态知狂奴。\n欠伸动天象，况乃人主乎。\n惜哉帝王真，大老归江湖。\n孰谓天地量，徒见客星孤。\n公卿满汉庭，纷纷索谶图。",""],["步出草萍关，举首见怀玉。\n超然动遐想，中有彩云屋。\n山高天宇空，安知白日速。\n翩翩青鸟使，暮归玉台宿。",""],["渔者乐水浅，鱼性乐水深。\n渔鱼各有欲，虚舟本无心。",""],["子房报韩心，毛公捧檄意。\n衷曲谁能亮，举世皆非是。\n圣哲明几先，众人视成事。\n浊水出磨泥，一朝迥神异。\n士志各有定，肯为俗下比。",""],["嘐嘐嗟断金，悠悠结同心。\n同心苟不固，胶漆亦未深。\n杯酒出肺腑，按剑起知音。\n朝为鱼水欢，暮为商与参。\n同学张陈子，干戈竟相侵。\n去去请息交，鸥盟蚤当寻。\n钟期或未死，吾且囊吾琴。",""],["桃李默不言，流莺语春风。\n语默各有性，此理谁能穷。\n羁靮不由人，圣人有天工。\n岂无神化术，能使蛇作龙。",""],["闲处有真忙，忙处有真闲。\n始知真闲忙，不在闲忙间。\n在人有万变，此心无往还。\n往还在通塞，坐与事物关。\n无适无不适，物物有至神。\n嗟彼游心子，求之蓬莱山。",""],["匡庐何所极，苍苍阁晴空。\n兄弟事幽讨，同日蹑奇踪。\n炼形化精魄，列为五老峰。\n物固有不朽，万代垂高风。\n我欲访其居，道远谁能从。\n长揖入翠微，冥栖结云松。\n从予以朱鸟，闲骑一苍龙。","匡庐何所极，苍苍阁晴空。\n兄弟事幽讨，同日蹑奇踪。\n炼形化精魄，列为五老峰。\n物固有不朽，万代垂高风。\n我欲访其居，道远谁能从。\n长揖入翠微，冥栖结云松。\n从予以朱鸟，閒骑一苍龙。"],["送别崇文郊，欲别还踟蹰。\n别远会恐难，延缘且斯须。\n与君会此地，十六星火除。\n后会安可必，人事靡常居。\n松柏化为薪，平陆成沮洳。\n变态若风云，念此心烦纡。\n江流罔昼夜，钟山郁葱如。\n万变皆在人，无事应簿书。\n人生驹过隙，日月倏转车。\n崇德贵及时，愿君爱玉躯。",""],["四时有去来，逐客久不至。\n天运尚可量，人事谁能计。\n昨夜梦见之，仿佛精神契。\n语久声弥低，画地示予字。\n灭没不可辩，了了得其意。\n言别何匆匆，路远会难继。\n合欢讵知梦，是梦聊足慰。\n借如平生魂，亢爽不可致。\n念之生悲凄，达旦不能寐。",""],["阴阳无停机，天道常流转。\n除夕依辰至，岁月忽已晚。\n感节念年非，令人发悲惋。\n少壮多志气，白发已乱短。\n行年逾不惑，知命途尚远。\n誓当师继日，畏此流光遄。",""],["促促笼中鸟，脉脉念远林。\n远林在何许，乃在增城阴。\n增城云九重，结巢最高岑。\n自罹尘网内，胡乃独伤心。\n仰见云间翼，窅然遗我音。\n愿言养奇翅，高举待秋深。",""],["阳气回管律，百虫已惊蛰。\n彼虫尚有情，草木皆萌蘖。\n君心亮匪石，坠井不复发。\n三年事远游，一去无书札。\n天道苟好还，君当终言旋。",""],["黄鹂出幽谷，款款闻新音。\n感我伐木篇，长言被弦琴。\n小弦意迫切，大弦纡思深。\n馀韵托南风，翻作龙场吟。\n上以期琢玉，下以期断金。",""],["一莺或两莺，嘤嘤若求善。\n意气正相感，忽值时节变。\n时节日已变，君行日已远。\n一隔如参商，咫尺不相见。\n相见不尽情，相思难嗣声。",""],["烨烨璞中玉，重拟连城赀。\n戒之在雕琢，勿为人所欺。\n君身有至宝，灵莹无瑕疵。\n去去求名工，无为强凿之。\n败甲与枯草，尚可决吾疑。","烨烨璞中玉，重拟连城赀。\n戒之在雕琢，勿为人所欺。\n君身有至宝，灵瑩无瑕疵。\n去去求名工，无为强凿之。\n败甲与枯草，尚可决吾疑。"],["形下下影响，形上上神奇。\n智愚一以远，慎哉此毫厘。\n上下匪一体，何由知彰微。\n修之在敬义，人力非天机。\n请勿信我语，亲见乃不疑。","形下下影响，形上上神奇。\n智愚一以远，慎哉此毫釐。\n上下匪一体，何由知彰微。\n修之在敬义，人力非天机。\n请勿信我语，亲见乃不疑。"],["大化在咸若，渔利及小鲜。\n喜戚以我故，口腹为心缘。\n闻有直钩子，此道今莫存。\n丈人濠上翁，回溪有潜鳞。\n悠然观澜处，或跃见天真。\n物情有冥会，此乐未易言。\n因思网罟设，自古无全仁。",""],["清清塘中莲，亭亭思公贤。\n思公爱公莲，欲往隔湖天。\n通直得自性，芳意谁与传。\n岂无牡丹艳，徒为俗子怜。\n扳荷玩水珠，弄化不成圆。\n何因动遐想，敛衽莲峰前。",""],["明月当中天，逍遥步前庭。\n问是此何时，昏中正虚星。\n嗟叹良独久，化机倏流行。\n白鸟会中昃，海蟾岂常盈。\n粲粲彼姮娥，皎洁含天灵。\n长风扫云翳，率土仰贞明。\n所嗟时不待，几见天河清。",""],["孤居感名节，三四见星虚。\n漫漫中夜心，良人自远徂。\n昔忧见面难，不谓无简书。\n感叹嗟何及，吞声涕涟如。\n明月云无私，不为照区区。\n会合一何欢，隔离一何冤。\n耿耿离合情，万里同月圆。",""],["南溪春何如，泱泱映涟漪。\n涟漪绿何如，白鸥来染衣。",""],["南溪夏何如，漾漾浩弥漫。\n弥漫深何如，满意看浴云。","南溪夏何如，漾漾浩瀰漫。\n瀰漫深何如，满意看浴云。"],["南溪秋何如，澄澄澹清幽。\n清幽皎何如，可鉴鱼虾游。",""],["南溪冬何如，涓涓细清浅。\n清浅静何如，寻源观蟹眼。",""],["游子涉江去，采采南涧芹。\n采之欲何为，岁暮寄怀人。\n怀人自不远，岁暮行当返。",""],["镜光前无路，才行始通窍。\n窈窕入云磴，攲侧行木杪。\n凭虚知天高，俯下觉形小。\n诣道如是观，洒落万物表。",""],["镜光本胜游，匪为谢尘扰。\n登高舒远眸，习静观众妙。\n风景翻多忧，履危愈悄悄。\n悠然望旷野，目尽意不了。",""],["我或求珷玞，人或畀璚玖。\n非不爱璚玖，向人难启口。\n启口恐吠声，听听国多狗。",""],["我或抱荆璞，人或夸燕石。\n非不诬此石，向人难历历。\n历历恐伤明，明者当自识。","我或抱荆璞，人或誇燕石。\n非不诬此石，向人难历历。\n历历恐伤明，明者当自识。"],["人或采桃李，我或赠芙蓉。\n非偏爱芙蓉，直外仍通中。\n静直春风表，不为众芳容。",""],["无极我之先，大块我之后。\n问我是何物，见之亦无有。\n纷纷形迹间，聚散讵能久。",""],["绣衣乘青骢，矫矫气如龙。\n霜蹄振山岳，踏躞生秋风。\n问君何所如，直指湖西东。\n问君何所事，皇命肃清戎。\n戎籍亦已繁，号声上通天。\n仍闻父老叹，逃亡尚未还。\n室有新寡妇，膝有新孤孱。\n何当见使君，长跪告此冤。",""],["秋月缺复圆，客行久不还。\n不还岁亦暮，念子屡长叹。\n叹罢继以歌，歌竟泪如泉。\n何时得会晤，所怀万一宣。",""],["涉园采桃李，持以赠所知。\n非贵桃李颜，不言自成蹊。\n岂无兰桂好，质以香自亏。\n默默牛医子，心期浩无涯。",""],["封书寄燕雁，雁不过衡阳。\n封书寄江鱼，鱼沉江水长。\n江水亦有竭，封书永不灭。\n耿耿无由宣，心绪自中结。",""],["涧水何泠泠，涧石何磷磷。\n漱之欲奚为，石苔自无尘。\n安得石上泉，漱我耳中喧。",""],["涧水漱幽石，漱之何太勤。\n幽石本贞白，粲粲无缁磷。\n安得山下泉，漱我胸中尘。",""],["群雀下啄泥，仰唤竹间侣。\n竹亦有嘉实，若为相赠许。",""],["冥鹏将图南，去以六月息。\n试问何太迟，物以久而积。\n冥鹏起扶摇，九万一朝极。\n试问何太速，风积有馀力。\n嗟彼蜩鴳徒，枪榆聊自适。\n枪榆不崇朝，孰辨垂天翼。",""],["秋高天宇空，河汉净如澄。\n月华皓无际，亭亭照子行。\n凉风起天末，金石为之鸣。\n回薄西山岑，摇摇吹客旌。\n风以比君清，月以比君明。\n清飙频远播，明照无遗情。",""],["卞和献荆璞，言尽继以泪。\n虽以三刖足，于心曾不悔。\n岂不知保身，徒以识为累。\n楚国有大宝，弃之如瓦块。\n何况以暗投，按剑或相待。\n大易贵藏器，龙蛇亦何害。",""],["秉节降金台，徘徊瞻斗杓。\n斗杓东回旋，北极终不摇。\n下直长安西，三二骨肉交。\n骨肉谁忍割，矧此多危途。\n含凄感悲风，羞作儿女号。\n长弧射天狼，拥彗扫旄头。\n日月会中天，聚首是何朝。\n各自养时晦，慎言思寡尤。",""],["松枝何太高，高可撑青天。\n松根何太深，深可彻黄泉。\n松叶何太繁，繁可庇颠连。\n高以比君节，繁以比君仁。\n深以比君智，宜续甘棠编。\n呜呼如此树，宜种君堂前。",""],["南风起浩荡，吹我德州航。\n黄尘翳白日，白日无辉光。\n顺逆固有数，风伯亦何伤。",""],["万物宇宙间，混沦同一气。\n充塞与流行，其体实无二。\n就中有粲然，即一为万理。\n外此以索万，舍身别求臂。\n逝川及鸢鱼，昭昭已明示。\n我心苟不蔽，安能出于是。\n知止乃有定，动静原非异。\n见之即浑化，是名为大智。\n其次在敬养，敬有为心累。\n勿忘以勿助，其机极简易。\n嗟彼世间儒，憧憧起私意。\n自然本无为，廓之配天地。",""],["壬申仲春尾，问道临清流。\n寒泉汲短绠，新草弥荒洲。\n去鸟历微霭，焉知光景遒。\n感物发长叹，云日令人愁。\n群公递倾盖，所语皆兵筹。\n折冲在千里，虎噬犹未休。\n如闻复内向，独抱杞人忧。\n安得汉骠骑，一鼓清神州。",""],["刺船过东洙，东洙风景奇。\n莫打东洙水，惊我白鸥飞。\n白鸥飞尚可，翠柳鸣黄鹂。",""],["刺船过西崦，西崦风光幽。\n莫唾西崦石，渐近太湖头。\n太湖烟波阔，洞庭渺难收。",""],["少非风尘姿，雅志在丘壑。\n偶从野王舟，春夜太湖泊。\n茆公向我揖，为我举云幕。\n雨后空宇澄，天高极寥廓。\n七十二峰峦，缥缈天际落。\n日短意不穷，更上湖边阁。",""],["陟登千仞冈，超然坐琴台。\n长倚青琅玕，举手望蓬莱。\n不见瑶台月，但见青鸟来。\n弱水几清浅，念之令人哀。",""],["已辞鄂王宫，迢递入天竺。\n鸟道烟萝深，履声落空谷。\n一溪度飞来，泠泠更幽独。\n无为独木桥，于此巢云竹。",""],["乘月步层台，独立倚长塔。\n逍遥望东海，天地归吐纳。\n夜潮殷如雷，涛头雪山立。\n病骨怯虚寒，四月欺缊纳。",""],["迢迢涉江去，江介生凄风。\n涉之将奚为，南湖采芙蓉。\n美人在远道，我心忧忡忡。\n登山足夔魅，蹈海多鱼龙。\n俯仰天地内，去子谁予从。",""],["道经蓬莱馆，溪穷到阳明。\n下看东南峰，苍苍入青冥。\n不诣此真境，焉知匪虚名。\n踧踖步岩石，山高岂无灵。\n子乔不可见，伫立魂屏营。\n草木若有识，欣欣向予荣。\n采之欲谁寄，岁晏难为情。",""],["弭棹小阳头，小有藏春屿。\n隔竹十数家，风日美清渚。\n山木苦未多，空林一鸟语。\n即事岂知幽，浣纱此溪女。",""],["弭棹大阳头，大有藏春坞。\n深林隔尘寰，苍石辨太古。\n岩岫千千重，重重起烟雨。\n疑有蛟龙居，全身应九五。",""],["投暮宿瑞洪，际晓过邬子。\n薄云递轻凉，微雨湿芳沚。\n高帆信天风，断港出湖涘。\n因动江湖思，便欲泛彭蠡。\n遥揖五老峰，汀洲采苹芷。\n乘流直东下，无乃瞬息耳。","投暮宿瑞洪，际晓过邬子。\n薄云递轻凉，微雨湿芳沚。\n高帆信天风，断港出湖涘。\n因动江湖思，便欲泛彭蠡。\n遥揖五老峰，汀洲采蘋芷。\n乘流直东下，无乃瞬息耳。"],["蔼蔼东都季，群公青云器。\n耿耿陈窦心，时违势自踬。\n哲人方龙蛇，沉冥西江汜。\n下榻岂无论，栖栖欲奚俟。\n载诵厦木言，时之用大矣。",""],["严陵卧扶汉，段生偃藩魏。\n古来素业流，沮溺乃救世。\n我拜墓中人，伊人骨已蜕。\n我拜墓前木，此木栋梁器。\n载感厦木言，时之用大矣。",""],["行行十八滩，一滩度一劫。\n劫尽逢水源，平澜见明月。\n踏月逾庾关，于兹是小歇。\n人世多滟滪，寻常互倾灭。\n我身在风涛，阅月百圆缺。\n此事难重陈，重陈五情热。",""],["蛋子何眇眇，自得同水族。\n缓桨荡朝暄，落日依阴谷。\n将舟无远梦，下上清溪曲。\n得失在一鱼，岂识荣与辱。",""],["大妇厌糟糠，中妇足粳粱。\n小妇何绰约，装金调玉浆。\n愁乐各未终，微日落阴冈。",""],["举首望明月，明月沉海中。\n举手招白云，白云游太空。\n白云不可结，明月不可缝。\n揽袂长叹息，星火忽已终。\n安得飞仙子，借我一苍龙。",""],["明月出海东，照入我怀中。\n两手捧怀笑，浮云生我胸。\n移枕见远山，开窗得清风。\n适意非有期，至道末有从。\n蓬莱隔弱水，无力谁能杭。",""],["仰看明月殿，灿灿姮娥居。\n我欲跳身入，飞空骑蟾蜍。\n归来启灵府，中有明月珠。\n佩之当明月，圆光满八区。\n愿扫浮云翳，本来无外须。",""],["曲江江水长，欲济川无梁。\n美人不可即，风度安可量。\n飞鸟择高枝，鸣凤在朝阳。\n黄唐世已远，千载空翱翔。",""],["武溪溪水深，欲往隔云浔。\n美人在何许，风采空遗音。\n忧思满南北，托之被弦琴。\n惟有江门石，可以写我心。",""],["应变意弥定，到寺心颇动。\n泥空乃多修，无事有大用。\n溪行得自身，云卧无尘梦。\n迢遥隔岭钟，风吹过阴洞。",""],["夜宿漕溪边，云深失归径。\n山空白露下，林迥玄风定。\n火轮明东海，魄渊薄西岭。\n举手问两崖，此中是何景。",""],["今夕乃何夕，复与子同携。\n舟楫更相将，灯烛仍交辉。\n念彼旧游地，一落多路岐。\n欲恸杨朱泣，泪下不可挥。\n举首望黄云，太山久已颓。\n哲人不可作，与子其从谁。",""],["哲人久已逝，山水有遗光。\n履地益怀人，况此埋玉乡。\n登山勿采松，采之恐枝伤。\n临水勿汲源，汲之流不长。",""],["夫君有嘉惠，赠我云锦裳。\n中绣自然字，服之永不忘。\n忍着君遗物，为人作新妆。\n酹酒矢心曲，敬进南丰香。",""],["凤凰去不返，万仞空高冈。\n升冈望孤凤，何时复来翔。\n感此笼中鸟，眷彼旷世祥。\n黄唐代已远，五色徒文章。",""],["客子念前路，居人慕岁功。\n舒眸望南荒，林木郁葱葱。\n借问此何时，日度玄枵中。\n落叶靡堕影，来雁无遗踪。\n自非朔风发，何以辨玄冬。\n乃知天地大，因兹穷始终。",""],["青青江蓠草，茫茫隔周道。\n有女携倾筐，采采忽日暮。\n日暮把不盈，持此感春情。\n自君之戍矣，江草八九荣。\n草荣他人赏，孤居益惆怅。\n王孙归不归，春草飞蛾长。",""],["客行卅里滩，款款闻绵蛮。\n声嫩语犹涩，翅新飞且还。\n感我故园念，春来人未旋。\n北雁今已归，南枝久当残。\n归去来山中，春草游王孙。",""],["俗情爱新岁，寒暑运之常。\n常运委我去，感兹翻慨慷。\n慨慷亦奚为，有志不获将。\n悠悠万里道，税驾未有方。\n岂无鬓如丝，那堪补君裳。",""],["人生如浮云，散在天一涯。\n天涯又飘泊，浩荡成离披。\n风吹一朝合，聚会岂有期。\n闲云不出山，奇鱼不离溪。\n行矣归毋迟，春山多紫芝。",""],["癸酉王正月，望舒忽已圆。\n登望凭祥陆，暂辞龙州船。\n杭苇始断港，前旌出回峦。\n隐见万山中，初翳疑无门。\n转忽或有通，上与青空连。\n洒落观群山，芙蓉秀晴烟。\n烟与山俱淡，心与境相关。\n倏然若有得，殊土元同天。",""],["侧径通幽崖，凌风放高躅。\n下有百尺渊，上荫千寻木。\n冷泉漱溪毛，回飙动修竹。\n超然生奇怀，情结清溪曲。\n中有无名禽，于兹媚幽独。","侧径通幽崖，淩风放高躅。\n下有百尺渊，上荫千寻木。\n冷泉漱溪毛，回飙动脩竹。\n超然生奇怀，情结清溪曲。\n中有无名禽，于兹媚幽独。"],["路驰心有往，俗忤气屡发。\n蛮貊苟可行，笃敬功尚缺。\n悠悠卧虚馆，咄咄书空札。\n惕然发深省，揽衣坐㵳泬。\n夜久空宇澄，三籁俱已灭。",""],["鸟鸣客初觉，檐隙光渐发。\n欲起仍迟留，省事心已折。\n哲人夜入梦，遗我一书札。\n恍惚不可读，意了字灭没。\n展转隔幽明，哀歌思盈闼。",""],["峥嵘矻野次，石壁开岩扉。\n山木虽未多，白云暮来归。\n小憩登陟馀，超然生远思。\n凉飙起新霁，高歌递微晖。\n风云一飘散，浩荡本无期。",""],["昔欲访名岩，匪为恣盘游。\n闻有先哲踪，因兹仰前修。\n野云埋古院，光风满层丘。\n伊人不可见，顿令我心忧。\n溪莲有佳实，欲采渺无由。",""],["凤凰阁千仞，九重增城庐。\n城中藏洞府，市上隐悬壶。\n云卧毛骨寒，冥栖心境娱。\n楼堞几席下，群山入窗虚。\n就枕见山色，悠然睇遐墟。\n俯仰宇宙内，此乐复何如。",""],["秋高气初清，云净天宇澄。\n迢遥上危塔，凭虚步青冥。\n仰近北辰次，下看南极星。\n达观众妙理，俯察群动情。\n斯人苦长勤，日夕竞营营。\n惟彼江流水，朝宗去不停。",""],["名刹来何方，幻迹飞青天。\n天光照岩洞，闪烁云霞间。\n云霞散倏忽，上与苍穹连。\n空山无人迹，高鸟暮独还。\n和光本无路，逝水自有澜。\n仲尼久不作，此意谁与言。",""],["嘉筵籍兰若，宿雨清埃氛。\n广宴开云峤，清歌临水滨。\n爱客感贤守，鼓瑟愧嘉宾。\n狎坐飞羽觞，更酬倒琼樽。\n奇怀寄登眺，危塔凌青云。\n舒眸碧海际，浩荡观无垠。\n游目周四野，歌啸声相闻。\n乃知非盘乐，游息至理存。","嘉筵籍兰若，宿雨清埃氛。\n广宴开云峤，清歌临水滨。\n爱客感贤守，鼓瑟愧嘉宾。\n狎坐飞羽觞，更酬倒琼樽。\n奇怀寄登眺，危塔淩青云。\n舒眸碧海际，浩荡观无垠。\n游目周四野，歌啸声相闻。\n乃知非盘乐，游息至理存。"],["青山拥高台，新亭何翼然。\n长桥卧寒波，清池汇门前。\n筑者吴季子，伯夷所鸠僝。\n江湖孰云远，覆帱同一天。\n旭日下亭阶，顿首重致言。\n愿垂中天照，蔀屋见颠连。\n我欲将此屋，化作千万间。\n遍庇逃亡者，圣仁覆人寰。",""],["漫天雪霏霏，遍地生寒威。\n一方寒可逃，漫天将安违。\n仆夫寒吁天，天若不闻知。\n天普而无为，羲和愆其期。\n三旬竟不返，阳道亦孔微。\n将匪羲和愆，云雨有常师。\n彼哉胡不仁，亦已焉乎而。",""],["伊昔垂髫年，逢岁辄欢喜。\n喜欢将何如，数日仍屈指。\n事与年侵寻，世网固缠己。\n物态迁性情，感节悲怀起。\n四序恒不居，天地有剥否。\n眇兹血气躯，神理会颓圮。\n四大非我物，安能保妻子。\n骨肉尚不顾，官爵宁久恃。\n困鱼乐深渊，龌龊思脱屣。\n何当凌高风，采薇西山趾。","伊昔垂髫年，逢岁辄欢喜。\n喜欢将何如，数日仍屈指。\n事与年侵寻，世网固缠己。\n物态迁性情，感节悲怀起。\n四序恒不居，天地有剥否。\n眇兹血气躯，神理会颓圮。\n四大非我物，安能保妻子。\n骨肉尚不顾，官爵宁久恃。\n困鱼乐深渊，龌龊思脱屣。\n何当淩高风，采薇西山趾。"],["尹铎轻茧丝，冯驩毁券钱。\n汲公置焚斗，矫诏赈饥氓。\n火辰僣天纪，木德受其燔。\n遂令山岳赭，转使民物烦。\n民物烦以冤，号声迸高旻。\n时当云雷屯，经纶在群贤。\n子今万里去，衣佩何翩翩。\n燕雀尚堂室，溟鹏薄云天。\n形影日以远，思子心凄然。\n荆楚多遗迹，问俗重延缘。\n倘然得一木，能支大厦颠。","尹铎轻茧丝，冯驩燬券钱。\n汲公置焚斗，矫诏赈饥氓。\n火辰僣天纪，木德受其燔。\n遂令山岳赭，转使民物烦。\n民物烦以冤，号声迸高旻。\n时当云雷屯，经纶在群贤。\n子今万里去，衣佩何翩翩。\n燕雀尚堂室，溟鹏薄云天。\n形影日以远，思子心凄然。\n荆楚多遗迹，问俗重延缘。\n倘然得一木，能支大厦颠。"],["晓出兰溪门，逍遥望名山。\n望之已可爱，而况游其间。\n窈窕藏境胜，夷旷令心闲。\n白云昼冥冥，溪流日珊珊。\n不见牧羊子，化石只依然。\n心迹俱寂寞，怅望未能还。","晓出兰溪门，逍遥望名山。\n望之已可爱，而况游其间。\n窈窕藏境胜，夷旷令心閒。\n白云昼冥冥，溪流日珊珊。\n不见牧羊子，化石只依然。\n心迹俱寂寞，怅望未能还。"],["高堂今宴会，明日就泥途。\n保命欲骞举，忘身在网虞。\n涉江防滟滪，即陆愁崎岖。\n嗟予将安之，平地成险阻。",""],["白夫广文杰，访我黄金台。\n苦意协管律，雅颂厘清吹。\n音乐缺已久，闻此喜且疑。\n未理金石奏，八音安可裁。\n声本起于无，谁解穷往来。\n鱼马诚异类，感应何神哉。\n乃知太和气，不谢嶰谷材。\n圣人假物用，八风谁能回。\n此可悟神理，当与西山推。","白夫广文杰，访我黄金台。\n苦意协管律，雅颂釐清吹。\n音乐缺已久，闻此喜且疑。\n未理金石奏，八音安可裁。\n声本起于无，谁解穷往来。\n鱼马诚异类，感应何神哉。\n乃知太和气，不谢嶰谷材。\n圣人假物用，八风谁能回。\n此可悟神理，当与西山推。"],["玉台有名果，成之三千春。\n当其未成时，凡品不足珍。\n持以赠世人，涩口反见嗔。\n白璧按剑起，青蝇止棘频。\n圣人诫囊括，明哲贵保身。\n云龙会有时，感应岂无因。\n不惜知音寡，所惜不能琴。",""],["弱龄尘外志，点也与为徒。\n微尚夙所敦，俛仰一纪馀。\n伤哉力不竞，沦落在泥涂。\n中夜起兴叹，揽衣步前除。\n咎己有馀裕，尤人尚忧虞。\n行年四十九，将与伯玉俱。\n知非在今始，言为知者摅。",""],["凤鸟旷世出，一鸣三千年。\n寥寥抱真士，韬光自委身。\n我慕牛医子，沈冥以不言。\n之子小江秀，翩翩五陵间。\n家学存令德，发愤追前贤。\n夙昔游文艺，于今溯真源。\n努力同爱日，日月如奔川。",""],["昔于阳明子，邂逅初见君。\n初见意气合，稍亲直谅闻。\n中途遭屯厄，彼此各风尘。\n处坎心以亨，委顺道固存。\n晤言惬心赏，盛德观日新。\n遇利若阻梗，逐义如转轮。\n逊志乃有获，过化惟存神。",""],["送子出崇文，崇文日照人。\n朔风卷长陌，登高临水滨。\n河梁一抗手，孤影随形分。\n形分瞩望眼，望绝继以音。\n所愿崇明德，酬此百年身。\n易简理斯得，超诣在忘言。\n溟鹏具大翼，九万待风骞。",""],["下马东陵道，北风漫浩浩。\n举手拂尘翳，超然见穹昊。\n极目望泱茫，王气郁苍苍。\n地高逼象纬，彩云浮建章。\n群后圣以神，穆穆格明禋。\n虎豹开九关，六龙驭众真。\n衣冠翕然会，小臣亦骏奔。\n皇图愿永固，天寿同无垠。",""],["朔风吹广陌，回合野晴微。\n我马亦已瘏，与君同驱驰。\n驱驰竟何适，无事信多岐。\n道胜境斯惬，情旷途自夷。\n况与三益友，同行得所师。\n共励凌风节，勿使愿相违。","朔风吹广陌，回合野晴微。\n我马亦已瘏，与君同驱驰。\n驱驰竟何适，无事信多岐。\n道胜境斯惬，情旷途自夷。\n况与三益友，同行得所师。\n共励淩风节，勿使愿相违。"],["萍生无根蒂，聚散故不常。\n结缔水中荇，牵引随波浪。\n荇性有本根，行子念故乡。\n忆昔与子别，八九度星霜。\n誓同鸿与雁，北徂以随阳。\n一息在天涯，万里永相望。\n昨日寄书至，两载病喉疮。\n令我中情热，矧子讵能忘。\n别长苦会短，子独去踉蹡。\n岂无儿女情，歌竟长慨慷。",""],["溪莲水晶秀，结子心独苦。\n抚己良自惜，不若忘忧草。\n昨忻菽水欢，今病心如捣。\n肺肝倘可疗，岂但慕割股。\n肝肺亦已摧，安得悲速老。\n老态发日逼，发白心转赤。\n暮暮与朝朝，左右进药食。\n食苦谁能甘，食甘谁能释。\n视膳古为孝，一气共忻戚。\n何日上高堂，彩衣奉颜色。",""],["晓雨净炎氛，疏云霭朝阳。\n与子誓言迈，肩舆鸣相将。\n山花向人笑，好鸟翱还翔。\n景物虽可乐，悲怀翻感伤。\n引望埋玉处，白云起荷塘。\n墓草忽已青，岁序易炎凉。\n感君絮酒意，中心讵能忘。",""],["新晴天气佳，轻波动微曛。\n被蒙君子顾，画船联海滨。\n小堂高宴会，海错亦前陈。\n一笑群忧馀，六载此倾樽。\n泛艇小瀛外，虚阁凌青云。\n舒怀共远眺，聊用慰良辰。","新晴天气佳，轻波动微曛。\n被蒙君子顾，画船联海滨。\n小堂高宴会，海错亦前陈。\n一笑群忧馀，六载此倾樽。\n泛艇小瀛外，虚阁淩青云。\n舒怀共远眺，聊用慰良辰。"],["客舟何悠悠，来自天际头。\n水荇动微飙，旭日孤帆收。\n云是樗里子，薄言与同游。\n维南有嘉木，好鸟时相求。\n对此终日夕，聊以忘吾忧。\n未应小瀛月，虚系荡湖舟。",""],["峥嵘起孤根，四面迥无隣。\n云是文溪筑，当作李公墩。\n屹立彼中流，以墩肖于人。\n废兴无定主，此事亦迷沦。\n万物理固然，自馀何纷纷。\n瞻像绕三匝，感慨复何言。\n藤萝附高木，得意干青云。\n惟有夕阳鸦，江水自冬春。",""],["伐鼓以宵征，寥寥进所如。\n夕挂穗城帆，旦梦黄云墟。\n畏途发戒心，志在故欢愉。\n迢递遵回岸，逍遥度广渚。\n秋波漾溪毛，晓云映毁规。\n悠然见远𪩘，一鸟入丛株。\n西樵招隐地，未可先吾师。","伐鼓以宵征，寥寥进所如。\n夕挂穗城帆，旦梦黄云墟。\n畏途发戒心，志在故欢愉。\n迢递遵回岸，逍遥度广渚。\n秋波漾溪毛，晓云映燬规。\n悠然见远巘，一鸟入丛株。\n西樵招隐地，未可先吾师。"],["十年两系艇，几度还登楼。\n楼前餐果核，长树与楼头。\n日午下疏阴，横塘门径幽。\n彼树乃如此，令人生百忧。\n废兴递相寻，今古共悠悠。\n寂寞孤舟夜，潇条虚柝秋。\n满天灿星月，渺渺银河收。\n哲人嘉会地，不废长江流。",""],["瑟瑟秋风肃，霜高草木黄。\n物情何所迫，嗷嗷雁南翔。\n美人别云浦，相忆泪浪浪。\n天地有尽期，炎飙变为凉。\n贤哲皆有死，谁为金石刚。\n念昔我夫子，乘云归帝乡。\n迢迢十八载，望之云路长。\n俯仰松下土，安得不为伤。",""],["旦从故人宴，洒落坐高轩。\n一为风水别，中阻荒洲壖。\n起视迷四野，相忆夜漫漫。\n青蝇附马尾，利钝故随人。\n贞女托所天，忧乐由夫君。\n总为物所误，中立无缠牵。\n缠牵累千里，万事理固然。\n因兹悟至道，与君同勉旃。",""],["皂帽何处峰，青天敛芙蓉。\n屼峍昆仑顶，窈窕蓬莱宫。\n本自同大块，精气有所钟。\n洒落看诸山，诸山赴海同。\n群峰与万壑，拱揖如朝宗。\n壁立千万仞，凤凰翔高风。\n于兹拟埋玉，可以配我公。\n二纪犹此劫，五百隐奇踪。\n一朝迥神异，冀北马群空。",""],["方子石泉卜，廿年吾意中。\n风尘坐迟暮，高锡未凌风。\n我卜异于是，烟霞与尔同。\n碧云与云端，一以寄幽踪。\n且不离烟火，兼可巢筠松。\n居僯有二仲，或得共游从。","方子石泉卜，廿年吾意中。\n风尘坐迟暮，高锡未淩风。\n我卜异于是，烟霞与尔同。\n碧云与云端，一以寄幽踪。\n且不离烟火，兼可巢筠松。\n居僯有二仲，或得共游从。"],["秋深天气肃，雨馀亭馆凉。\n逍遥登梵阁，寂寞坐僧房。\n地高天宇空，云露沾衣裳。\n虚磬发林杪，传灯泛云光。\n端居疑寂灭，感节故悲伤。\n色空云同体，根尘何必忘。",""],["我庐在烟霞，逍遥出云端。\n天空鸟道绝，江迥柴门闲。\n翩翩者谁子，放歌来叩关。\n昔为青衿彦，今为入幕贤。\n手持纲成策，爽气凌高寒。","我庐在烟霞，逍遥出云端。\n天空鸟道绝，江迥柴门閒。\n翩翩者谁子，放歌来叩关。\n昔为青衿彦，今为入幕贤。\n手持纲成策，爽气淩高寒。"],["邓生或清者，爱我泉边石。\n若无愧此泉，许尔坐泉侧。",""],["君恪慕晦者，晦名在烟霞。\n知是素心人，宜住洞西家。",""],["双泉驾群峰，大科乃泉窦。\n科比泉高卑，已过十八九。\n碧云与紫姑，无乃科麓乎。\n是为第一峰，斯名岂云诬。",""],["大科樵中尊，双泉在科南。\n泉比科上下，已过十二三。\n宝鸭与双鱼，无乃流之馀。\n是为第一泉，斯名讵云虚。",""],["戴星出西樵，见月望三水。\n愁愆美人期，君命恐不俟。\n朔风吹船头，寒沙啮船趾。\n开蓬瞻停云，未忍中道已。","戴星出西樵，见月望三水。\n愁愆美人期，君命恐不俟。\n朔风吹船头，寒沙齧船趾。\n开蓬瞻停云，未忍中道已。"],["厥明泊水涯，楼船来未来。\n舍舟步曲岸，登高望所怀。\n所怀久不至，渺渺令人猜。\n自古难前期，人事多好乖。",""],["稍稍将船去，倏尔度三辰。\n朝去暮知还，多愧山中云。",""],["将船中夜归，潮到翳门溪。\n孤帆背月收，白云还满衣。",""],["东行度龙溪，遵岭北而西。\n回望烟霞洞，中居控四维。\n前得垂虹泉，珊珊落云端。\n壁立如斩削，鸟道孤岩悬。\n于兹宜揽结，或可作小歇。\n洗耳与枕流，长以师峻洁。",""],["圣人亦人为，诸子早辨志。\n持此忠信资，何远不可至。\n尧舜称大圣，其道孝弟耳。\n孝弟谁不然，鲜或见天理。\n天理天所为，超然绝人伪。\n夫谁能举之，聪明与睿智。\n兹理何由臻，执事自敬始。",""],["丁丑孟冬吉，湛子辟烟霞。\n虽非鹿门胜，亦携庞公家。\n乃开正义堂，乃建崇经楼。\n乐阁在堂前，茹芝在楼头。\n有亭面西壁，丽泽双泉北。\n退轩后洞居，峻洁垂虹侧。\n亦或考金钟，亦或击石鼓。\n前抚卧龙吟，后引九龙舞。\n七曜明天经，三水察地理。\n俯仰参两间，其道一而已。",""],["石泉在樵东，烟霞在樵西。\n同家宇宙内，况复同藩篱。\n若欲散沈郁，登高以眺遐。\n方子于斯时，不弃来烟霞。\n若欲翕发散，入谷听潺湲。\n湛子于斯时，不厌过石泉。\n春暮方发育，石泉颇幽独。\n万水与千山，烟霞堪寓目。\n秋冬美朝暾，烟霞颇高寒。\n晞发与炙背，石泉宜借眠。\n绕泉为盘阻，谁复争子所。\n伏虎与盘龙，呵禁乎不可。\n诸子游大科，亦须从大路。\n有或非吾徒，攻之以石鼓。",""],["有客晨叩门，劝我浚新泉。\n适当连雨天，工暇土脉匀。\n发石玉已喷，除壤榻自陈。\n布列象斗极，可以坐七贤。\n尹公几中尊，次左湛子焉。\n邓子居右方，方君左临渊。\n甘也接邓膝，南上秩有伦。\n馀二若有待，不备惟其人。\n清如此泉者，来居无厚颜。",""],["九龙樵三昧，竹台在九曲。\n岩与台近隣，相看爱无俗。\n根根一根同，曷以多为喜。\n此君正耻独，绕台是君子。",""],["南山有隐豹，十日雾雨中。\n惄焉忍长饥，引项吸天风。\n蟠家曲树底，甘以矢自终。\n不啖人间食，卓为汉士雄。\n故人扣我关，舒啸凭高峰。\n六夕烟霞里，浮云迷去踪。",""],["世有好直者，直行悲途穷。\n直视不仰天，直立不俯躬。\n若有用直者，如绳无曲木。\n如弦有高音，如矢利于镞。\n或有徒直者，心不藏丝毫。\n与人无可否，于物忘卑高。\n我直异于是，用一而化二。\n生理本不回，修之敬为地。",""],["片帆出扶胥，潮打虎门开。\n正爱远山青，白鸟闲飞来。","片帆出扶胥，潮打虎门开。\n正爱远山青，白鸟閒飞来。"],["举手望飞云，鸣桡过黄木。\n舣舟江上亭，虚空观日浴。",""],["抱病烟霞居，与世日相遐。\n不见交亲至，惟见白云过。\n孟夏风云会，送子来大科。\n洞门修且深，窈窕入烟萝。\n群彦翕然集，宴饮酣且歌。\n警发同文会，言笑靡及他。\n岂无欲君意，未敢言琢磨。\n不谓即言旋，白云如子何。\n贱躯因晨风，饯子山之阿。",""],["吾爱蘧伯玉，五十能知非。\n吾慕卫武公，耄期不忘规。\n芳名垂典训，百世诚吾师。\n嗟彼夸毗子，沾沾自满攲。\n隙光讵全照，掩鉴犹蔽亏。\n井蛙不知天，瓮里蒙醯鸡。\n日月普空宇，万物含光辉。\n高明与广大，临照无隐微。\n圣哲崇弘毅，小器非大知。\n全功在知性，尽心乃不遗。","吾爱蘧伯玉，五十能知非。\n吾慕卫武公，耄期不忘规。\n芳名垂典训，百世诚吾师。\n嗟彼誇毗子，沾沾自满攲。\n隙光讵全照，掩鉴犹蔽亏。\n井蛙不知天，瓮里蒙醯鸡。\n日月普空宇，万物含光辉。\n高明与广大，临照无隐微。\n圣哲崇弘毅，小器非大知。\n全功在知性，尽心乃不遗。"],["送子翳门关，上上官山渡。\n自渡还自济，千圣同大道。\n下樵苦不难，上樵苦不早。\n有形岂不滞，出入更如主。\n短景倏如流，永怀岁将暮。\n且莫笑杨朱，杨朱泣岐路。",""],["有客来烟霞，告我游燕北。\n送子以愁心，徘徊瞻斗极。",""],["采采篱内花，少间复耻独。\n采之欲何为，幽香难入俗。\n吾衰虑芳歇，岁晏日不足。\n薄言采群芳，天地归一掬。\n霜高草木黄，孤秀媚空谷。\n自非金刚姿，孰致后凋曲。\n圣人贵松柏，卫风咏菉竹。\n爱此柴桑操，纳尔于大麓。\n登高发雅颂，被之三尺木。\n手弄无弦君，眦决飞鸿目。\n谁能继此曲，此曲情何极。\n顾谓二三子，菁莪歌乐育。\n一育草木蕃，永言自求福。\n我福在百顺，神不疾而速。\n四时自运行，天道尚往复。\n怀人倘不遐，吾以献芹曝。",""],["有鸟振奇羽，周游隘八区。\n嗟彼抢榆翅，一枝徒自娱。\n素啄秋江水，今将睨天池。\n偶值云端树，况是千寻枝。\n积风负大翼，殊量非小知。\n语君九万程，君志定何如。",""],["白云满空山，山在白云里。\n心若似云闲，与君同睡此。","白云满空山，山在白云里。\n心若似云閒，与君同睡此。"],["嗟予语敬之，敬之当听予。\n敬亦无不在，语子敬读书。\n当其未读时，天君自俨如。\n及其对书册，万象涵太虚。\n是谓以我观，勿以此丧志。\n舍之求放心，离物以为二。\n学问与思辨，古训乃其地。\n无在无不在，事事亦如是。",""],["大学崇至善，格物为实地。\n格者意身心，是谓至其理。\n如彼之国都，亲见乃知至。\n平地说相轮，伯淳所以耻。\n格之厥功何，知行并时诣。\n终日及终身，惟此一大事。\n何为齐治平，即前物理是。\n万一本同原，体用元非二。\n道丧千载馀，支离为简易。\n谁能一扫之，敢以告吾子。",""],["陈生古梅秀，三载拜小瀛。\n访予避地处，远扣烟霞扃。\n云栖百尺阁，明月几亏盈。\n经始开书院，置田赡诸生。\n冷淡世人笑，在古或垂名。\n咄咄夸此子，睚眦愤所争。\n持此赠之归，以为乡里荣。",""],["故人莲峰子，约我到罗浮。\n罗浮众仙人，伫望大石楼。\n缥缈度飞云，超然见丹丘。\n自我小蓬瀛，可以至十洲。\n试问莲峰子，与我烟霞不。",""],["东山众东山，爱之即我有。\n若然不知爱，其土等培𪣻。\n宣尼曾一登，聊以小东鲁。\n因君感吾心，吾将随步武。","东山众东山，爱之即我有。\n若然不知爱，其土等培塿。\n宣尼曾一登，聊以小东鲁。\n因君感吾心，吾将随步武。"],["秋菊已可爱，况复当高轩。\n坐轩对新菊，南山见悠然。\n此景世间有，所恨难其人。\n何期闹市中，聊复见蒋君。\n可是元卿裔，三径开白云。\n菊吾甚爱之，借轩闲一眠。","秋菊已可爱，况复当高轩。\n坐轩对新菊，南山见悠然。\n此景世间有，所恨难其人。\n何期闹市中，聊复见蒋君。\n可是元卿裔，三径开白云。\n菊吾甚爱之，借轩閒一眠。"],["谁为开湛泉，先得吾姓号。\n知是爱泉人，可与结心素。\n移居近泉头，对之心益幽。\n因达虚明体，于以长泳游。",""],["里奚非智士，公奇为忠臣。\n何期数载下，共沐新主恩。\n入疆问贤守，高宴具前陈。\n忧馀发孤笑，痛定说酸辛。\n晴祠拜舜日，愤惋吊荒坟。\n愿持精一学，献之重瞳君。",""],["我爱东山高，东山有佳色。\n匪爱东山色，中有幽人宅。\n昔为谢公居，今下董子帏。\n丈人日夕往，斑衣此儿戏。\n郎今侍仙府，寿以金茎露。\n丈人进一杯，我为一歌侑。\n歌竟将若何，为祝东山寿。",""],["有子骑青骢，青骢何桓桓。\n我马愧不如，谁马气如云。\n下马为拜之，因以知其人。\n若人抱忠孝，君家有严君。\n再试乃卷怀，临世濯垢氛。\n我欲从紫霞，遨游于无垠。\n聊用谢短世，永以寿千春。",""],["孤石已可爱，况复双嶙峋。\n物情无美恶，损益在所任。\n一以砺吾行，一以砺吾心。\n砺行得人钦，砺心得神歆。\n神人既两协，为谢他山吟。",""],["戴君工垂佐，业出石镜阴。\n邂逅道知素，因忆齐云岑。\n国计赴留司，若过桑梓林。\n为予借石镜，可照万古心。",""],["鸿胪出尚方，飘飘下五云。\n踟蹰即长路，瞻恋犹枫宸。\n朱光发大夏，长养同维新。\n阳刚尚微郁，阴姤讵能沦。\n两都景不殊，欣戚齐疏亲。\n斗杓解斟酌，羲和无停轮。\n谁能回元气，祈此万年春。",""],["君家在宝潭，潭中有真源。\n若欲求至宝，更窥九层渊。",""],["翩翩毗陵子，浴德璧水涯。\n十年不入官，藏器以待时。\n四海仰明圣，天运转璇玑。\n遐不共帝臣，之子亦来归。\n观光五云里，际会千载期。\n阳德会光大，阴霭尚朝曦。\n时事异厝薪，凤凰亚鸡栖。\n献璞或见刖，按剑专相疑。\n苍苍阳羡峰，微微江月晖。\n送子归山中，山中多蕨薇。","翩翩毗陵子，浴德璧水涯。\n十年不入官，藏器以待时。\n四海仰明圣，天运转璿玑。\n遐不共帝臣，之子亦来归。\n观光五云里，际会千载期。\n阳德会光大，阴霭尚朝曦。\n时事异厝薪，凤凰亚鸡栖。\n献璞或见刖，按剑专相疑。\n苍苍阳羡峰，微微江月晖。\n送子归山中，山中多蕨薇。"],["岳顶亦松耳，托根故不同。\n遂为人所慕，拟置幽亭中。\n得之亭益幽，浩浩生高风。\n若有抚松人，等视无卑崇。",""],["番山一时秀，君才似杨修。\n况当机云年，文价迈等流。\n双双矫云翼，意气隘九州。\n中年一垂翅，抢彼枳棘休。\n列第太常右，交辉花萼楼。\n鹦鹉诉北寒，越鸟思南游。\n法星化奎文，一夜光芒浮。\n我有停云念，岂无看云愁。\n南宫省署静，文苑开清修。\n六朝佳丽景，楚尾与吴头。\n我祖膺戎狄，山河为增优。\n夫何根本地，犹有兵食忧。\n大风拔陵木，江涨浮尸游。\n今年灾疫仍，千室无人收。\n频下修省诏，悔祸天启谋。\n此当属春官，送子发长讴。\n若有南征赋，可以献纳不。",""],["佩玉身若槁，志在朱陵天。\n襟怀全楚阔，胸荡洞庭烟。\n使君乘别驾，冠盖何翩翩。\n去问常德俗，令我心飘然。\n圣师问得人，澹台部下贤。\n身心是公事，何烦入室焉。\n若访蒋生径，宁无切琢言。",""],["少师群伦表，朗豁夙天人。\n骥驹已超类，岐嶷与岳嶟。\n蔼蔼文苑秀，皇皇秉丝纶。\n垂翅权奸际，云雷见居屯。\n藏纳似梁公，龙蛇十六春。\n贤者固叵测，终复唐乾坤。\n我师富才力，张弛在北辰。\n浊河上滔天，清济中不浑。\n先皇幸南北，留后报主身。\n时与三二公，内外协同寅。\n旄头出东南，帷幄坐清尘。\n深忧在心腹，岂但宁与彬。\n城社杀狐鼠，事势岂易论。\n及乎抱弓泣，危疑难重陈。\n寅夜定大策，翊运扶紫宸。\n圣人御皇极，正诏下高旻。\n积弊一旦革，大礼无前因。\n众论正嚣嚣，国狗亦狺狺。\n处人骨肉间，两宫恩义均。\n自非中理解，谁能定逡巡。\n天子曰劳止，策勋命谆谆。\n三让不拜封，世禄控亦频。\n天子自仁孝，手敕加私亲。\n从容对数语，封纳了不嗔。\n自馀一召对，侃侃复訚訚。\n帝亦为之慰，格君可渐臻。\n公方论年秩，闭门解朝绅。\n帝命加太傅，赐宴倍臣隣。\n三四获所辞，乃饮春官醇。\n皋夔皆赓歌，殊锡感明禋。\n此日是何日，重阳更越旬。\n寔维公华诞，岳降生甫申。\n福德代不数，无乃天逸麟。\n天寿且平格，周召古所伦。\n永命在祈天，国脉亦以新。\n维时贺宾至，公醉在帝𬮱。\n贵介盛珠屦，所宝惟贤仁。\n狄门多桃李，宁无入幕宾。\n水也则狂简，滥竽亦效颦。\n敬赋南山诗，万寿祝无垠。","少师群伦表，朗豁夙天人。\n骥驹已超类，岐嶷与岳嶟。\n蔼蔼文苑秀，皇皇秉丝纶。\n垂翅权奸际，云雷见居屯。\n藏纳似梁公，龙蛇十六春。\n贤者固叵测，终复唐乾坤。\n我师富才力，张弛在北辰。\n浊河上滔天，清济中不浑。\n先皇幸南北，留后报主身。\n时与三二公，内外协同寅。\n旄头出东南，帷幄坐清尘。\n深忧在心腹，岂但宁与彬。\n城社杀狐鼠，事势岂易论。\n及乎抱弓泣，危疑难重陈。\n寅夜定大策，翊运扶紫宸。\n圣人御皇极，正诏下高旻。\n积弊一旦革，大礼无前因。\n众论正嚣嚣，国狗亦狺狺。\n处人骨肉间，两宫恩义均。\n自非中理解，谁能定逡巡。\n天子曰劳止，策勋命谆谆。\n三让不拜封，世禄控亦频。\n天子自仁孝，手敕加私亲。\n从容对数语，封纳了不嗔。\n自馀一召对，侃侃复訚訚。\n帝亦为之慰，格君可渐臻。\n公方论年秩，闭门解朝绅。\n帝命加太傅，赐宴倍臣隣。\n三四获所辞，乃饮春官醇。\n皋夔皆赓歌，殊锡感明禋。\n此日是何日，重阳更越旬。\n寔维公华诞，岳降生甫申。\n福德代不数，无乃天逸麟。\n天寿且平格，周召古所伦。\n永命在祈天，国脉亦以新。\n维时贺宾至，公醉在帝闉。\n贵介盛珠屦，所宝惟贤仁。\n狄门多桃李，宁无入幕宾。\n水也则狂简，滥竽亦效颦。\n敬赋南山诗，万寿祝无垠。"],["司寇东湖公，文学饰吏治。\n凤毛两翀霄，乘骢乃仲氏。\n从予拜乞言，服之为砭剂。\n予久拙言词，感君故来义。\n请从文厚言，静重如厚地。\n卓哉万仞冈，壁立不可比。\n青天何昭昭，白日靡霞翳。\n雷霆迅奋击，去来复何意。\n流水与行云，浩荡行无事。\n物情有常则，君行为君记。",""],["名玉方在璞，隐隐含辉光。\n不有卞和子，忽焉终韫藏。\n物情有感遇，世岂无明良。\n胡为抱之泣，徒尔重自伤。\n李君温如玉，独负圭璧章。\n我乃他山石，磨琢以相望。\n进思正斋居，君已谢奉常。\n局促笼中鸟，插翅慕云翔。\n金华为益高，浙水为益长。\n玉尔明德躯，慰我金石肠。",""],["杞人忧天亏，共工怒地缺。\n天地且反复，人事何足说。\n物理故不齐，人乎天使之。\n天人莫之致，此咎将安归。\n大易贵时义，蠖屈乃求伸。\n危言亦何为，祇以危其身。\n去矣勿复道，龙德在存神。","杞人忧天亏，共工怒地缺。\n天地且反覆，人事何足说。\n物理故不齐，人乎天使之。\n天人莫之致，此咎将安归。\n大易贵时义，蠖屈乃求伸。\n危言亦何为，祇以危其身。\n去矣勿复道，龙德在存神。"],["澧州吾旧契，于子为姻㜕。\n况尔朴茂资，古道期跻攀。\n兹将牧如皋，令我心惕然。\n已闻江南北，饿殍盈郊阡。\n静坤为屡震，干玑失常旋。\n狐死兔且悲，骨肉相啖残。\n死者未掩骼，生者留孤孱。\n古人尚平格，三极谁复论。\n调燮自一邑，以为诸牧先。","澧州吾旧契，于子为姻㜕。\n况尔朴茂资，古道期跻攀。\n兹将牧如皋，令我心惕然。\n已闻江南北，饿殍盈郊阡。\n静坤为屡震，乾玑失常旋。\n狐死兔且悲，骨肉相啖残。\n死者未掩骼，生者留孤孱。\n古人尚平格，三极谁复论。\n调燮自一邑，以为诸牧先。"],["沿流及汶上，问是古中都。\n宣尼有流化，男女别行途。\n有堂表思圣，遗准存圣模。\n治者平偏党，学以平卑高。\n扩之遂相鲁，东周其庶乎。\n水也未升堂，入室安可图。\n寄语都人士，希圣无自诬。",""],["悠悠宇宙内，斯人独长勤。\n谁立万古心，所赖大圣人。\n六籍开知见，耳目长得新。\n元气岂岳降，此地传绂麟。\n佳气远弥蔼，况乃亲炙存。\n杏坛沛时雨，高弟集如云。\n当时侍讲席，所志皆求仁。\n仁也人心耳，五十何无闻。\n稽首奠心曲，诱衷希圣神。",""],["吾闻青精鸟，鸣则有大水。\n列之在旌旗，为世智者耻。",""],["鸲鹆学人言，翻能避罗网。\n人迷祸福途，徒居万物上。",""],["宇宙何寥邈，造化苦长勤。\n绵绵初生条，倏忽摧为薪。\n采薪须采枝，采薪休采根。\n枝伤可复生，根蹶难为春。\n牛山既濯矣，乃尚寻斧斤。\n斧斤亦易缺，生理亦易灭。\n畴若予草木，帝咨益重烈。\n往谐周虞衡，咸若夏鱼鳖。\n尽物斯尽人，性分在调燮。",""],["皇穹尚不宰，阴阳运时功。\n所以乾坤尊，六子代有终。\n蔼蔼贤少宰，庐山起高踪。\n昔为翰苑秀，于今代天工。\n词华照青阳，玉色倾群公。\n扬历遍台省，文武兼折冲。\n报政趍当宁，新春向和融。\n留都盛冠盖，出饯江之东。\n江花发文藻，江水鉴清容。\n行矣无迟迟，宵旰正重瞳。",""],["飞挽地僵仆，海运天翻波。\n圣皇制国计，全功在漕河。\n河水亦有竭，民力岂云多。\n榜卒晨告痡，及暮靡啸歌。\n妻孥终岁别，生死在网罗。\n去年千里赤，十室九蓬科。\n骨肉且相食，他人将若何。\n根蠹花不实，生理宁有他。\n君子秉明德，调剂使平和。\n干禄有恺悌，刚柔无僣差。\n如何民物遂，国祚同无涯。",""],["峨峨定山尊，苍苍出云里。\n望之不可即，盈盈隔江水。\n何以爱此山，爱此山中云。\n涔涔不成雨，念之徒伤神。\n定山不可见，得见西峰子。\n爱之若定山，聊以慰予意。\n之子度江去，渺然一苇杭。\n登高赋将归，于以写不忘。",""],["暂辞太仆马，采药归武夷。\n武夷多异人，九曲或见之。\n若逢云谷老，为予重致辞。\n精一事久旷，千载空尔为。",""],["泠泠淮浦水，水清人亦清。\n有客来照影，浩然歌濯缨。\n岂但可濯缨，坐使心神澄。\n无穷川上意，日夜注沧溟。",""],["广宴开钟阜，群彦集瀛洲。\n新晴美朝晖，重阴豁然收。\n主人爱敬客，感格天与谋。\n八榻依云列，眇予岂其俦。\n因思竹林会，当时亦何修。\n醉心以明德，岂伊杯酒酬。",""],["吾慕朱修撰，持敬终不破。\n千载仰其人，庶以警予情。\n蔼蔼玉峰子，云间一硕果。\n大华谢雕镌，至性本无作。\n桃李自成蹊，此言可喻大。\n默默太宰公，恭敬倾四座。",""],["清献本狷介，琴鹤适相随。\n峻洁殊绝俗，家风君独追。\n昔予与宗伯，内馆日徘徊。\n因兹契衷素，卓然出风埃。\n何其廿载下，共把金陵杯。\n杯到莫停手，有诏行当回。",""],["翩翩李供奉，世号谪仙人。\n帝赍锦绣襟，笔下如有神。\n明公泰山秀，鼎甲自宸遴。\n不薄南国游，渺渺江东云。\n玉堂忝嘉会，律转物华新。\n再枉琼瑶篇，涤我胸中尘。",""],["太常抱荆璞，肮脏尝遗荣。\n拜诏感明主，买舟扬越行。\n虚疑是何逊，吟笑春风生。\n寄怀托秋奕，远心在沉溟。\n清修我所师，维以咏周行。\n今夕同嘉宴，欲子子心明。",""],["当时李郭舟，望者如登仙。\n君家在瀛洲，君知然不然。\n我本南溟客，家住增城巅。\n凡骨久未蜕，阴功六十年。\n感子琼浆酌，报以金石言。\n神理各保爱，逝水趋东川。",""],["三吴多秀士，藉藉皆贤豪。\n元方与季方，雅获一臂交。\n昔联翰苑辔，今共璧水游。\n季冬木叶脱，已见新萌抽。\n群公修胜会，德言亦交酬。\n敬赋无衣篇，誓与子同仇。",""],["兹辰风日佳，秋空极寥廓。\n四美翕然臻，群英亦趋约。\n结集逍遥游，临江更登阁。\n阁迥江不流，澄心坐超脱。\n高歌饯嘉宾，遗响天际落。\n展足贵千里，去去崇明德。",""],["翩翩一朱鸟，毓德祝融丘。\n羽映五云色，将母来神州。\n亦有游子衣，慈母手中线。\n何如京兆君，日日侍亲膳。\n天子至仁孝，诏许扶亲归。\n亲欢日不足，皇命有程期。\n直知归荣欢，勿言别时苦。\n我歌北山诗，子为彩衣舞。",""],["昔行长千里，欣然得贞幽。\n斋分金屋色，门带玉河流。\n中有天曹星，光照闽海陬。\n丈夫抱经济，及时展才猷。\n手挹上林春，去播薇垣秋。",""],["朱光正中天，阳和倏南流。\n行迈越万里，山川何阻修。\n长风负大翼，六月须云游。\n遐以酬宿昔，道义敦所投。\n夫君工垂佐，一麾守遐州。\n踟蹰临岐路，执手野绸缪。\n王风四海同，毋曰蛮荒陬。\n君其嗣德音，慰此友生求。",""],["诸公青云器，鄙人长系匏。\n九载面石壁，烟霞与游遨。\n知匪适时韵，世网忽复遭。\n天官开胜会，满座皆贤豪。\n人豪事自胜，蓬瀛何必高。\n作者已七人，伊予惭续貂。",""],["清风东南来，阳德方在巽。\n抚己感时物，天道有常运。\n八位皆乘时，万年如转瞬。\n荣华逐飘风，柔条为煨烬。\n是形岂不坏，万有归空尽。\n何以觅真常，至道在贞信。\n敬告同盟子，无忘金石论。",""],["主人且莫言，听我歌秋云。\n逍遥望牛首，神爽已翛然。\n牛首夫何如，我尝造其区。\n坐小西南峰，蒸郁浮翠虚。\n人言秋云薄，我爱秋云淡。\n淡以明我心，薄以忘世念。\n白衣与苍狗，变态竟何有。\n此山长尊居，万化有形后。\n山高有大云，云大能施雨。\n若待春阳时，万物皆煦煦。",""],["主人如酒清，未对心先澄。\n酒似主人意，不尽来如绳。\n清宴依兰若，回席近前楹。\n江山献佳丽，乐极悄怀生。\n六朝豪俊地，风花忽飘零。\n维彼长江水，滔滔去不停。",""],["昔我游太湖，欲访洞庭山。\n匪为爱僻绝，自古多隐贤。\n翠壁浮大泽，洪涛卷高天。\n道阻不可致，怅望二十年。\n蔡生从予游，秀出西山巅。\n爱之如爱山，神爽超尘凡。\n虚无指归路，渺渺在云间。\n为我卜角里，先扫茅公坛。",""],["忆昔张公子，倾盖淮南道。\n宛宛青阳色，侃侃金玉吐。\n邂逅金陵游，抚臆道衷素。\n往来二十霜，头颅各非故。\n君今渡琼台，海岸孤绝处。\n别驾展骥足，千群看独步。",""],["三阳舒盛德，万物皆发生。\n试问胡乃尔，隆冬闭元精。\n天道专乃直，地道翕而辟。\n欲会天地心，毖之在恭默。\n小毖通神明，大毖天地贞。\n毖之复毖之，上下同流行。\n查子开名斋，独得毖之义。\n不愧此屋漏，可以配天地。",""],["中丞谢司空，书院开湖渚。\n静观山下泉，因知水来处。\n湛然涵太虚，馀波欲东注。\n湖光入帘明，照见先生语。\n逝者其如斯，自然本无作。\n一画起于无，六经皆我注。\n自以我自观，自感还我悟。\n寄语湖外人，湖源尔当溯。",""],["忆予年向立，同君西瓮闾。\n尔年方二六，志气千里驹。\n君今已二毛，我衰当何如。\n别驾展骥足，会计赴留都。\n把酒谈故旧，美恶成虚无。\n君自崇明德，爱此金玉躯。",""],["悠悠寸草心，荡荡三春德。\n亲恩比昊天，昊天元罔极。\n罔极何所思，目击双坟白。\n双坟不可见，游子沅湘客。\n泪下斑竹枝，染泪图坟色。\n于以寓孝思，孝思本无迹。\n体魄归黄壤，神理陟玄寂。\n潜思无不通，见之在恭默。",""],["晨光曜白日，宿雪倏然消。\n借问乘除理，阴阳谁与调。\n适此中和天，送君中和桥。\n此桥君自度，自度还自超。\n行行戒多岐，天路谅不遥。",""],["逋吏不逋吏，逋吏莫逋心。\n逋吏吏身洁，逋心心不神。\n不神乃滞物，天理自微灭。\n兀兀此窝中，无言自超越。\n我则何所逋，八方皆我闼。",""],["留都根本地，兵食夙告亏。\n闻有颜司徒，旋斡如神输。\n蔼蔼黄山公，画一守不违。\n后先协乃心，会计靡毫遗。\n月计一不足，岁计今几馀。\n秣马腾槽鸣，壮士歌以嬉。\n春光入报政，南风满征旗。\n幸承前席问，请进阜财诗。",""],["草树动微旭，江介清风生。\n都城尽冠盖，出饯春官卿。\n际此晴和天，矧伊皇路平。\n揽辔即长阪，去去觐朝廷。\n伯夷典三礼，夙夜惟寅清。\n会见神人协，几年南教成。",""],["君来钟山秀，君去衡山高。\n问山何以高，为有人之豪。\n山高得撑天，炼石可补地。\n君今采药行，为我重留意。",""],["五马何跄跄，朱轮何喤喤。\n青天曜白日，送子之大邦。\n钓台有清风，世远道弥光。\n为我一再拜，山高流水长。",""],["鹤泉我所慕，爱之如爱鹤。\n独立雪山高，意气轻寥廓。\n一鸣天以清，再鸣地以宁。\n去去凌紫云，对扬在王庭。","鹤泉我所慕，爱之如爱鹤。\n独立雪山高，意气轻寥廓。\n一鸣天以清，再鸣地以宁。\n去去淩紫云，对扬在王庭。"],["萧山何高高，白云何游游。\n白云有去来，此山屹不摇。\n朝出暮知归，白云为我师。\n寄语萧山灵，主人今款扉。",""],["螺川接南浦，岭雪通鸟道。\n送君归快阁，因思我来处。\n天道好乘除，有来孰不去。\n我若归西樵，访子洲之浒。",""],["潮客金陵游，邂逅谈暴虎。\n南山有白额，白日食人脑。\n嗟予几不免，藏身入藩府。\n非爱曳长裾，惴惴戒馀暴。\n地虎尚可撄，飞虎谁能捕。\n寄语虐政人，归来学周处。",""],["鲁有柳下圣，士师亦三黜。\n直道古难容，焉往而不屈。\n送君江水东，正是开笼日。\n羁鸟得旧林，安能顾俦匹。\n若过展禽祠，为我一拜之。\n身屈道弥尊，千秋映馀辉。",""],["北虏瞰天关，长廑宵旰忧。\n谁能请长缨，系取单于囚。\n挽弧射天狼，拥彗扫旄头。\n元戎十乘出，胡骑宵奔遒。\n本兵得贤佐，深沉出智谋。\n庙堂有成算，群公更运筹。\n折冲在尊俎，全功幸蚤收。",""],["负疴颓檐下，嗒然若无怀。\n清飙东南来，吹我灵襟开。\n舆浦有好音，召命从天来。\n邦储得佐理，兵食靡遗乖。\n朝廷有正人，四方无厉阶。",""],["平生子魏子，称道十年前。\n夙闻艰贞节，兼知文武贤。\n倾盖金陵下，初赋缁衣篇。\n秋风爽鸠鸣，鸾凤为鹰鹯。\n凌厉翀九霄，众鸟皆回旋。\n独自持风裁，肃肃都城天。","平生子魏子，称道十年前。\n夙闻艰贞节，兼知文武贤。\n倾盖金陵下，初赋缁衣篇。\n秋风爽鸠鸣，鸾凤为鹰鹯。\n淩厉翀九霄，众鸟皆回旋。\n独自持风裁，肃肃都城天。"],["维皇立民极，冢宰为天官。\n何名为天官，心亦如天然。\n好恶一不作，天鉴何昭全。\n君子抱明德，心学自家传。\n我素慕其人，神交倾盖前。\n一朝简帝心，四海望平平。\n山公日有启，野人献无芹。\n迹以参商隔，浩浩心同天。",""],["丈夫负志气，投笔当封侯。\n奇文抱经纬，星斗罗清秋。\n甲科取太魁，仕宦至将相。\n收身归五湖，鸿飞紫冥上。",""],["朝阳出东方，仪凤正皇皇。\n凤鸣自有时，得时为休祥。\n会看日中天，普照弥八荒。\n照见箫韶鸣，五彩成文章。\n宣尼有遗叹，礼乐空虞唐。\n何期千载下，重见春官堂。",""],["菊亦有何趣，趣之存乎人。\n花光映天地，自性求灵根。\n植根植欲深，采花采其神。\n欲辨神灵理，南山已忘言。\n我闻子云子，藏心亦云渊。\n寄语趣菊翁，难为俗人传。",""],["仰观有三光，俯察有三石。\n谁能参两间，许尔齐三极。\n三极本同原，是名为一体。\n世惟精一者，可以与于此。\n在天则成象，在地则成形。\n无违大父母，子道自完成。",""],["善权善洞府，神仙逸其名。\n嘉名吾夙慕，于兹扣岩扃。\n地气通灵窍，天神启虚明。\n谁能履兹境，可游神之庭。\n明公翕然至，如云集诸生。\n心同理有惬，景澹心自澄。",""],["圣途日芜秽，宇宙何寥焉。\n天下皆尚同，人人信其贤。\n自我抱兹独，世贤多烦冤。\n蔼蔼溪田子，倾盖独相怜。\n见嗟大科训，交契十年前。\n邂逅金陵游，载歌伐木篇。\n岂伊人事乖，聚散如云烟。\n风云安可期，见月忆同天。",""],["见君廿载前，倾盖湖西东。\n重逢每追想，惚惚如梦中。\n君才本明哲，所志在事功。\n足迹亘南北，威声动虏戎。\n功成尚久次，六七阅春冬。\n手持经济策，于以献重瞳。",""],["秋高霜露繁，木落雁南迁。\n南鹏幸相遇，息养待时骞。\n江东送司空，飞盖如云烟。\n寒江深碧流，白日曜青天。\n瞻望嗟弗及，北斗紫微前。",""],["道义骨肉爱，异姓如周亲。\n而母亦吾母，一体同戚忻。\n尊慈享善养，况乃及百春。\n即化何遗憾，而令吾戚焉。\n子爱本罔极，吾母仅八旬。\n哀哀蓼莪篇，吾宁为子陈。\n显扬乃不朽，相期未死前。",""],["牛生久侍侧，因知慈母贤。\n念长衣上线，心苦手中丸。\n曷报三春晖，愿寿三千年。\n努力显扬事，行道在尔身。",""]]});
